/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200512-7","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"厚生委員会","time":"午前１０時１１分～午後 ０時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"第３４号議案および第３６号議案の健康推進部が所管する「専決処分の承認を求めること」","agenda":"第３４号議案および第３６号議案の健康推進部が所管する「専決処分の承認を求めること」","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの数値を具体的に、何で３７０人というのが出てきたのかということで、計算の数字を出してほしいと求めました。２点、お願いします。","respondent":"池田国保医療年金課長","answer":"この１０１人というのが、およその感染者の数字ということになってまいりますけれども、およそ３.６倍の方が検査を実際に受けていると。これから予定しております後期高齢者の分というものがありますので、また決まり次第、それと併せて周知するような形を考えているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３７０人の専決の補正ということになったのですが、厚労省と総務省から出されている通知で、その点についてはいかがでしょうか。その減少した方の減免についての周知というのも、併せてしていただきたいと思うのですけれども、その点についてもお願いします。","respondent":"池田国保医療年金課長","answer":"実際には陰性の方も対象になっておりますので、レセプトだけで判断できるということは、なかなか難しいかと考えているところです。実際には６月の賦課計算に間に合うようにということで準備を進めているところですけれども、周知はしっかりとする予定で考えております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に要望なのですが、病気やけがで仕事を休まざるを得ないときに、１年６か月にわたり支給されるという仕組みになっています。加入者のうち３４％近くが給与所得者という状況に変化しているわけですから、そのことについても一言あれば、お願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"それと、もう一つが生活の保障という２つの理由で、国のほうで全市町村に要請したもので、実現したところでございました。農業をされている方ということで、健康保険とかが違った階層で入っているですので、現在のところは厳しいかということを考えているところです。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこで、まず確認させていただきたいのですけれども、この対象者が、感染した者または疑われる者というのは、ちょっと分かりにくい。確認です。","respondent":"池田国保医療年金課長","answer":"そういったものができない場合には、事業主の方の証明をもって支給することも構わないということで、Ｑ＆Ａが出ているところです。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"紙１枚でも構いません、検査を受けた方には全てお知らせができるのではないかと思いますが、まずはそういうことをやっていらっしゃいますでしょうか。やっていなければ、今日からでもやってほしいと求めましたが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"委員からのご提案は、よいご提案だと思います。既に取り組んでいるところですので、もしくは疑いのあった方については、こういった制度があるということで周知できる方法を考えたいと思います。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"課長がさっきおっしゃったような６月になってからという意味では、早めに休んでいただく、遅くなってしまうと果たせなくなってしまうと思うのです。お休みをされたら国保でも傷病手当がありますというのを書いていただくと、少しはプラスになるのではないかと思いますが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"確かにＰＲというのは一番大事なことですので、これについては前向きに進めていきたいと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"発熱が３７度７分で、コロナの感染の可能性がかなり濃厚なので、２週間自宅にいてくださいと。こういう制度がありますのでお伝えいただけたらということをしていただけると、周知にもつながるのかなと思ったのですけれども、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"では、ぜひ医師会にもよろしくお願いしたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"の順番を入れ替えまして、第３２号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の順番を入れ替えまして、第３２号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その人数が分かったら教えていただきたいのと、品川区としてはパルスオキシメータの活用というのはされないのかについても伺いたいと思います。既に退院された方の人数も、改めて分かるようでしたら説明を求めました。","respondent":"鷹箸保健予防課長","answer":"我々では把握していないのと、ホテルに入られる方に区から対応するといったスキームは、現在のところではございません。日々退院していかれるので、かなりの方がもう無事退院して、我々の療養支援対象から外れているということになります。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１台１万５,０００円で、何台購入するというのを教えていただけたら。","respondent":"鷹箸保健予防課長","answer":"おおむね５００台を想定しておりますけれども、今回購入分は１５０台を想定して、そこまでは買わずに済んだというところです。本当に全国で足りないという状況は聞いております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"引き続いてＰＣＲ検査のほうも伺いたいのですけれども、これは５月１２日、ずっと要望もさせていただいておりましたので。２６６人とお聞きしたのですけれども、４月の３か月ぐらいでこれぐらいの人数というと、ご説明いただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"その点では、それほどお待たせしているとは我々としては認識していないところで、マックス１日５０人ぐらい診ていただけております。３７度５分が４日間続くという部分がありましたが、受診対象、ここに来て設立したということになります。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから第２波、第３波、すごく評価をさせてほしいと求めました。今、やることで医療崩壊というところにもつながるのだと言われていた部分もあったと思うのですが、きちんと検査をやることで……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検査をすることで、医療崩壊を防いでいくのだというのが、今大きな世論になっていると思うのですけれども、その中でのＰＣＲ検査の考え方、対象者に対しての考え方というところでは、区としてどのように考えられているのかということについてお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"あくまでも国が出した方針にのっとって対象としていくということの後は、基礎疾患の方は２日以上ということがありましたけれども、これまでも検査はできていたと理解はしています。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ただ、目安というのが大きく変えられることによって、多分、検査をされる対象というのは大きく広がると考えられるのではないかと思うのですけれども、その点はいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今、委員ご指摘のとおり、金曜日に変わりましたので、今後は、あくまでもかかりつけ医の先生が必要と判断された方が、予約という形になりますけれども、対象についてはかなり増えるのではないかというのは、当然想定しています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当然、相談の目安から検査のほうにつながるということの拡大になっていくと思いますし、ぜひしていってほしいと求めました。予算額が６,５５９万円余ということなのですけれども、もろもろということだったのですが、内訳が分かったら教えてほしいと求めました。","respondent":"舩木保健体制整備担当課長","answer":"いろいろな今後の運営であるとか、準備であるとか、そういう運営に関わるところの人件費を４００万円ほど見込んでおります。初年度調弁を合わせた最初の一月のコストが大体２,７００万円と見込んでおりまして、全体の費用を６,５００万円余として見込んでいるところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"診察には来ないでくださいと言われて、電話で症状を聞いて、その電話で予約していただくという形もできるのでしょうかということが２点目。そこからの移送というのはどこがどういう形で行うのか、その点について、以上３点説明を求めました。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"３点ございました質問のうち、２点ほど私からお答えいたします。それが電話だけで判断するのか、そこら辺につきましては、電話相談のところも今後の流れの中では含んでいるものとしてご理解いただきたいと思います。 陽性になった方への対応ですが、まず入院して、しっかりしていただくというスキームを考えております。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"ＰＣＲ検査から伺っていきたいのですけれども、検査員の方々というのは輪番になっていくのでしょうか。慣れるまでという話があったように、毎回日替わりだとなかなか慣れが少ないのか、１人２人というか、どういう体制なのか、確認させてください。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"質問いただきました最初の２点について、私からご説明いたします。２番目の費用の負担ですけれども、国からは２分の１の補助が出るとのことですので、２分の１の補助が見込まれるです。報告方法に何度か変更とか変遷がございまして、発生届がまず出ますと、それが届いたり届かなかったりということがあった自治体もあると聞いています。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"今後の１日２０件ぐらいを目安とするとして、実数として大体どのぐらいになりそうということは、想定はされているのでしょうか。ホテル療養を選択される方は非常に少なくて、自宅療養を選択される方が多いと聞いておりますけれども、品川区もそういう状況にあるのか尋ねました。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"マックス２０という状況ではないというところも聞いておりますが、今後、対応がしていけるのだろうとは認識しております。１台だけ借り上げられたとして、引き続き検討といいますか、考えていきたいと考えています。 あるいはお子さんに関しては対応できないという前提がありますので、その方々については今後も可能性があるかもしれないということとなっています。それを考えますと、４月に本当に増えたときに、急変したときに本当に対応できるか。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは国マターだと思うので、多分、都や国にも要望されていると思いますが、私としても、区に対して要望していきたいと思います。これはドクターからも以前は、私も聞きましたけれども、そういうことはさすがに今後はないと考えていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"つまり、今年の４月１日時点で妊娠中であった方から、今年度いっぱいまでに妊娠届を出された方までが対象ということでよろしいですか。そうした方が、こうしたパッケージだけは先に欲しいとか、タクシー券を使いたいといった希望にも応えることができるのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"先ほども説明いたしましたけれども、状況把握や簡単なご相談支援といったものを専門職が行うということも、対象者の要件にはなっております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"４月１日基準で妊娠をされていた方ということは、既に出産を終えている方も対象ということになるのでしょうか。今年度中に妊娠というのは、妊娠届を出した日が３月３１日までということでよろしいのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"４月１日の基準日ということで、何らかの不利益がないような形にできると一番いいとは思っておりますけれども、はっきりしていないところもあります。３月３１日に妊娠届を出された方まで対象になるということです。","id":"exchange-021"},{"speaker":"あべ委員","kind":"確認","question":"もちろん、これから妊娠される方は、その後ということなのでしょうけれども、今妊娠中の方がいつ頃これを頂けるのかということを確認させてください。お願いします。","respondent":"榎本荏原保健センター所長","answer":"どの手段を取ると一番早くお渡しできるかをこちらも検討して、出産予定日がなるべく早い方をシステムで抽出して、なるべくスピーディーに手を打てるようにとは思っております。","id":"exchange-022"},{"speaker":"あべ委員","kind":"意見","question":"最後にしますけれども、これは知事の会見ですごく取り上げられたこともあって、来るのは今か今かと先月来、待っていらっしゃる方が大勢いらっしゃるので、見通しも併せてアナウンスしていただくとともに、早急な配布をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問・要望","question":"それから３の育児パッケージについては、郵送で基本は行われるということで、そういう方への対応について確認をさせてほしいと求めました。この場合は自宅待機なのでしょうか、こういったところへの活用みたいなところの考え方も、併せてお聞かせほしいと求めました。","respondent":"高山健康課長、榎本荏原保健センター所長、鷹箸保健予防課長","answer":"私から、休日診療における防疫用品の内訳的なところというお話をします。いわゆるガウンといったものを予定しておりまして、この間で４００組と申しますか… 郵送でお送りして、戻ってきてしまう方についてです。ほとんどの方は届くとこの場合は考えておりますけれども、どこにいらっしゃるのかということについて… ご家族のいる方については、検査を受ける前から対象者の方に、かかりつけ医からご説明していただくようになっております。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"さっきフローチャートを今日アップされるということで、そこら辺まで示された内容になっているのか、そこだけ確認をさせてほしいと求めました。","respondent":"舩木保健体制整備担当課長","answer":"フローですけれども、検査結果の判定など、陰性になった場合にはかかりつけ医から、陰性でしたというアナウンスになりますが、陽性の方については、ホテルなどでの療養であったり、中等症、重症の場合には、病院に入院であることまでの流れをお示ししたフローになってあります。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区はまだですかという話で、もう一日でも早くやっていただきたいというのが私たちのお願いでございまして、そこは要望いたします。といいますのは、ぜひこれもやっていただきたいのが、要望になってしまうのですが、こういうエラーが起こるだろうと想定されます。","respondent":"寺嶋特別定額給付金担当課長","answer":"修正は適宜かけていくということで対応を考えておりますので、郵送申請については、限りなくエラーでロスタイムがないように考えております。７月ぐらいまでかかる可能性がありますということをホームページ上でうたわせていただいて、コールセンターでもそのように回答します。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"介護・障害福祉サービスのところで伺います。要望も含めて伺いますが、これを第１弾と考えたときに、次の手。","respondent":"宮尾高齢者福祉課長","answer":"今回のこちらの業務継続支援金の趣旨は、お一人お一人に伝わるような、しっかりとその辺は工夫をしてまいりたいと思ってあります。例えばこの影響によって、それは今後きちんと事業者等々のお声も頂きながら、しっかりと見据えて考えてまいりたいと考えています。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"その辺はこれと関連して、感染拡大という点から第２弾、第３弾と、大きく事業所に対する支援が必要かと思います。その辺の見立てを最後に伺って終わりにします。","respondent":"宮尾高齢者福祉課長","answer":"今度は事業所に対するさらなる継続の支援というところで、マスクですとか消毒液といったものに対して、サポートはしています。こういった物的な支援も含めて、様々なところからお声を頂きながら考えてまいりたいと思っているところです。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"給付金についてお伺いしたいのですけれども、今日も朝８時５０分にマイナンバー関係の受付は終了と出ていて、給付金の関係が多いかなと思います。割り算していくと、郵送のほうがもはや早いのではないかと思いますが、いかがか尋ねました。","respondent":"寺嶋特別定額給付金担当課長","answer":"今、オンラインでの申請が９,０００件を超えているので、おそらく１万件ぐらいにはなるだろうと考えています。郵送の申請の一番早い方と、オンライン申請の遅い方を比べたら、郵送の方が早く着金するということも計算上起こり得ると考えています。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"３０日を過ぎても申出があれば、その方にお支払いをして、後から二重払いになった分を世帯主に請求しますというように方針が変わりました。いつ頃までそういう体制を取るのか、そして、どのような形で広報しているのかということを説明を求めました。","respondent":"寺嶋特別定額給付金担当課長","answer":"それからコールセンターでは、ご連絡があった場合については受付をしておりますので、ご相談くださいということで対応はしております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"確認","question":"事業運営も大変だと思うのですけれども、働く方にきちんと現金が届く仕組みになっているかどうかだけ確認をさせてください。あるいは決定率と言ったらいいのでしょうか、それともある程度絞られてしまうのか、その運用も説明を求めました。","respondent":"寺嶋特別定額給付金担当課長、宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"広報等も検討しているのですけれども、広報の準備が、おおむね１か月ぐらい前に原稿をある程度固めなければならない。それから… 業務継続支援金が、まさに今回の支援金の目的が、そこはしっかりと支給の際にご説明を申し上げて。週４日から５日活動していたところを、週２日から３日程度になったという形のイメージが示されているところです。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後の住宅確保給付金なのですけれども、対象が広がったということをご存じない方が非常に多いのではないかと思います。これを破綻する前に知っていただきたいという、非常に緊急性のあるものだと思いますので、引き続き周知方、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６名から１８名でされているということなのですけれども、何件ぐらいあったのかということについてもお聞かせほしいと求めました。ネットカフェ生活者に対して、区としてはどう把握して、どう対応するのかについてもお聞かせほしいと求めました。","respondent":"寺嶋特別定額給付金担当課長、櫻木生活福祉課長","answer":"お問合せの内容の８０％以上がマイナンバーカードに関することでございまして、それ以外は振込日の話とか、ＤＶ等の対応についてという状況です。あるいは連携して対応しているところで… こちらで人数は把握しておりまして、正確な数字ではございませんが、おおむね２０名前後です。日によって数字は増減するですが、おおむねこちらで把握している数字としては、そのぐらいの方々を把握しています。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、そういうところに行ってチラシで案内をしているということで、区としては対応されるということでいいのでしょうか。その周知の努力という点について、区として考えられていることがありましたら、お願いしたいと思います。","respondent":"寺嶋特別定額給付金担当課長、宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"今実際に対応している感触といたしましては、やはり１０万円という金額と、ご相談とか問合せも通常の業務に増して多いのです。… 私からは、業務継続支援金に関するお尋ねにお答えしたいと思います。そういったことを、これからも経営に対する影響をしっかりと把握していって… もともと４名体制で実施していたところ、３名ほど暮らし・しごと応援センターで従事して、応援体制を取っております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それぞれありがとうございました。そういう方というのは、そこら辺のところは生活福祉課に相談に行って、手続きを取るという形になるのかという確認をお願いしたいと思います。","respondent":"寺嶋特別定額給付金担当課長","answer":"それに対する給付ができるところまでの証明書を発行したりというところは、それぞれの専門部署と連携してやっていただいているということです。支給が可能になる方法で何とかしたいと考えていますので、区役所を挙げて、支給が可能になるように取り組んでいるところです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"実際はずっとこちらにいるという方、それから、もう住民票が抹消されてしまっているという方もいらっしゃるかと思います。それぞれについて、どういう扱いをされているのか説明を求めました。","respondent":"櫻木生活福祉課長","answer":"住民票を所管するところに状況によっては同行して、住民票を取るお手伝いをするような形で、何らかの形で住民票もしくは生活の基盤となるようなものを取れるようにサポートさせていただいてあります。","id":"exchange-036"}]},{"id":"topic-03","title":"では次に、第３５号議案、専決処分の承認を求めること","agenda":"では次に、第３５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、その減額をされたことで、保険の総額というのはどれぐらい減収になるのかということも教えてほしいと求めました。それから第３では０.２の引下げということになると思うのですが、確認をさせていただいてもいいでしょうかという、その３点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"第１段階から第４段階までを合わせまして、合計で約２万７,０００人の方が、この軽減の対象となると見込んでおります。そして、こちらもまだ見込みではあるのですが、約３億２,０００万円が今回の軽減によって影響が出るという金額と見込んでいるところです。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":47432,"voices":146}},{"id":"r02-20200512-9","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"文教委員会","time":"午前１０時１０分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ですので、所得制限を設けるべきではないと思うのですが、そこの部分の区のお考えを伺いたいと思います。品川区としても、こうしたひとり親世帯への支援が必要になるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"区はこの国の方針に従って実施しています。品川区といたしましては、ひとり親世帯に関しては、現在のところは支給支援する予定はございません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"国にも対象を広げていくようにということで求めていくことが必要だと思いますけれども、いかがでしょうか。そういった形も含めて、ぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"４月２０日に閣議決定されたことを受けて、品川区としては推進していく所存です。児童扶養手当の追加の考え方ですけれども、区といたしましては方針として従っているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童扶養手当のほうは国だと。そういったことも含めて区として考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"様々な社会状況がありますので、今、この段階では、まずは臨時特別給付金の一時金を考えて対応しているところでございまして、社会状況を踏まえて、区といたしまして対応すべきときに、しかるべきときに対応していきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、実施期間が最長６月３０日までとなっておりますけれども、いつからのものが対象になるのかということを伺いたいと思います。家賃ですとか、人件費の固定費の補助をしていくべきではないかと思うのですが、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"３月分から登園自粛に伴っての保育料の返還ということで行っておりますので、認証保育所についても同様に３月分からということで考えてあります。運営費等の支援というお話でしたけれども、運営費については、その減った分を減らすというような対応は行わないこととしております。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、この運営費支援が出ないのではないか、そういった面でも運営費補助がさらに必要になってくるのではないかというふうに思うのです。ぜひやっていただきたいと思うのですが、改めてご答弁ほしいと求めました。","respondent":"若生保育支援課長","answer":"確実に保障するという考えですので、それはまたちょっと違う話になってくるので、そこは区のほうからも適切に指導なり助言をしたいと考えています。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、固定費の補助ということを考えてほしいと求めました。利用する際にはどういう方がどちらのほうがいいのか、そういったところがよく分からなかったので伺いたいのと、伺いたいと思います。","respondent":"若生保育支援課長","answer":"事業を開始するにあたって、４月にさかのぼって適用するという形になると、償還払い方式でしか対応できないというような形になってあります。今のところ６月３０日までとなっている関係もございまして、若干、適しているほうをご案内していきたいと考えております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで、難しいとおっしゃってこられましたけれども、どのように考え方を整理されたのか、伺いたいと思います。今回、１食５００円ということで考えた理由について伺いたいと思います。","respondent":"篠田学務課長、若生保育支援課長","answer":"基本的には、いわゆる給食費相当分で考えますと食材費だけですので２４０円から３２０円と非常に低額で、なかなか１食分というのは難しいかなと。その辺りを踏まえて１食５００円とさせていただいたというものです。東京都へ届出をしている事業者という要件がありますので、その届出事業者の数ですけれども、４月現在で都内で１５０事業者あります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ３月を入れていただきたいというふうに思うのですけれども、なぜ入れないのか、伺いたいと思います。今回をまず一歩として、さらに昼食代の支援を拡充させるべきだと思うのですけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"そのときの状況を見ながら、必要に応じて、また新たに対応が必要かどうかは考えてまいりたいというふうに考えておるところです。逆に、一般的には生活支援というような考え方になってくるのかなと思いますので、現状ではすべての家庭に対する支援は考えていないものです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活支援としても、区の中での考えとして、ぜひ検討してほしいと求めました。学校がどう再開されていくかということもありましたけれども、休校の際にはぜひ広げてほしいと求めましたし、なかなか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は関連していると思っているのですが、今、休校が長期化していて、宿題だけでいいのかというふうに思います。ぜひ今後の教育活動について、受験生もいらっしゃいますので、検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう１つは、バウチャー型に若干似ているのですけれども、償還払いではないという仕組みなのでしょうか。ベビーシッターが足らなくて、申し込んでもサービスを受けられないみたいな話になるような心配はないのかという点についてお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"１事業者しかございませんで、この事業を進めるにあたっては、そこでは対応がちょっと難しいだろうというところで外しています。何も研修ですとか資格がない方は、対象となり得る方としては、区市町村バウチャー型だけで算定したところでは１４０人程度いるというような状況です。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"区市町村バウチャー型で１４０人というお話でしたけれども、都が認定した１５事業者は、それでいいのかという確認が１つ。そこについての今の予定というか、どのように区内の子育て世帯の方にご利用をご案内していくのかというところで最後にお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"当然、そこの中で先ほど言った１４０人の中にもそういった方は入ってくるというふうに認識しています。今後、承認いただいた後にホームページ等で周知するほか、当然その通っている園を通じてご案内をするということを考えてあります。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"今、少しお話があったかもしれないのですけれども、ベビーシッターについてお伺いいたします。“入所していた”という要件が必要なのか尋ねました。","respondent":"若生保育支援課長","answer":"対象者ですけれども、これは保育所等に通う児童ということになりますので、認可ですとか認証、それから認可外、そういったものを含めて、やはり“保育園に在園している”というところが要件になっているものです。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"この２つの方式ですけれども、利用者の方と相談しながら選んでいくということでよろしいのかという確認をさせてください。こちらも確認だけなのですけれども、同年３月分の児童手当の対象となっている児童であれば、これはちょっと詳しく教えてほしいと求めました。","respondent":"若生保育支援課長、三ッ橋子育て応援課長","answer":"支払いという形になりますので、通常ですと、お受けしてから早くて１か月後ぐらいのお支払いになるかというところで考えております。… 交通費につきましては、現時点では対象とはしてございません。対象外です。今回、本来は３月３１日が基準日ですので、４月分の児童手当対象となっておりまして、高校生は３月分の支給の対象となっているものです。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"すみません、先ほど、医療従事者などの保護者の方に対しても保育所が開いていないところがあるということでよろしいのでしょうか。いまいちベビーシッターを利用する方がどのような方なのかが分からなくて。","respondent":"若生保育支援課長","answer":"基本的には、医療従事者等も含めて登園ができないような方がまずメインで対象になってくるだろうというようなことで考えております。医療従事者等、ベビーシッターの利用しか方法がないというような方について、今回こういった支援をしていくという考え方です。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問","question":"新型コロナウイルスに感染している方が保育所で出たという場合の休園となると、そのほかの方は濃厚接触者にはならないのか尋ねました。","respondent":"若生保育支援課長","answer":"ベビーシッターの利用は難しいかと考えていますが、園に感染者がいた状態でも必ずしも濃厚接触者と判定されない園児もいらっしゃいますので、そういった方には利用ができるというような形になっていると考えています。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問","question":"１点だけ。国からの全員に配られる１０万円の給付金にはあったのですけれども、児童手当の対象の方で、そういった対象の方はいらっしゃるのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"そういうものの中でＤＶについても、認定するにあたっては通常から取り組んでいるところですので、通常どおりということです。ホームページ上でも「ＤＶについては」という文言は載せる予定です。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは質問ではなくて要望するのですが、それぞれ都なりで対応して、いろいろこういった施策を行っていただいてありがたいと思います。ただ、その両方を言うのは変なのですけれども、またそういった職員の方々の勤務状況を十分に反映しながら行っていただけるとよろしいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":15596,"voices":66}},{"id":"r02-20200512-5","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"総務委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"そういう中で、やはり支給がいつになるかという声をいろんな方からお聞きしました。申請書を送るのが今月の２２日だったと思いますが、目安でも結構ですので、給付時期について説明を求めました。","respondent":"品川財政課長","answer":"５月１日よりコールセンター設置等をしまして、マイナンバーカードによるオンライン申請は５月１日から開始しております。どうなるかというところですけれども、とりあえず５月末ぐらいには何とか支払いができるように、今のところ進めているという状況です。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"そういう情報をホームページで見たのですけれども、これは１日に受付できるキャパシティー、数があるそうなのです。そこを教えてもらってもよろしいか尋ねました。","respondent":"品川財政課長","answer":"委員のお話のとおり、１日の処理件数の上限が決まっておりまして、本日も朝８時５０分台という形で締め切ってしまっている状況です。どうしても処理する件数の上限というのがありまして、このような状況になっているです。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"実際に受け取るまでの間、約１カ月から１カ月半ぐらいかかるという情報がありまして、できるだけ書類申請を勧めています。少しでも混雑解消、また３密の解消にもなると思うのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"この間、今回の補正予算にも出ておりますとおり、事務をなるべく郵送扱いという形で進めているところです。委員がおっしゃるとおり、こういったところについても、郵送受付を促していくような形で周知の努力をしていきたいと考えています。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"次に、特別定額給付金の事務費のことなのですけれども、こちらは国庫支出金から出ていると思うのですけれども、これは前もって国から出された数字なのか、もしくは区から提示したものなのかを教えてもらえますか尋ねました。","respondent":"品川財政課長","answer":"事務費につきましては、区で、委託費用、それからシステム等の改修費用を試算しまして計上しているものです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"５０店舗から１００店舗未満、５０店舗未満で分かれていたと思うのですけれども、それ以外に何か要件というのはあるのでしょうか。それと、これは申請方式なのかどうかを教えてもらいたいのですけれども。","respondent":"品川財政課長","answer":"５０店舗以上１００店舗未満の商店街、５０店舗未満の商店街という形で、金額は分けてやっていく予定です。基本的には申請していただいて支給するという考え方に基づいて、事業は構築していこうと考えております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区として求めていただきたいし、この自粛と補償はセットでという視点を持って事業を展開してほしいと求めましたが、いかがでしょうか。あわせて伺いますが、区として求めるべきだと思っているのですけれども、それぞれお答えほしいと求めました。","respondent":"品川財政課長","answer":"やはりこの間、新型コロナウイルス感染症対策等については、各自治体が一丸となって対応していかなければいけないと考えております。国で補助を考えるような動き等も出てくるかもしれませんので、そういった状況も見極めながら、状況に応じて対応していきたいと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"財源確保をするという視点から、今年度から対応すべきだと思いますが、この視点についてお考えを伺いたいと思います。そうしたことの検討も必要ではないかと思いますけれども、そもそもの考え方と具体的なことと、それぞれお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"こういった部分の減収が見込まれるのではないかというところは、区としても非常に来年度予算編成に向けて危機感はあるところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"せめて当面中止ぐらい求めていただきたい。中止というのは、現状の海上ルートに戻すということを求めてほしいと求めましたけれども、最後にいかがか尋ねました。","respondent":"品川財政課長","answer":"はこういった状況も見ながら、かつ区としてどういう対応をしていったらいいかというところも踏まえながら、検討していきたいと考えています。そういうところで素早く対応ができるようにやっていきたいと考えております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"１９ページの中小企業経営支援事業費、予算特別委員会の総括質疑のときに、この制度について伺いました。どのような対応を行っているのかなど、お知らせいただけたらと思うのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"本人のいろいろな考え方等もありますので、そういったところも踏まえながら、その措置をどういうふうにやっていくかというところは対応していくです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"今までは自宅か入院かだったのが、今は入院か施設かで、自宅がないということになったと伺っています。生活が苦しくなってきた方たちにとにかく情報が届くように、細かく発信していただけたらと要望いたしますが、いかがか尋ねました。","respondent":"品川財政課長","answer":"それは、必要に応じて、ホームページ等、周知は考えていきたいと思います。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"あまり中身に入りたくはないのですが、確認だけさせていただきたいところが多少あります。さっきの答弁はちょっと危険だと思ったので、それは所管のほうといろいろ確認していただきたいと考えています。","respondent":"品川財政課長","answer":"５月末で全体のどれぐらいが出せるのかというところはまだ未定ですけれども、５月末を目途にというところでの説明です。ですので、今後もそういう各部署の状況等を、定期的に内部で報告会等がありますので、その中で状況を見て、対応していくという状況です。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"本来だったら１０分の１０あっていいのではないですか。いかがか尋ねました。","respondent":"品川財政課長","answer":"見直し、考え直し等が必要ではないかというところなのですが、基本的には財政調整基金の中で対応できるのではないかと考えております。私の説明が少しあれなのかもしれませんが、全体としては非常に、区独自のものというのは、今回の補正予算で出しております。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"延期になってしまったわけですから、「だから、ここの部分は我慢してください。」というメッセージを、しっかりしていくということが、非常に大切なのかと思いますので、これは私の要望であります。","respondent":"品川財政課長","answer":"やはり区としても、そういうところはしっかりと情報収集を行って、必要なところには早急にしっかりと対策を打っていきたいと考えております。来年度予算につきましても、そういうところも踏まえて、とにかく区民が安心するような政策を積極的に打っていきたいと考えております。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"１５ページ、４月２０日の閣議決定で、これは緊急なのになぜ専決処分にしなかったのか。例えば外注にするのではなくて職員を使ってでも、一日でも早く送るべきだったと私は思うのですが、その辺について１点だけお答えくださいとの意見を述べました。","respondent":"品川財政課長","answer":"方針といったところは、なかなか区でも、マスコミで出ている内容と同期を合わせて動いているものではないというところが１つあります。補正予算も本日出しているという中で、区としては最大限努力して、早期に給付金を出そうということで動いていたです。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"中小・零細企業、２万件あったらどうやって区で対応できるのですか。であるなら、やはり人のためになるお金の使い方というのをやってほしいのですが、その点について総合的に見解だけ説明を求めました。","respondent":"品川財政課長","answer":"制度としては、区としてしっかりと対応している動きでいるところなのですが、若干出てしまっているというところは否めないのかなと思います。事業所を支援することによって、間接的には個人を支援していくところに、今回の補正予算を出していると考えています。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"さっき伺ったのですけれど、確認なのですけれど、検討中なのでしょうか。その部分をお聞かせいただけますか。","respondent":"品川財政課長","answer":"１つ、若干ずれている部分があるかとは思いますが、動きは出ているところです。そういったところも見ながら必要性について検討して、必要があれば動いていきたいと考えております。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"５月８日時点で、申請だったか、３３件あったそうなのです。ぜひ少しでも、区として当事者の方たちの声を聞いて進めていってほしいと要望いたしますが、いかがか尋ねました。","respondent":"品川財政課長","answer":"当然、区民の声、それから状況等も考えながら、必要な施策に対しては早急に打っていきたいという考えは常に持っておりますので、時機を見て、必要であれば対応していきたいとは考えてあります。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろと議論を伺っていて、ひとり親などは、本当に困っている状況があるというのは聞いております。行政が３密をつくるような体制を、何とか工夫して解消していっていただきたいという思いがありますので、お考えをお聞かせほしいと求めました。","respondent":"品川財政課長","answer":"まさにこの間、特別定額給付金については、やはりマイナンバーカード関係のことが非常に懸念されているところです。この新型コロナウイルス感染症の時期ですから、できる限り３密も避けたような形で対応していくように努力をしていきたいと考えております。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"民間でも、かなり距離を取って、ぜひそういったところを見習いながら取り組んでほしいと求めました。５月１日、３密にならないような取組みと、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"今、各委員の質疑で確認できたところもありますので、そういったところは除きます。それは、子育て世帯の臨時特別給付金についても、どういう封筒で送るのか、新しくつくるのか、この辺をまず説明を求めました。","respondent":"品川財政課長","answer":"封筒については、現在どのように動いているか、既存のものになるか、その辺は把握してございません。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それを今、この危機的な状況で少しずつ、２％ぐらいですか、使って、今回、２１億円ということでやっている。もしくは要望だけになるかもしれませんが、現状で言うと、子どもが１人で家で勉強しているというのが実態だと思うのです。","respondent":"品川財政課長","answer":"家にいる子どもたちに対して授業等ができるかというところは、今いろいろと、教育委員会の中でも努力しながら進めているところです。こういったところも踏まえて、今後も子どもたちの食事がしっかりと取れるような形で何かできるかというところは考えていきたいと考えています。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"これが答弁でも既に前向きな答弁が出ているわけですから、感染拡大防止をやりながら一生懸命、食を提供してくれているところがあるわけです。優秀な職員の方が皆さんいらっしゃるわけですから、危機のときだからこそ、ぜひ総結集してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"積極的な予算をさらにつけていただきたいということと、国に対してもしっかり意見を述べていただきたいと要望して賛成。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":28147,"voices":60}},{"id":"r02-20200512-10","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"議会運営委員会","time":"午後 ３時２５分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1186,"voices":8}},{"id":"r02-20200518-10","meetingId":"r02-cm05","date":"2020年5月18日","dateIso":"2020-05-18","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"返事をすべきではないかということが１つと、その意見も踏まえて再検討することも必要ではないかと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前回の議運で決定した事項ですので、全会一致ということでやっております。ですから、再検討は必要ないというのが自民党の判断です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"大倉委員","kind":"意見","question":"前回の決定どおりということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、それはもう今回は皆さんで同意したということで、私はそれはいいと思います。再考を求めるということを書面に記して、そういうご説明は少しでもされたらよかったのかなという、それだけ意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"提案のときに総合審査の話がありました。では、実際に５つの常任委員会で全て出席するには５人以上の会派でなければ物理的には無理なわけで、意見を述べさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6484,"voices":24}},{"id":"r02-20200519-6","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"区民委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"の順番を入れ替えまして、２、その他","agenda":"の順番を入れ替えまして、２、その他","exchanges":[{"speaker":"こんの副委員長","kind":"意見","question":"私たち議員も、次の新しい体制に向けて、お一人お一人とまた頑張ってまいりたいと考えていますので、引き続きどうぞよろしくお願いいたします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"通知カード廃止に伴う事務の変更","agenda":"通知カード廃止に伴う事務の変更","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのですけれども、品川区で１日上限１００件というのはどのようになったかというのを１点伺いたいのと、それだけ伺いたいです。","respondent":"木村戸籍住民課長","answer":"今は、朝の７時から整理券を配りまして、何時にお越しくださいという形で、それを配って、１００が来たら終わりという形の運営をしています。郵送、行き来の感染リスクを避けるということもありますので、そういう形をご案内してまいりたいと思っています。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"変更すると周知しても、どんな手段を使ってもなかなか知ることが難しくて、分からずに窓口に来てしまうようなこともあると思うのです。それとも何年までなのかとか、そういうことは決まっているのか、教えていただきたいです。","respondent":"木村戸籍住民課長","answer":"国では経過措置というような言い方をしているのですけれども、具体的にそれがいつまでかというのはまだ示されていない状況です。おっしゃるように、未来永劫ということではないとは思っています。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問・要望","question":"やはり報道なんかでもとにかく行政のスピードがすごく求められる中で、あれ、分からない方は遅いという印象を受けられると思うのです。最大限に努力しているということも周知するべきかなと思いますし、その辺はどうなのか、お考えだけでも説明を求めました。","respondent":"木村戸籍住民課長","answer":"そういう形にはなったのですけれども、今は給付金の、いわゆるどっちが早いかというところでの取材で毎日対応しているようなところです。郵送申請が２１日に発送して、引き続き特別定額給付金担当と連携して、情報の出し方について考えてまいりたいと思います。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問","question":"すいません、期間を例えばもう少しスピードを速めるために何ができるとか、そういったところはなかなか難しいところになってしまうものですか。人を増員するとか、そういったことというのは、なかなか扱うものが扱うものだけに難しいとか、そういうことになってくるところなのか尋ねました。","respondent":"鈴木（真）委員長、木村戸籍住民課長","answer":"そこになってしまうと、部署も違ってくると思うので。答えられる範囲でよろしくお願いします。 分かる範囲がちょっと限られておりまして、すいません。そういう仕組みというのですか、チェックしてというところは報道のとおりでございまして、そこの分量はどうしても縮められないところです。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"意見","question":"本当に連日一生懸命やられた成果で、今日なんかはすごく空いていたななんて思っておりますが、またこのようなときもあるかもしれませんので、ぜひ引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"もしそういう書類でマイナンバーを求められたときに、住民票記載事項証明書、こうしたものを添付するという理解でいいのかというのが１つ。後々の窓口の煩雑さとか負担を軽減しておくということが必要かなと思うのですけれども、その２点、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"そういう申請の場面がその方々に訪れるときという部分が、実際にそれをもらってもそのときはピンと来ないという部分もあるとは思います。","id":"exchange-007"},{"speaker":"こんの副委員長","kind":"意見","question":"中身が変わったときに、その次に気がついて来る方々というのが、とかく窓口への負担がすごくかかる方が多いかなというのが予測されます。引き続きご面倒をおかけいたしますけれども、そうした対策などもできる限り頑張っていただければなというところで、意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","agenda":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今ご説明のあった無料相談窓口、最後の部分からお伺いしたいと思います。これはどのぐらいの、出張セミナーもありますけれども、無料相談窓口ということですが、どのぐらいの相談件数を予定なさっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"１日当たり十五、厳密にはなかなかお答えしづらい部分がありますけれども、需要はあるのかなと考えております。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"５月１７日付ですか、そんなことはすべきではないという趣旨の記事なのですけれども、やってあげるよというので頼んだ。持続化給付金についても考えてもいいのではないかと私は思ったのですけれども、この点、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"例えば国のほうで４００カ所以上のサポート窓口ができるというような話を聞いておりますので、十分可能なのかなと考えていますので、そういった部分までは必要ないかなと考えているところです。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問・要望","question":"要望として出しておきます。実際に融資が実行された件数はどのぐらいになっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"５月１２日に条例改正等をお願いさせていただいたときに実行件数をご案内させていただきましたが、あそこから変化は、今のところ、私どもでは把握できていない状況です。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"たしか４００件弱ぐらいだったと思うのですが、では、どのぐらいあっ旋して、全て実行されるものなのですか、結果的に。","respondent":"遠藤商業・ものづくり課長","answer":"当時５００万円だったところが多かったので、目いっぱい、まずはうちのほうでお話しされるようなことが多いと。ただ、あるいはほかの融資を受けられるとかいう部分がありますので、私どもが融資あっ旋した件数全てが実行されるというものではございません。","id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"５００万円を１,０００万円に増やし、条例改正してまで対象者を広げられて、いろいろな手だてを打たれているわけですよね。１００％というのは……、本当に１００％を目指して頑張らなければいけないというのが政治、どうお考えになりますかとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"実際にどれを使うかというのは恐らく銀行に行ってから決めるものかと思いますので、そちらに流れるという部分もありますので、そういう部分で補っているのかなと考えています。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"いや、それから結果として融資が受けられないというような相談も来たりするのですが、そういう実態をどのぐらいおつかみになっていますか。お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"今回のコロナに対してはふだんと違うような対応をするようにという通知は出ているところではありますけれども、やはり判断として、融資をしないという判断があるのかなと考えています。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"区側もつかんで、この融資あっ旋で枠をどんどん広げている、区内産業を本当に維持したいということでやっているわけではないですか。銀行だって、貸せば収入、利息として入ってくるわけですから、あるいはお金はある意味だぶついているわけですから、貸したいのだと思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"実態を把握するということは大事かと考えていますので、この辺の検証はしっかりしていきたいなと考えています。その辺につきまして、一生懸命検証して、今後につなげていければと思います。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問・要望","question":"だから、そういうことを私たちとしてはつかんでいかなければいけない。だからこそ広く融資が必要だしということだから、それを何とかできる限りやっていただきたいと思うのですけれども、いかがでしょう。","respondent":"遠藤商業・ものづくり課長","answer":"関係者からそれぞれ正式な回答という形ではないのですけれども、いろいろお話しする機会がありますので、その辺は捉えていきたいと思っています。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"品川区でもぜひこの方向を私は考えてほしいと求めました。固定費の助成ということに関して、今一度、どのようにお考えになるか、お願いいたしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"これまで私どもも様々な支援といいますか、融資の金額などを上げていただきまして、ほかの枠にないようなものを実施いただいたところです。国でもその部分についていろいろ手当をするというような話を聞いておりますので、その動向を見ながら考えていきたいと思います。","id":"exchange-017"},{"speaker":"松澤委員","kind":"確認","question":"融資の件で１つ、日本政策金融公庫などは民間の金融機関などと連携しまして、幅広く緩和をしましょうみたいな流れができていると確認しているのです。保証をする、保証人が品川区というのですか、何て言えばいいのか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"いいですか。そんなイメージを持ったもので、そういうのがあると、スピード感を持ってお金を借りられるという部分で、いいのかなという。","respondent":"遠藤商業・ものづくり課長","answer":"それをなかなかうちのほうで、区、一自治体がバックアップするというのはなかなか難しいところがあるかなと考えているところです。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"終わりがあるという中で、これから先、今後を見据えて、では、これから産業で力を入れるにはどうすればいいのか。何かそういったコロナ収束後のビジョンというのですか、そういうのはまだ全然ないものなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"事態が治まればすぐにやりたいという部分があるかと思いますので、こちらとしてもできる限りの支援をやらせていただきたいということで、いろいろ検討させていただいてあります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１点は、この申込み方法で事前予約制は分かるのですが、株式会社キャンパスクリエイトというのは、今まで区と関係があった会社ですか。その辺について、３点教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"制度を拡大した部分のパンフレットとか、少しでも多くの方が見たことないとかよく分からないということがないように努めていきたいと考えています。ご案内できませんで失礼しました、２つ、新たに設置するという形になっております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"だって、２５日、３日間あるわけですよね、２２日からやるわけですから。その辺についてお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"うちのほうで持っている創業支援センターがございまして、とにかく今回、こちらは何分急ぎでやらせていただいたと。何とか２２日から開設はできるという形になりまして、ただ、翌週からという形になってしまったような事情があるところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"とにかく課長、今回は、全体を網羅してほしいと求めました。丁寧に説明してあげて、この制度を活用していただけるようになっていただくことを本当に心から望みます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"国の持続化給付金、こういった取組は本当にありがたく、感謝する次第であります。人が足りるかどうかというのはあるかと思うのですが、そういうのも予定はしているのかというのを教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業センター１階ロビーで、場所はありますので、あまりに集中するようであれば、中小企業診断士協会とも相談という形になりますけれども、そういう場面になりましたら、増やすことも考えていきたいと思います。","id":"exchange-024"},{"speaker":"こんの副委員長","kind":"確認","question":"確認ですが、中小企業診断士の相談窓口でやる相談請負業務というのでしょうか、どこまで相談に乗るかということ。こちらの中小企業診断士のほうでもそこまでの業務を請け負っていただけるのかどうなのかというところを１点確認と、あと、確認と言いながら。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、そこの準備のところを私どもでやらせていただくというような形で考えております。こうこうこうですから、またやっているうちにご要望等あれば、いろいろ方向性なども考えていきたいと考えています。","id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"そうすると、繰り返しになってしまいますけれども、２段階と考えていいのですか。こういう２段階で、品川区は申請を希望する人にきちんと給付金が行き渡るようなサポート、支援をするという理解でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"今回お見えになる方は、パソコンの操作も慣れていないでしょうし、そもそも申請自体やったことがないという方を想定しておりますので、できるだけ丁寧に、本人がちゃんと分かるような形で、場合によってはメモなども作りながらやっていきたいと考えています。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19367,"voices":66}},{"id":"r02-20200519-7","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４月３０日までは２６６人ということで伺っているのですけれども、どう件数が変わっているのかについてもお聞かせほしいと求めました。保健所の職員が感染者が出るたびに全て調査をしてきたという仕組みでいいのでしょうかということを、改めて確認させてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"家族が４人ならと、それを全部我々常勤だけではできませんので、それも派遣の看護師たちにかなりの数をお願いして対応しています。業務量については、相当増えていたところではありますけれども、４月７日から執務室も移しまして、大幅に人数を増やして対応してまいりました。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"帰国者・接触者外来に紹介した件数は何人ですかと何回か伺っていて、紹介された人数は２６６人ですということで伺っていたのです。品川区の相談センターに来た人数のうち、この１,４７０件というのはちょっとどういう数字なのかについて教えていただきたいのが１点です。","respondent":"鷹箸保健予防課長","answer":"濃厚接触者の数は５月１３日までの数で２,３４８件になっています。家族、同僚などです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では、今後に向けても教えていただけるような情報の提供をぜひお願いしたいなと思います。第三波についての想定ですとか、それに対する対策ですとか、取組みをどうしていこうという方向だったりとかがあったら教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"保健所の件についてはいろいろ伺ったのですけれども、乳幼児健診は元々ずっと密な感じでやっていたと思うのです。具体的にどういう形でやっていくことを考えていらっしゃいますか。","respondent":"榎本荏原保健センター所長","answer":"個別健診に近いような形でなるべく実施できる体制を整えて、時間もかなり区切って、最小の人数で来ていただいてということでやる予定です。その４か月児健診を進めながら、そこも工夫しながら全体のスケジュールをうまく組んでやっていきたいと考えています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"あなたは例えばこの日の何時何分から何分の間みたいな形でやっていくのでしょうか。そうすると、何か逆に行けない方も増えてしまうのかなと思うのですが、そこら辺は何か工夫があるか説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"９割ぐらいは集まってきておりまして、それでもご連絡がとれない方には訪問に伺ってというかなりきめ細やかに対応はしております。ご都合の悪い場合は変更が一応可能な体制はとらせていただいて、柔軟に時間変更は対応できるようにしたいとは思っているところであります。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"それからお伺いしたいのが、コロナで（２）に関係してくるところでもあるのですけれども、こうした体制は続いていくのでしょうか。これはもし分かれば教えてほしいと求めました。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"今回、確かにコロナ対応で特別な通知が出されているのですけれども、これまではオンライン診療は初回は必ず面談というか診察。今回はその初回も除いていいというのは、当面の間という通知だったと認識しておりますので… オンライン診療は見直しを行うことになっています。それと新しい形で進めることになっているから、進める方向は変わらないと思います。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"ファックスなどでできるというのも、しかも郵送で送ってもらうみたいなのもあったと思いますけれども、その点はどうでしょう。それももしご存じでしたら説明を求めました。","respondent":"鷹箸保健予防課長","answer":"処方はそのまま継続というのは今までもでしたし、今後も可能かと思います。今回、自宅療養の方に対しても、継続な処方が必要な方については……。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"３日間で３５件ということで、何軒のクリニックからのご紹介だったかを一つ確認させていただいて、そのうちこういうことに参画されている方。最後に６月から荏原医師会からの参画もというところで、今の時点で分かればどのような体制になるのか、教えてほしいと求めました。","respondent":"舩木保健体制整備担当課長","answer":"先週３日間開設いたしましたところで、どのぐらいのかかりつけ医から来た結果の３５件であるとか、お調べ次第とは考えております。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと質問を忘れていたのですけれども、前回もお伺いしました妊婦パッケージ、保健センター。この間は検討中というお話だったと思いますけれども。","respondent":"榎本荏原保健センター所長","answer":"検討中と、まだちょっと未確定というところで、都からは基準日が４月１日。その話でしょうか。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"その後生まれたのはオーケーだけれども、区で何らか対象にしようと考えているという意味で受け取ってよろしいのでしょうか。基準日というのはそういう意味ですね。","respondent":"榎本荏原保健センター所長","answer":"都からの通知の基準日というのは４月１日以降、今後出産される方はもちろん来年の３月３１日まで全部対象だというところです。","id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"電話相談はもう始まって、電話での確認とかはもう始まっているということでよろしいのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"いろいろ検討して、それでうまくつながらない方とかについてはお電話でとかという形で進めるほうがよりベストだろうということで、そういった体制で進めているところです。","id":"exchange-011"}]},{"id":"topic-02","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番の工事工程の変更というところなのですが、この仕様・構造の変更がどういう中身なのかを教えてください。ちょっと確認させていただきたいのが、改めてなのですけれども、どういう施設だったのかを改めて教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらはデイサービスをやっておりまして、一般の方の通所介護、それから認知症対応型の通所介護もそれぞれ実施をしています。これは今の仮の施設でも同様のサービスを実施しています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここに仕様・構造の変更に伴う到達防護工の見直しによる補助工法の追加と書いてあるのでちょっと伺ったのですが、基本的には変わらないのに、そこがこういうふうに書いてあるのはどういうことなのかがちょっとよく分からないです。","respondent":"宮尾高齢者福祉課長","answer":"広さですとか、当初予定をしておりました内容とか、そこはしっかりと担保をしてもらえるです。工事の詳しい工法については存じ上げておりませんが、そこはしっかりと担保してくれるということは確認をしています。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"それからなかなか工事で６年間一気に延びるというのは珍しいと思うのですけれども、何かこの仮移転先の改善みたいなことの必要性をどう受け止めて、また予定があるかどうか説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"仮移転先のプレハブですが、実は今回、工事の変更が決まるのが３回目なのです。あるいは場合によっては専門家の方に調査に入っていただくとかいったことも将来的に視野に入れて進めていきたいと考えています。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"やはりプレハブがかなり長期になっていて、恒久施設よりも居住性が劣るのは確かなので、不具合を直すというだけではなくて、ちょっと今の施設の基準に合わせたようなことを考えていただけるとありがたいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"西大井三丁目国家公務員宿舎","agenda":"西大井三丁目国家公務員宿舎","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの場所は防災機能ということで防災広場と障害者施設ということなのですけれども、おおよそ半々ぐらいの面積の割合ということになるのでしょうか。土地の面積ですとか延床面積、どれぐらいの障害者施設がつくられるのかというところを教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２点目にグループホームと短期入所の人数ですけれども、想定しまして、１９人程度ということになっております。そのうち短期入所ですけれども、今のところ３名を予定しています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中で、それはどこでどう検討されていくのか、また当事者家族の声を聞く場所があるのかについても教えてほしいと求めました。区立の施設として指定管理者という形でされるのか、もしそういうことであれば、おおよそのスケジュールも分かれば説明を求めました。","respondent":"松山障害者福祉課長","answer":"現在のこちらの説明会は周辺住民に対する説明会ですので、そちらのお声も併せて頂きながら、区として検討を図ってまいりたいと考えています。状況に合わせながら説明会等、今後の用地取得についても、今年度内には実施する予定です。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地域の方に対しての説明会はもうされていますよね。団体の皆さんですとか、ここにこういう施設ができるという説明会みたいなのはいつ頃計画されているのかについて、最後に説明を求めました。","respondent":"松山障害者福祉課長","answer":"現段階では昨年の９月に周辺住民の方に対する説明会を実施いたしました。案を住民説明会のほうに出させていただいたという時点ですので、説明会についてはその時期になりましたら行っていきたいと考えています。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に一言。設計とかということに対してもいろいろなご要望とか何かもあると思いますので、ぜひ当事者。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"確認","question":"これも多分指定管理で運営をされていくことになるのか、ちょっと先ほどのやりとりがよく分からなかったのですけれども、それを確認したいのと、施設の設計よりも前なのか後なのか、それはどんな感じの順番で考えていらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"今のところまだ国の土地の取得前ですので、指定管理でいくという決定はまだ区のほうではしておりません。それから設計については、運営事業者と設計事業者ということになろうかと思いますけれども、設計の後で運営をと今のところは考えております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"まだ取得前なのでということですけれども、直営でやるということはなかなか考えづらいのかと思います。運営しやすい施設づくりという観点も必要だと思いますので、また取得後により良い方法を考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-04","title":"医療的ケア児地域生活支援促進事業","agenda":"医療的ケア児地域生活支援促進事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１つは医療的ケア児の方が通ってくる場合に、送迎はあるのかどうかについても教えてください。職員体制というのはかなり厚くすることが必要なのではないかと思うのですけれども、そこら辺の体制についても教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"それから３点目、送迎についてですが、現段階では難しいと考えています。看護師につきましては、３日ということではなくて、３日以上ということで区のほうは公募の案として求めてあります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点でいえば、なぜこの２３人ということになるのかという思いがしているのですが、その点についても伺いたいと思います。それからもう１つ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それともう１つなのですけれども、今回の地域生活支援促進事業というのは区の独自の事業ということでいいのでしょうか。地域生活支援事業として区が行うということでもないということで、丸々区の事業ということで捉えていいのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"３つ目ですけれども、区の独自事業なのかというところですが、こちらは区の独自事業ということで作ったものです。地域生活支援事業の枠組みに当てはまるのか、しばらく様子を見ながら事業の組み立てをしていきたいと考えています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、当事者の方々からの意見、こういう事業がほかの自治体でもされているところがあるのかどうなのかについても伺いたいと思います。常に介護者と運転者の２人が必要だとか、そういうことを考えると、そういう点についてはどう考えられるのかについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"３点目の送迎についてなのですが、確かに送迎のご苦労というのは非常にお声を頂いております。この状態から始めて、今後、医療的ケア児を支えるようなことのサービスにつながればと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ただ、ちょっとこれが本当に要望に合った形で実際に動き出せるようなというところは、その点について伺いたいと思います。ちょっと検討していただきたいと思うのと、これから協議会も立ち上げていくわけですから、その点についてもいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"それから２点目のアンケート調査ですけれども、確かにクロス集計をして独自にという集計については今、検討したいと考えております。ただ、そこでニーズ調査をしたほうがいいのか、またご意見を伺いながら検討していきたいと考えています。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問・要望","question":"何か取組みが今すぐは難しくても、初めからは難しくても提携という形とか、要望になるかもしれませんがご検討いただきたいというのが１点です。そういった要望もありまして、世田谷区にあるもみじの家なんかは利用面談が３年待ちだそうで、その辺りをお伺いさせてください。","respondent":"松山障害者福祉課長","answer":"使いやすい施設にするためのやはり外出サポートというご提案を頂きましたので、検討していきたいと考えています。それは事業者側のいろいろな工夫で可能になることかと思いますが、今後、公募の中で事業者側から提案を頂ければ、非常にありがたいと考えています。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"プロポーザルもまだこれからなのですけれども、こういった取組みをやるというような事業者にぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"区内の医療的ケア児はとりあえず２３人という数字が出ていたわけですけれども、これは１８歳以下の全てのお子さんと考えてよろしいでしょうか。この２３人の中で、もちろんと言っていいのか、ここに来られる方というのはどのぐらいの割合の方がいらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"２３人の方というのは１８歳以下の方です。人数的には明確にお答えはできませんけれども、全くいらっしゃれないという方はそれほど多くはないであろうと思います。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっとそれについてのお考えを伺いたいと思います。相談は予約だと思うのですけれども、利用自体はどのようにお考えか尋ねました。","respondent":"松山障害者福祉課長","answer":"こちらですけれども、全く今のままの事業がいいかどうかというのは、またお声を聞きながら工夫できるところは工夫していきたいと考えています。それから２点目の予約制なのか、兄弟の方は別のお部屋で保育をするということができないだろうかということを考えております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"１,２００万円のほとんどが人件費だと思うのですけれども、委託料の中の人件費を幾らと見込んでいらっしゃるのでしょうか。それで十分とお考えになられるか説明を求めました。","respondent":"松山障害者福祉課長","answer":"委託料は委員のご指摘のとおり、ほぼ人件費です。１月から３月の間、３か月分を見込んでおりますので、十分に可能なものと考えております。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"この数字で年間なのはあまりにもどうするのだろうという感じだったので、それはちょっと安心いたしました。そこが実施要領の中ではちょっと見当たらなかったものですから、それを加えたほうがいいのではないかと思うのですが、どのように思われるか尋ねました。","respondent":"松山障害者福祉課長","answer":"やはり相談時に医療的なケアの相談が受けられるという体制をとるためには、一定程度の経験が必要なものと考えております。ちょっと入れる文言については検討していきたいと考えています。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"ぜひよろしくお願いします。協議会との関係、それから既に動いている地域自立支援協議会との関係というのは、この施設をどう捉えたらいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"今ちょっと自立支援協議会も含めて、感染症拡大防止の観点から会議の開催は難しいのですけれども、何らかかの方法で情報共有を図っていく予定です。自立支援協議会は非常に課題の範囲が広うありますので、情報共有、連携強化を行ってまいりたいと考えております。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと話が広がりますけれども、自立支援協議会、これの議事録はいつ頃アップされるご予定であるのか。それから本年度コロナで止まってしまっている部分があるのですけれども、見通しなり教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"自立支援協議会に関してですけれども、議事録等についてはできるだけ早急にアップしたいと思っています。協議会の開催の仕方も、例えば東京都自立支援協議会ですと書面開催ですとかいったようなこともやってありますので。","id":"exchange-034"},{"speaker":"あべ委員","kind":"提案","question":"今でしたら障害がある方、当事者も参加できるという意味ではオンライン開催なども含めて考えていっていただくといいかと思います。最後は提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１年ちょっと遅れてしまっているような状況で、コロナの問題があって、医療的ケア児・者の協議会のメンバーはもう決まっているのでしょうか。そのメンバーが決まっていたら、どういう方がメンバーになっていて、何人ぐらいかということを教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"大体メンバーは２０人以内を想定しております。２つの団体から出ていただいています。","id":"exchange-036"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どうも１年間お疲れさまです。区民の皆さんや施設の要望をお聞きいただいて応えていただけたらと思いますし、区民の命と暮らしを守るために共に頑張っていけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29627,"voices":114}},{"id":"r02-20200519-8","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"建設委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません、議事進行について若干の意見とご質問があるので、発言します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"情勢の面でも変化もありまして、新ルートの運用も始まりましたし、やはり一刻も早く審査してほしいという請願・陳情者の思いもあると思うのです。すべきではなかったのかなと思うのですけれども、冒頭、今回の委員長の判断の理由を伺わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"先ほど申し上げましたとおり、聴取する順番を変更し、(2)から(4)を先に取り上げてまいります。 それでは、(2)令和２年６月都営住宅入居者募集","agenda":"先ほど申し上げましたとおり、聴取する順番を変更し、(2)から(4)を先に取り上げてまいります。 それでは、(2)令和２年６月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"後ほど区営住宅、区民住宅の使用料等の猶予および分納についての報告があると思うのですけど、こちらの都営住宅では使用料の納付期限猶予、あるいは減額や免除などの対応などそういった動きがあるのか、そこら辺、もし分かっていたら説明を求めました。","respondent":"森住宅課長","answer":"これまでも同じような制度があったということで、特段、新型コロナウイルス感染症に対応して新たな制度を設けたということは聞いておりません。猶予につきましても、詳しい条件等は手元にございませんが、そういう対応をしているとは聞いております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"区としても、都営住宅の入居者募集のお知らせをいろいろなところにするときに、従来からの制度とはいっても、こういう場合はそういった措置もあるのだということで、ぜひ区民の方に伝わるように、周知など工夫してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-03","title":"西大井三丁目国家公務員宿舎","agenda":"西大井三丁目国家公務員宿舎","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"３月１２日に、要望のとおり売払を決定する通知を受けたとありますが、これはいわゆる貸付ではなくて、売りますよということだけが通知されたのか、金額等はこれからの交渉なのか、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"委員ご指摘のとおりでして、今回、売り払うことの決定ということですので、この後、品川区だけですけれども、入札という手続に進みまして、今年度中に取得の手続を進めるという手順になっております。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区が買うわけですけれども、入札という表現になると。予算特別委員会のときも質問したのですけど、できる限り安く買っていただきたいと思っているのですけれども、一応その辺の考え方について。","respondent":"佐藤木密整備推進課長","answer":"今年度予算につきましては、木密整備推進課と障害者福祉課が約半分ずつということで計上しておりますので、その範囲で再度、精査いたしまして、入札に進むということになります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"事業説明会とワークショップは大体いつ頃の開催を目指しているのか伺います。具体的な流れというのですか、人数や想定対象者なども、教えてほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"まずは事業説明会を一度、開かせていただいた上で、希望者の方を募集します。その際は町会等を通じてご意見を頂くような形で考えておりますが、防災広場の中でどういったしつらえが必要かと、計画していきたいと考えております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"解除を待ってから周知して、まずは事業説明会ということですけれども、説明会の前に周知するということですか。昨年９月に住民に対して計画、いろいろ工夫してお知らせすることが必要なのではないかと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"委員ご指摘のとおり、昨年９月に一度、事業説明会を行っております。再度、事業説明会を予定しておりますので、事業説明会ということを予定しております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"重ねてお願いしたいのですが、どうなったのだろうということで、いつ終束するかというのもまだ見通せないところがあると思うのです。その後、報告できる範囲でやはりニュース等でぜひ地域の方に進捗などをお知らせしてほしいと求めましたし、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"品川区はそういった施設が少ないですから。ぜひ円満に、両方にとっていい施設になってほしいと思うので、その辺はどういうふうに計画されているのか伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"残ったところは防災広場として活用しようという形になって、ここまで来ております。昨年９月の説明会の際も、そういった形で地域の方には説明しておりますが、今後とも説明会等の機会を捉えて説明して。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"そういうときは、所管はもう関わらない感じですか。障害者施設のほうは障害者施設のほうでワークショップなり何なりやるとして、これは所管が違いますという話なのか、その辺を伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"９月に行いました住民説明会は、住民説明会も、両課で対応したいと考えています。ご説明いたしましたワークショップについては、防災広場についてですけれども、それぞれ連携を持って対応していきたいと考えております。","id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"両方の所管が丁寧にそれぞれ説明を行いながら、かつ連携する形で、ぜひ今後とも丁寧な説明をしていっていただけたらいいかと思います。障害者当事者の方たちも、ぜひ所管に働きかけてほしいと思いますけれども、こちらの課でもくれぐれもお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"１,６００m2の中の建蔽、それとも８００m2の中での容積、建て方が変わってくると思う。そこら辺のテクニカルな話も教えてほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"障害者福祉施設の最低要件というところから想定したものでして、まだあまりそこの詳細な部分については詰め切れていないところです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"外構でくくるかどうかは別としても、例えば８００m2にして、結構無駄なスペースができる。どうせなら防災広場も広くというのであれば、ぜひ設計や土地利用の仕方を考えていただければというお願いだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-04","title":"（仮称）品川区立環境学習交流施設の検討状況","agenda":"（仮称）品川区立環境学習交流施設の検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"少し具体的なところをお伺いしたいのですけれども、今のところの具体的な検討状況はどうなっているのかというのをまず１点お伺いします。極力こうした樹木の大きなものは残して、こういう計画は進めるべきだと思うのですけれども、いかがでしょうかというのが２点目です。","respondent":"提坂環境課長","answer":"樹木診断を行いまして、敷地内に３メートル以上の高木が４５本ございまして、そのおのおのについて診断を実施したところです。この２２本については、各棟で有効活用できないか、その辺の手法の検討を進めているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"この大きな視点というのも学習できるような施設にすべきだと思うのですけれども、いかがでしょうかというのが１点目です。戸越公園内の池・樹木を活用した工作等とありますけれども、その点での工夫などは何かあるのでしょうか、伺わせてください。","respondent":"提坂環境課長","answer":"それから過去にこういういろいろな環境上の問題が起きてきましたとか、そういうところを分かっていただくような展示とか、その辺も盛り込む予定です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"なので、新型コロナウイルス感染症対策とはいえ、やはり戸別の資料配布でいいのかなとは思います。時期とか手法は工夫しつつも、そこら辺の改善というか工夫をしていくべきだと思いますが、いかがか尋ねました。","respondent":"提坂環境課長","answer":"説明会を合同で行いたいところであったのですが、いろいろご質問とかご意見があれば個別に丁寧に対応させていただきたいと考えているところです。１２月の工事説明会、丁寧に説明させていただき、近隣のご意見をいろいろ頂戴したいと考えています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは希望者の方だけしか来ないわけですから、ぜひそこら辺は状況を見ながら工夫してほしいと求めました。区からのＺＥＢの説明があまりないかと思っていまして、ＺＥＢというのは結局どういうものなのか、もう少しご説明いただきたい。","respondent":"提坂環境課長","answer":"ひさし、壁面緑化など、熱効率のよい省エネにつながる建物計画を検討しています。地中熱の関係でご説明しますけれども、空調の省エネの対策ということで、今回の計画では地下１５メートルほどにある地下水の熱を使用する予定です。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり会ってお話をされるような場面をぜひ設定していただきたいのだけれども、そういう計画は今は全然ないのか伺いたいと思います。もう少し何か補強のご説明があったら伺いたいと思いますし、今後も進めていっていただきたいと思うのですが、その辺についてはいかがか尋ねました。","respondent":"提坂環境課長、森住宅課長、中村都市環境部長","answer":"実施設計を進めているところで、７月が工期となってございまして、説明会とかをやるということは考えられるかと思いますけれども。地球環境… 当然、まずはこの緊急事態宣言の中で、説明会についてはそういった対応をしていく。こういう理由で、説明会ではなくて戸別配布をさせていただいていますと… 説明会等のスケジュールについて、戸別配布をさせていただいた中で個別の意見があれば丁寧に対応するというところで、併せて設計作業も当然。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくこれだけのお金と手間と場所を使ってやるので、その辺はまず考えてほしいと求めました。そういう意見を出すような場面があるのか、運営事業者と協議するような場面があるのか、今後の運営について伺いたいと思います。","respondent":"提坂環境課長","answer":"令和４年４月以降に、その辺のいろいろなタイムリーな企画というのを随時、取入れていければと考えています。","id":"exchange-020"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"今度はそれが直階段になったということと、あと、以前は多機能トイレがあったのですけれども、今回はトイレが２つ。これはやはり設計上のいろいろな事情があるかと思うのですけれども、この自然換気、吹き抜けではなくなったということでよろしいのか尋ねました。","respondent":"提坂環境課長","answer":"すみません、そこら辺は私、勉強不足で申し訳ないのですけれども、前回の説明と違うということであれば、その辺は設計が変わったと思うのですが、安全管理とかその辺の問題で、屋上にあった施設を一部３階に下ろしたとかそういうところがあるとは聞いてあります。","id":"exchange-021"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"では最後に、この３階の平面図で、当初は展望テラスになっていたのです。別紙の４番目、樹木を活用した工作やクイズとか、そういうのを何か取り入れた菜園になるということでよろしいのか尋ねました。","respondent":"提坂環境課長","answer":"屋上に計画というか予定があったのですが、先ほど申し上げた理由によって、屋上に設置するのは難しいということで３階に下ろしております。平面図を見ていただくと、その横に緑に親しむ新緑デッキということで、こちらを計画させていただいているところです。","id":"exchange-022"}]},{"id":"topic-05","title":"に戻りまして、建設委員会所管にかかる新型コロナウイルス感染症の対応","agenda":"に戻りまして、建設委員会所管にかかる新型コロナウイルス感染症の対応","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"同様に減免等について検討されているということを伺っているのですが、５月という２カ月ではなくて、場合によってはもう少し長くしていただく。４月に全居住者に通知したとありますけれども、周知漏れのないようにやってもらいたいのですけれども、併せてご見解を説明を求めました。","respondent":"森住宅課長","answer":"４月の半ば頃に検討を進めまして、７月分、延長していくことも考えながら進めていきたいと考えております。国や都の動き、また委員ご紹介のあった都民住宅の検討状況につきましても情報を収集しながら、検討してまいりたいと思います。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問","question":"そういった制度があるのですけれども、使えないとすると、たしか半年後、１年後ですか、分割で分納していかなければいけないと。そこもぜひ検討すべきではないかと思うのですけれども、もう一回、併せて説明を求めました。","respondent":"森住宅課長","answer":"生活福祉課のほうで行っております住居確保給付金につきましては、区営・区民ともに活用は可能です。収入の状況に応じて減額をして、こういった住居確保給付金の案内についても、指定管理者とともに案内を進めていきたいと考えています。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問・要望","question":"積極的に、必要とされる方がしっかりと情報に触れられるように、今の住居確保給付金についても併せてしっかり周知してほしいと求めました。要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"２番の実際に自転車等駐車場の使用料の返還を申し出た方ですか、申請者数を、見込み数でもいいのですけれども、伺いたいと思います。３番目についても、実績というのですか、申請はどれぐらいあるのか、あるいは見込んでいるのか伺いたいと思います。","respondent":"川口交通安全担当課長、稲田土木管理課長","answer":"試算では現在のところ１００％で還付した場合だと、おおむね８５１万４,３００円というところです。なお、現在までですけれども、昨日現在で今のところ５４人の方が返還の申請に来ているところです。 ３番の占用料の納付期限の猶予なのですけれども、現在、これで猶予しているという物件はございません。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"それと、５番目の工事状況で、具体的には公園工事ということでしたけれども、これは何が原因で中止になってしまっているのか伺います。それぞれ休止中の業務にあたっていた従業員の方の実態というのですか、働いているのかとか、そこら辺の状況について伺わせてください。","respondent":"高梨公園課長","answer":"それと、基本的にはそちらのほうの業務をしていただくように振替えをするというような対応を取っていただくというのが一般的です。そちらに対する声かけであるとか、減るような業務もあれば、逆に増えるような業務もあるといった形で対応していただいているというのが現状です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"最後のところでもう少し伺いたいのですけれども、仕事をしておられて、きちんと賃金が払われているのかというところを伺ったのです。それとも違う業務、そういう業務をしているよということでほかの業務をしてもらって支払われるのか、そこら辺りをもう少し説明を求めました。","respondent":"高梨公園課長","answer":"願わくは６月からは一定程度、段階的に通常どおりに戻ればいいなと考えていますが、業者のほうとは話し合いを進めているところです。今月、何もないから今月の支払いはなしといったことは限りなくない形で進められるように、経理部門と話をしながら進めているところです。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。各所管のところから、手書きでやるのだったら別に印鑑はなくてもいいというふうな処理はできないのかと思うのですけれども、そこはいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"財務当局と検討して作成したのですが、いわゆるお金が絡む還付になりますので、このような手続となりました。今後、何かそのようなＯＡ化というかオンライン化でできるものがございましたら、また検討させていただきたいと考えております。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"印鑑のところはどうですか。本当に細かくて申し訳ないのですけれども、ここぐらいだったら印鑑は要らないのではないかと思うのですけれども、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"そちらの部分につきましても、印鑑の必要性につきまして今後、検討させていただければと考えています。","id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"加えて、これはＰＤＦで上げていただいているのですけれども、私も最近、字を書くのが苦手になってきて、還付の理由とかも手書きでと書かれているかと思うのですが、例えばこれをワードやエクセルで上げていただくとか、そういったことも今後できればと思うのですけれども、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"様式等につきましては、ＰＤＦで上げさせていただいたところですけれども、今後、もしワード等の様式で、どうしても手書きが必要な部分というところはしょうがないのですけれども、それ以外で可能な部分につきましては、そのような様式でできればとも考えております。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"意見","question":"５月３１日までの予定となっていますけれども、そういったことを基準にして、もう少しやるのかどうなのか。例えば同様の趣旨でそういう感謝の意を表するような取り組みを何か今後、考えられているのかどうか、この３点を説明を求めました。","respondent":"松本河川下水道課長","answer":"期間ですが、一応、今、５月３１日までということで予定しています。東京都も実施しておりまして、３１日以降、やっていくのかどうかにつきましては検討していきたいと思ってあります。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば部の中とかそういうところで１回、そういう契約関係を部の中で対応しているではないですか。そういうところを１回こういうことにしようよという話を部でして、それを例えば経理課に上げようとか、そういう動きは部の中でないのか尋ねました。","respondent":"稲田土木管理課長","answer":"検討できるものなのか、そういうもろもろのことは今現在、まさしく部内では話をしていると。経理課のほうにもそのようなことは上げていきながら、新型コロナウイルス感染症の対応としてできる部分をやっていきたいと考えているところです。","id":"exchange-033"}]},{"id":"topic-06","title":"スカイウォーク３号復旧工事","agenda":"スカイウォーク３号復旧工事","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"その確認をしたいのと、今後の事故防止対策に何か生かすようなところがあるのか、なかったのかというのをお伺いします。それと、この復旧工事の費用は幾らで、これは既に当初予算に入っているということで予算立てというのはそのような感じでいいのかも伺います。","respondent":"溝口道路課長","answer":"今回の事故の原因等を踏まえた点検等を行いながら、ほかの橋梁についても同じような事故が起きないようにしていきたいと考えているものです。復旧と併せて今後、同様の事故が起きないような防止対策といったものも含めて費用を計上しているものです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"そういう時期はまだだったのに、こういうことが起きてしまったというような感じで考えていいのでしょうかというのが１点。これはたまたま当たらなかったからよかったよねで終わりかなということがあったので、その辺どうなのか、考え方だけ伺いたいと思います。","respondent":"溝口道路課長","answer":"例えば街路樹などがありますので、その倒木に伴っては、やはり天災なので補償できないなどというのもケースとしてはあります。そういったものを管理していく上で、第三者に危害を加えないように日頃より適正に管理していく、それが大切だと感じているところです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つはやはり点検の時期と、今後のことですけれども、ぜひ想定してほしいと求めました。本当にヒヤリハットどころか、検討していただきたいという意味で申し上げましたので、もし何か見解があれば伺いたいと思います。","respondent":"溝口道路課長","answer":"そういった中で、そういったそれぞれの部会でいろいろ技術者の必要な情報の共有ですとか必要な検討、そういったものもこれまで行ってきたところです。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、今の１億１,０００万円もそうだけれども、今後、架け替えという大きなことも出てくるのではないですか。そういう部分のスカイウォークの再開発絡みの扱い方の橋梁というのはどういう契約が一番多いのか説明を求めました。","respondent":"溝口道路課長","answer":"所有は完了後、分けておりますので、それぞれの責任において何か対応しなければいけないものは対応していかなければいけない。そういった形になると考えていますし、費用負担を含めて、そこはまた再協議をして決めていきたいと考えているところです。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"景観上はどうかというのもあるのだけれども、今後こういうことがあるなら、普通のマンションだっていろいろな改修費用がかかるわけではないですか。そういうことも踏まえて、どうお考えでこういうものを選んだのかというのだけお願いします。","respondent":"溝口道路課長","answer":"ほかにも１号、２号という同様のデザインで３橋、架かっています。そこはしっかり当初から考えて、今後、どのような形で管理していくのかというのはしっかり考えていきたいと考えております。","id":"exchange-038"}]},{"id":"topic-07","title":"「品川区水とみどりの基本計画・行動計画」の改定","agenda":"「品川区水とみどりの基本計画・行動計画」の改定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"まず伺いたいのですけれども、区が緑化推進の目的の重点はどこに置いておられるのか、一度まずお伺いしたいと。それと併せて、７月から９月頃に水とみどりの課題の検討と、現時点では区としてはどんな課題があると考えておられるのかも伺います。","respondent":"高梨公園課長","answer":"なかなか今、守りながら、さらに一歩ずつみどりを多くしていくといったところを重点的に取り組んでいければいいかと考えているところです。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"区の４分の１ということなのですが、そもそものところなのですけれども、伺いたい。その中心となる施策はどのようなことを考えているのかというのも伺います。","respondent":"高梨公園課長","answer":"目標に向けて、一歩一歩進めていきたいと考えています。１つ、２３区の平均と比べても、みどりを増やすといったところは重要な要素の１つであると考えているところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に、ぜひ近隣の方にも喜ばれて、なおかつみどりが実質的に増えていくというような形で進めていくような計画にしていただきたいと。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひこの部分は進めていただきたいと思っておりまして、例えば品川区民が憩いの場所とすると、水辺からというのもあるではないですか。ここら辺のところだけは、ぜひ突っ込んで、せっかくやるのだから、いいものにしていただきたいと思うのだけれども、どうかというのだけ伺います。","respondent":"高梨公園課長","answer":"基本計画部分の総論的なもののところもしっかり検討して進めていかなければいけないと。要するに各施策をもう少しブレークダウンして考えましょうといったところ、またこの検討の中で必要な検討ができればいいかと感じているところです。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどの環境学習交流施設ですか、その辺はすごく難しくて、その中で具体的に何を重点的にやっていくのかというのはすごく難しいところだと思います。その方たちの意見は生かしていっていただきたいと、これは要望にとどめておきますので、もし何か見解があれば一言お願いします。","respondent":"高梨公園課長","answer":"それと水とみどりのネットワーク構想を踏まえて、環境基本計画、景観計画とも調和を取りながら進めさせていただきたいと考えているところです。","id":"exchange-043"}]},{"id":"topic-08","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この事業が東京都全体の計画の中でどういうような位置づけで行われる事業なのか、全体的なところをご説明いただければというのが１点です。今回の工事とそういった改善との関係があるのか、ないのかとか、そこら辺も併せてお伺いします。","respondent":"松本河川下水道課長","answer":"全体で３期に分けまして、経済的耐用年数が８０年程度あるものについて再構築するということで、第１期の再構築を進めているところです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"これを併せて行っていくというほうがいいのではないかと思うのですけれども、そういった工夫というのはできなかったのか、そこら辺については何か見解があれば伺わせてください。","respondent":"松本河川下水道課長","answer":"管の破損だとか蛇行だとか、どうしても更生ができない箇所につきましては、開削工法で入替えをしています。このうち８割が合流式の下水道管になっておりまして、今、言われたように全て分流式に替えるということになると、莫大な費用がかかると考えています。","id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"それを例えば管きょ更生ですか、その後は大体、何年ぐらいもつのかという。それで先ほど８０年と言ったこととの考え方を整理して説明を求めました。","respondent":"松本河川下水道課長","answer":"一応、経済的には３０年ほど延命ができるということで、８０年程度までには管きょを入れ替える工事を終わりにしましょうということでやってあります。","id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。法定耐用年数の５０年になる前に、内面を補強することで３０年ぐらい長くもたせて、こういうことでよろしいのか尋ねました。","respondent":"松本河川下水道課長","answer":"今のお話のとおり、法定耐用年数の５０年より３０年程度、延命しまして、経済的耐用年数というものが８０年になるように、効率的に下水道管を整備していくです。","id":"exchange-047"}]},{"id":"topic-09","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"月見橋の家の仕様構造の変更のほうが理由のように見えるのですけれども、そこら辺について何かもう少し状況、理由などをご説明ほしいと求めました。","respondent":"松本河川下水道課長","answer":"２点目の月見橋の家の仕様構造の変更に伴う到達防護工の見直しによる補助工法の追加ですが、建物の基礎構造を検討しています。で、月見橋の家の建築予定箇所まで地盤を凍らせる凍結工法というものをやってあります。","id":"exchange-048"},{"speaker":"たけうち委員","kind":"質問","question":"それで、日本で初めてとか世界で初めてとか、工法がすごいというようなことを伺った記憶があるのです。私が委員長だったような気がするのですが、そうするとその工法が予定どおりいかなかったということなのか、分かれば説明を求めました。","respondent":"松本河川下水道課長","answer":"水質ですが、今回、令和４年度中頃に、浜川ポンプ所の流域の切替えをすることで、勝島運河の水質がよくなると考えています。高潮対策の樋門と排水機場の建設ですが、当初ですと令和３年度から進める予定だったものが、令和９年度の中ごろ以降からの施工となってしまうです。","id":"exchange-049"},{"speaker":"たけうち委員","kind":"意見","question":"何が原因なのか分からないですけれども、失敗してしまったということなのだとすると非常に残念だなと思っているのです。それは仕方がないのですが、ただ、いずれにしてもこんなに延びてしまっているのでどうしようもないのでしょうけれども、そこが分かればとの意見を述べました。","respondent":"松本河川下水道課長","answer":"この工事のトラブルにつきましては先ほどご説明したように、大きなものとしては、次の月見橋の家で造るマンホールの構造がやはり複雑になったと。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4290#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46612,"voices":142}},{"id":"r02-20200519-9","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"文教委員会","time":"午後 １時００分～午後 ３時５７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症にかかる区立学校の対応と今後の教育活動の予定","agenda":"新型コロナウイルス感染症にかかる区立学校の対応と今後の教育活動の予定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"併せて、メンタル面でも不安定になっている子どももいると思うので、そういった面でも支援をしてほしいと求めましたけれども、伺います。されることがあるということは、されないこともあるのかという気がしますが、その点を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"教育総合支援センターとしましても巡回相談、またこれまでも引き続いてつながっている保護者については、ご連絡を差し上げて対応しています。ただ、基本的に学校が家庭と連携をとっているその情報が一番ですので、ここを中心に対応してまいるつもりです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでも言ってきましたが、やはりそもそも私たちは必要ないということで中止を求めております。今現在のこの状況で実施することは、今年度は少なくとも中止をすべきだと思いますけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"各学校が行える段階で、ですから場合によっては学年ごとや学級ごとの実施できる段階で、統一日ではなく実施をしたいと考えています。この場合、区で統一する必要は全くなく、そういった中での実施をして学習に活かしていければと考えていますので、実施の方向で考えているです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今年度はもう２か月進んでいないということですから、それは見られないのかなという気がするのです。やはり今、中止すべきではということで言っておりますけれども、やれないこともあるということでよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"学校が再開後、速やかに行うということで指導はしておりますので、それは統一日を設けるということではなく、という意味です。ですので、全校で実施するというものです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"少なくとも今年度は中止にすべきだと改めて強く要望しておきたいと思います。大学生がこの間授業が中止になって、区としてはそういったところをどのようにお考えになっているのか、支援なども含めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"品川区にも大学生がいるわけで、義務教育ではないですけれども、区としての考えというのは何かもっているのかというところでお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"１つ確認なのですけれども、そうした支援をやるということになったのですけれども、品川区はこの東京都の補正予算の活用ということは考えていらっしゃるのか尋ねました。","respondent":"篠田学務課長","answer":"こちらに関しましては、その補助金に対しては私どもでは手を挙げる機会がちょっとなかったといったことがあります。私どもでは提供できなかった機械をお借りすることができるですので、東京都の補助をぜひ活用させていただければと考えているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"補正予算は東京都がせっかく組んでいるものですので、使えるものはしっかりと使って、有効活用していっていただきたいと考えております。具体的なその工程というか、学習方法が、今、分かれば、教えていただきたいのですけれども。","respondent":"篠田学務課長","answer":"今回こういった流れもありまして、今後はそういった部分もきちんと基盤として整備していく必要があるだろうという認識はもってあります。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、教育委員会でやられている学習状況の成果の確認というのは、具体的にどのような形でやっているのか。ほかのご家庭との比較というか自分の位置づけといったことも情報提供されているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"横山委員","kind":"確認","question":"この２番の表の定期健康診断のところなのですけれども、こちらは新年度に毎年実施をしている内容でよろしいのでしょうか。時期は１学期中に行うということでよろしいのか尋ねました。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"学校再開後実施予定となってございまして、通常ですと４月の段階で、内科等の診断があります。今、なかなかこの時期では実施するのは難しいだろうということで、医師会からも２学期以降にしてもらえないかというようなお話を頂いていま… 基本的には学校では説明とか発表とか協議というところで学習内容を充実させて、今までのドリル学習も含め、そういう考え方でおります。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"必要な方、学校で身体検査等を行ったりする上で、必要な方は医療につないでいけるようにという配慮をぜひお願いしたいというところを要望します。何かちょっとしたきっかけといいますか、ぜひこの機会にさらに充実させていっていただきたいということも要望させていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"品川わくわくスクールの放送を５月１１日からしていきますというところで、これは各家庭はどのような形で受信していらっしゃるのでしょうか。どうやって見ているのかというところを説明を求めました。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"は消毒液を置いて、手洗いをまめにすると。密を避けるというようなことに配慮しながら、校庭と学校図書館もそうですけれども、そのようなところに配慮しながら行っていきたいと考えております。そちらにつきましては、品川ケーブルテレビをご覧になれるような環境のご家庭が半分くらいだということを理解しています。","id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"先ほどもちょっと議論があったのですけれども、特にＩＣＴの都の補助金のところで、主に通信のインフラ的なところでお伺いしていきたいのです。スマホがある、そういうものを使ってそういう授業をリモートでやると、それは補助の対象にはならないということなのかということの確認です。","respondent":"篠田学務課長","answer":"は１点目、補助の対象の考え方です。要は、我々としましてはできる限り力を尽くして、一刻も早く入手できるように今後取り組んでまいりたいと考えているところではあります。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"区が自分で、うちはこういう機械を使いたいのだと、その費用も東京都としては補助の対象になるのかというのを１点確認しておきたいのです。そういうものを使いながら、双方向のやりとりができるようにするということについてのお考えはどうか、最後にお伺いします。","respondent":"篠田学務課長","answer":"そのスパンで考えていきたいなと思っていたところではあるのですけれども、もうとりあえずあるもので対応するのがいいのではないかと。第３波が出てきたときにはきちんと対応できるような形、どういった形で対応できるのかということを検討してまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"そういったこともいつ起こるか分からないので、やはり準備はちょっと早めにしてほしいなというところがあります。教育委員会のほうで、全家庭の通信状況とかを把握するためのアンケートを取られたことはありますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"２点について答えします。１年生に向けてのＰＲをしているようなページもございまして、そのような表情を見て心が和らいでいるお子さんもいるのではないかと思っています。","id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"保護者の方からの声で、学校によって時間割も違う、課題も違う。“ここの学校はこういうことをしていてすごくいいですよ”とか、今、校長会とかで共有していたりといったことはありますかとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"特にホームページにつきましては、各学校長へ充実に向けて何度も働きかけてあります。そういった事例について話をしまして、各学校それぞれの取組の工夫を促しています。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのお子さんたちが分散登校で来たときに、これはものすごく大変だと思うのですれども、その辺りはどのようにお考えかも伺います。５月２７日に議会が開かれれば成り立つので、区立小・中学校にも２分の１でしょうか、対応するかどうか考えていらっしゃるのかという辺りです。","respondent":"矢部教育総合支援センター長、篠田学務課長、工藤指導課長","answer":"お答えできませんが、１年１組だったらその半分をＡ、考えております。部活についても、今、検討中ですが… それから、数もたくさん作られていないものですから、手に入る見込みが今のところ立っていないような状況です。対応を考えていきたいという中では… やはり講師の方を最大限活用しながら、予定していたいわゆる少人数の習熟度別指導なども効果的に行っていきたいと考えておりますので。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"品薄だから厳しいのかもしれませんが、お願いします。特別支援教室のほうは、通常ほどの回数は難しいかもしれませんが、開始していくということでよろしいのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"その予定です。","id":"exchange-017"},{"speaker":"芹澤副委員長","kind":"質問","question":"１点だけお伺いしたいです。そういった方々に対しての今後のアプローチというのは、何かお考えはあるのか尋ねました。","respondent":"有馬庶務課長","answer":"ここはしっかりと発信力を大事に、伝わるようにやっていきましょうということで５月の初めにも取り組んだところです。ここからしっかりと始めていって、区がやっている施策がしっかりと保護者にも伝わっていくように、まず努力をしていきたいと考えています。","id":"exchange-018"},{"speaker":"芹澤副委員長","kind":"意見","question":"これからいろいろ頑張るということで、施策ももちろんそうですし、思いというか、取組だけではない部分というのもぜひ保護者の皆さんに伝えていただいて、ゴールを共有しながらこの災害を乗り越えられればと思いますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"令和２年度新入学学校別増減要因一覧","agenda":"令和２年度新入学学校別増減要因一覧","exchanges":[{"speaker":"せお委員","kind":"質問","question":"私が知識がなくて申し訳ないのですが、単純にちょっと１点お聞きしたいのです。浜川小学校と浜川中学校の減要因の希望実数がすごく多いのですけれども、これは何か原因があるのか尋ねました。","respondent":"篠田学務課長","answer":"特に浜川小学校の場合は改築期間がかなり長くなることが見込まれてございまして、言ってみれば１年生で入りますと。そうしますと、もう一つは私立への入学ですとかが中学校の場合には結構影響が出てきますので、そういった部分はあるのかなと考えているところです。","id":"exchange-020"}]},{"id":"topic-03","title":"子どもの食の支援事業","agenda":"子どもの食の支援事業","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"この令和元年度の寄付金が、とてもよい結果に終わったわけですけれども、そのうちの１００万円は子ども食堂のほうの子ども応援基金に寄付しましたと。もう一つ、その５５７万３,０７３円の内訳として、この二つ以外に支出した部分があれば説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"子ども食堂の子ども応援基金に１００万円、それ以外はしあわせ食卓事業にその残額を、となっております。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"これは、対象者が２５８世帯の前回しあわせ食卓事業で食品の配送を受けた家庭と、このお知らせはどのような形で行くのでしょうか。手挙げ方式だとは思うのですけれども、どのようにこの対象となるような方々に周知をしていくのか、そこについて説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"しあわせ食卓事業の一番最初の周知方法ですけれども、１,５００世帯全体に対してお知らせをいたしました。約９０世帯分、その中で食の支援が必要だという方が電子申請して、その方に対してお米を配送するという形になっております。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"対象が新たに９０世帯というところでしたから、今の２５８世帯足す９０世帯で、上限３６７世帯までには十分あるということで、若干余分があるというところですけれども、余ったりした場合はどうするのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今回、詳細にはお伝えしておりませんでしたけれども、この９０世帯の中で、ご希望があった方は６２世帯でございました。つまり、しあわせ食卓事業としては３２０世帯になるのですけれども、それ以外の部分に関しては子ども食堂へと考えております。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっとお伺いしていきたいのですけれども、「子ども応援基金が増え、こちらは具体的にどのような形で負担の軽減が図られているのか。“１人ではないし、お米ですとか食と共に届けていただきたいと考えていますが、その辺りの考えを説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"子ども応援基金からしながわ子ども食堂ネットワークを通じて各子ども食堂に実施しておりまして、今回、３倍の１５万円ということになりました。引き続きの支援につきましては、食の支援を続けていき、その中でも支援をしていきたいと考えています。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"先ほども質問が出たのですけれども、上限３６７世帯ということで、この上限をこうした数にしたという根拠は。お米の数とかそういうことがあると思うのですけれども、どうして上限３６７世帯にしたのかというところをお知らせください。","respondent":"三ッ橋子育て応援課長","answer":"その中でたくさん寄付が入ったことによって、３００世帯以上の部分について、３６７世帯というふうになりました。そちらが上限よりも上がったこの３６７という結果となっているところです。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"確認","question":"１,５００世帯のうち、逆に言えば約２６０世帯の方しか希望されなかったのですが、その辺りについてはどのようにお考えでしょうか。皆さん、なかなか運営が厳しいとお聞きしているのですが、その辺りも確認したいと思います。","respondent":"三ッ橋子育て応援課長","answer":"第２回目、第３回目ができる可能性がありますので、何回か配送していきたいと考えています。助成上限５万円、今回からは１５万円になりますけれども、助成しています。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"何に幾ら使ったみたいな、そういったいろいろな決算報告みたいなのは、どこにどのような形で出されるのでしょうか。それだけ追加で、すみません。","respondent":"三ッ橋子育て応援課長","answer":"今回につきましては特に詳細についてはご報告しておりませんけれども、必要に応じてご報告していきたいと考えています。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。必要に応じてというのは、どこがどう必要だと思えばいいというのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"梱包代など、また配送料についてもありますけれども、商品代は今のところ約３,０００円となっております。トータルしますと、１３８万円余となっております。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話があったような配送料がどうかというのを整理できた段階で、委員会か、何らかの形で公表していただければ。今はもう数字は結構ですので、お願いしたいと思いますとの意見を述べました。","respondent":"三ッ橋子育て応援課長","answer":"今、お伝えしましたように、１回目が１４０万円弱となっておりまして、あと２回目、３回目と、できましたらあと複数回と考えております。それがすべて終わった段階で全体を報告していきたいと思いますので、よろしくお願いいたします。","id":"exchange-029"},{"speaker":"新妻委員長","kind":"質問・要望","question":"すみません、私から１点お伺いします。もしこの上限に達していく、漏れてしまった方々への次の支援策というのが、何かお考えがあるのかということをお聞かせほしいと求めました。","respondent":"三ッ橋子育て応援課長","answer":"例えば、しあわせ食卓事業の２回目に関しては、新しく転出・転入された方に関してまた周知をしてまいります。令和２年度のガバメントクラウドファンディングにつきましても、一番最初から周知して全体として募集はしてまいります。","id":"exchange-030"}]},{"id":"topic-04","title":"令和２年４月入園申込状況等","agenda":"令和２年４月入園申込状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この減った理由を伺いたいと思います。この不承諾数から先の内訳を伺いたいと思います。","respondent":"若生保育支援課長","answer":"２点目の、この不承諾数から待機児童数まで減った数の内訳です。例えば１園だけをご希望された方ですとか、それから最後は育休の延長をされた方が１人というようなことで、合計１,１６２人となっています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"待機児童数が１０人ということで、２歳児が多くなったのはなぜなのか、区で分析しているところを伺いたいと思います。この中で、先ほどの内訳でいくと育休延長は１人ということだったので、もしその辺りについて分析しているところがあれば伺いたいと思います。","respondent":"若生保育支援課長","answer":"それから、先ほどもちょっと触れたのですが、東大井・八潮地区で待機児童が３年ほど発生し続いているというところで、今後の対策です。今、事業者からも幾つか提案を頂いてありますので、区としてもなるべくエリアごとで充足できるような形で努力してまいりたいと考えております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、この１３名という待機児童数について若干名という説明がありましたが、そこも伺いたいと思います。「３歳の壁」が強まっているというのか、何と言っていいか分かりませんが、そこの区としてのお考えを伺えればと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"それから、昨年度１２名ということでいくとプラス１人でほぼ同水準に収まったということは認識しています。常々… マッチングの部分の話がありましたので、少し私のほうから答えさせていただきたいと思います。今、まずは丁寧にご案内させていただいて… こちらについては連携園を確保している部分ですので、そこで連携をとって３歳に上がるというところで、枠は十分確保できていると考えています。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"「３歳の壁」はないということでしたが、そこは今後分析していただいて、しっかりと対応できるようにしてほしいと求めました。少なくともこの待機児童数というところでは解消していかなければいけないと思いますが、改めて答弁がありましたら、ぜひ伺いたいと思います。","respondent":"若生保育支援課長","answer":"申し訳ございません。当然、今後、こちらを限りなくゼロに近づけていくという努力はしてまいりたいと考えております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"ゼロに近づけていくということで考えていくということでしたけれども、やはりゼロにするということが必要だと思います。それも含めて待機児童ゼロとして、私たちが言っている隠れ待機児童もなくしていくということでやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"２歳児、３歳児が品川地区、一応それぞれ空いてはいるのですよね。そこのところについて、もう少し詳細なご説明を頂きたいと思いますとの意見を述べました。","respondent":"立木保育課長","answer":"例えば“空きがあるのですけれども、こちらはいかがでしょうか”といった対応は、今現在もやらせていただいているところです。何かしらすべての方がよりよい方向でいけるような仕組みというのは、今後、研究していかなくてはいけないかなと考えているところです。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"“じゃあ、この方はここだったら通えるから”というようなことで、そういうやり方はできるのですか。定期利用というのは、フレキシブルに必要なところに必要なだけ定員を、定期利用の枠を設けるということはできるのか尋ねました。","respondent":"立木保育課長","answer":"できる限り、待機児童になってしまった方に関してはご案内できるような形で、毎年検討している中ではあります。","id":"exchange-037"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"社会福祉法人が１事業者参入しておりますけれども、久しぶりなのかなと思うのですが、この参入した経緯を伺いたいと思います。ココファン・ナーサリー旗の台が認証保育所から認可保育園へと移行する経緯も伺いたいと思います。","respondent":"若生保育支援課長","answer":"今回、東京に進出していくにあたり、まず１か所目として品川区にお声がけを頂きまして、昨年度からご提案いただいた中でお話を進めてきたところです。建てられる見込みができたというところでご提案を頂いて、区でも審査・検討させていただきまして、開設の予定に至ったものです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"提案","question":"社会福祉法人の参入の経緯、ご提案があってというお話だったのですが、もしもう少し具体的な理由がありましたら伺いたいと思います。今後そういった大規模な入れ替わりがないように、職員の方がしっかりと続けていける形で支援をしてほしいと求めましたが、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"話を進めてきたというような経緯以外で、私どもとしましても事業内容等を見せていただいて、今回こういった開設予定になったものです。","id":"exchange-039"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"今日の報告事項に直接関係ないのでここで伺うのですが、その方たちに対する賃金の仕組みはどのようになっているのでしょうか。区立保育園は当然全部（支給するもの）だと思いますので。","respondent":"若生保育支援課長","answer":"今回、登園自粛によって実態に応じて運営費を減らすということはないように、これまでどおりの運営費を通常どおり支給しています。保育士等の従業員に給料を支払っていただくというのを原則として考えてありますので、区としましても、指導するところではあります。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういうこともないように、というふうなところを区としてどのようにしてチェックができているか、あるいはどう確認されていくのか。要望でなるべくというお話だったので、きちんと指導していっていただきたいと思うのですが、その点についていかがか尋ねました。","respondent":"若生保育支援課長","answer":"今後、経営状況等を報告いただく部分もありますので、そういったところでしっかりとチェックしてまいりたいと考えています。運営費が減った分、給料を６割にするというような必要もございませんことから、指導してまいりたいということになります。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後にそういうお話をしていただいたので、そういった形で、事業者の方が休業している職員の方にしっかりと本来支払うべきものを支払うように、確認、チェック、指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"そうして、それに即した支援を検討していくべきではないかと思うのですが、その点を伺いたいと思います。５人に１人が退学を検討しているという結果も出ておりまして、その点について、伺いたいと思います。","respondent":"若生保育支援課長","answer":"区のほうからも補助金等、保護者への支援金等をお支払いさせていただいている部分もありますので、実態は日々こちらのほうで把握する機会があります。今後とも連絡を取り合う際に確認をしてまいりたいと考えています。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"それはあったほうがいいですけれども、答えられる方はいないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"それについて、現状、どのような形でフォローされているのかというところと、今後どうしていくのか。保育園・幼稚園にとっては非常に貴重な仕組みで、大変にいい方法で、皆様が助かっていたと思うのですが、ちょっとその点だけ確認させてください。","respondent":"立木保育課長","answer":"保育課にご相談があれば、きちんとしかるべきところとやり取りをさせていただいた中でしっかりと対応させていただいているというような状況です。幸い、今のところ重大案件というのは起きておりませんので、引き続き丁寧にフォローしていきたいと考えています。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46135,"voices":137}},{"id":"r02-20200519-5","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"総務委員会","time":"午後 １時００分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"東京都の緊急事態宣言がどうなるかはまだ分かりませんが、この両立の議論が始まっているのだと思います。品川区では１２日からＰＣＲ検査センターを開設しておりますけれども、こういう視点についてはどのようにお考えなのか伺いたいと思います。","respondent":"立川総務課長","answer":"本日の厚生委員会のほうで説明をされている内容ですが、やはり発熱や具合が悪い等でかかりつけの先生にご相談されている方は多数いらっしゃいます。昨週も３５件の検査申込みがあったということで、これからの経済の再開に向けて大変重要なことだと認識しています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"という気持ちもよく分かるのですけれども、受診そのものが減って、医療機関の経営も苦しくなっていると伺っております。品川区も品川、こうした医療機関への抜本的な財政支援というのが急がれているのではないかと思うのですけれども、併せて伺いたいと思います。","respondent":"立川総務課長","answer":"医療機関への支援については、国や都を中心に実施しているというふうに考えているところです。ご質問の直接支援ですが、こちらは各所管において必要な対策については検討を進めていく必要があるというふうに認識しています。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"なぜこのような質問をするのかというと、しかも近隣の方からは、むしろ公表してみんなに注意を促してほしいといった声が寄せられています。ぜひきちんと公表をして、みんなで感染について注意をしていくといった方向に進むといいなと思うのですが、その辺の考え方を伺いたいと思います。","respondent":"立川総務課長","answer":"ＰＣＲ検査センターのご質問につきましては、厚生委員会が所管ですので、回答は控えします。保育園の休園に関する園名の公表につきましては、感染された方、また周辺にいらっしゃる方のプライバシー等を配慮して、公表しないという方針です。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"特にＰＣＲ検査センターをせっかく品川区で開設したのですから、今は東京都のホームページに行かないと分からないではないですか。せめてそれぐらいでも確認できるように、もうちょっと公表に向けて要望したいと思いますがお考えを伺えたらと思います。","respondent":"立川総務課長","answer":"感染者数の公表につきましては、東京都のホームページに毎日最新の情報が載っておりまして、品川区のホームページにおきましても、そこのリンクを張らせていただいておりますので、人数の確認についてはできる状況です。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、そういった部分の公表をしてほしいなと要望したいと思います。品川区全体として、区有施設等の再開の目処はどのように考えられているのかなといった現在の状況についてお伺いできればと思います。","respondent":"立川総務課長","answer":"緊急事態宣言が解除された後の対応ですけれども、区といたしましては、現状の施設や事業について、いわゆる一遍に開くとかということではなくて、段階を踏んで徐々に開くといった方向で、今検討している状況です。","id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"再開に向けての検討が始まっているのは分かりました。第２波、第３波が来たときに、区としてつくられているのかという部分をお知らせくださいとの意見を述べました。","respondent":"立川総務課長","answer":"国の基本的な対処方針ですとか、東京都の方針ですとか、その辺を勘案いたしまして、区としての方向というのを決めていく必要があるというふうに考えているところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"１つ簡単に確認なのですが、１５日、全然違うページへのリンクだったのです。１８日には「間違いでした」というのが流れてきたのでよかったのですが、何か焦ってしまったのか、その辺の状況は分かりますか。","respondent":"大澤広報広聴課長","answer":"リンクするページを誤って張ってしまいました。今後、このようなことがないよう、細心の注意を払って周知していきたいと思います。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"いろいろ、手違いはあるかと思いますが、確認のほど、よろしくお願いします。独自でいろいろ、実情に合わせた解除方法、対策というものも必要なのかなと思うのですがいかがか尋ねました。","respondent":"立川総務課長","answer":"基本的には国の対処方針であるとか宣言であるとか、そういったものをベースに、各都道府県知事が、その自治体ごとの対応というのを検討していく。それ自体につきましては、国や都の方針等と齟齬がないように、バランスを取りながら決めていく必要があると考えているところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"全体を動かすのであればもちろん、国の施策があって、東京都に下ろされて、東京都が最終的な判断というふうになっていると思うのです。どうしていくのか、では品川区の権限はないのか、品川区は何ができるのかというところはいかがなのか尋ねました。","respondent":"立川総務課長","answer":"新聞報道ですけれども、基本的対処方針の読み方の解釈がそれぞれ異なっていたというふうに聞いているところです。国の基本方針であるとか、東京都の要請であるとか、そういったものを全て勘案して判断していく必要があるというふうに考えているところです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"なので、こういうところは品川区は早く解除しなければいけないとかは、実情に合わせた形でやっていかないといけない。いや、品川区はこういう対策を取っていくから独自でやるよというところが言えるのか、その関係はどうか尋ねました。","respondent":"立川総務課長","answer":"例えば飲食店の営業規制でありますとか、また区民の皆様への外出の自粛要請であるとか、こういったものにつきましては東京都全体で統一的にやるべきものだというふうに考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"今度は第２波というのが秋頃来るのではないか、もちろん都の考え方は参考にするも、やはり品川区の現状というのは把握していかなければいけない。それだけでは今後済まないのではないですかということを、ちょっと強く言わせていただきたいなと思いますので、ご検討のほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"今現在、封じ込めで、自粛、規制ということで動いていますけれど、このままずっと続けるおつもりなのでしょうか。都の言われるとおり進めていかざるを得ないのか、区としてどういうふうにお考えなのか、説明を求めました。","respondent":"立川総務課長","answer":"これが２大方針というか基本的な対策の目的ですので、方針、区として対応を決めていく必要があるというふうに考えているところです。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"半年でなくす、１年でなくすわけにいかないではないですか。解除できる手だてを区のほうでも示すべき時期なのかなと思うのですけれど、その辺について、再度ご見解を説明を求めました。","respondent":"立川総務課長","answer":"委員にご指摘いただいた、やはり新型コロナウイルス感染症と一緒に生きていくといった社会をこれから形成していく必要があるというふうに考えておりますので、区としてどういったことができるのかというのは検討を進めていく必要があるというふうに考えているところです。","id":"exchange-013"},{"speaker":"小芝委員","kind":"質問","question":"1)ホームページの４つ目、「感染者等に対する」という言い方で、中国というふうに特定の国を限定していないのです。これは何か、限定している理由は、いろいろとありますけれども、教えてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"今まで外国人に対する差別発言等が当区におきましてもございましたので、それを踏まえながら書かせていただいたです。医療従事者の方に対する差別に関するところにも飛ぶようにできておりますので、今後も検討させていただきたい課題だと考えているところです。","id":"exchange-014"},{"speaker":"小芝委員","kind":"質問","question":"ちょっとマスクをしていない方だとか、この非常事態宣言の中で、例えば夜８時以降営業されているお店もあります。そういう形で、そういう例も報道レベルでは僕も知ってはいるのですけれども、品川区で実際にそういった例というのは今まであったのか尋ねました。","respondent":"島袋人権啓発課長","answer":"人権啓発課のほうに頂く問合せ等ではこのような件はございませんでした。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれど、品川区ＰＣＲ検査センターのさっき聞いたご質問の中で、これから品川区のホームページでの情報提供というのを考えているのかどうかという部分を確認したいと思います。","respondent":"立川総務課長","answer":"所管に聞いた話では、検査状況の公表というのは特に考えていないです。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"今、検査状況の一覧、検査の流れが出ているではないですか。せっかくＰＣＲ検査センターを持ったのですから、品川区での状況というのは公表されるべきだと思うので、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"新型コロナウイルス感染症に関しての質問がいっぱいあると思うのですけれど、それをホームページのほうで書いてあるところはないのでしたか。質問がいろいろと出てくると思うのですけれど、新型コロナウイルス感染症に関してまとめたものというのはなかったのでしたか。","respondent":"大澤広報広聴課長","answer":"一般的なＱ＆Ａは各ページに載っている場合もあるのですけれども、まとめてというのは今のところ、ページとしては作っていません。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"新型コロナウイルス感染症に対しての質問はどこが集約しているのですか。それぞれの所管になるのか尋ねました。","respondent":"立川総務課長","answer":"例えば経済的なものでしたら商業・ものづくり課でありましたり、検査等といったことですと当然保健所のほうです。よく聞こえないだとか、最近よく聞こえるようになったとか、そういったご意見については総務課のほうで承っているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"今後緊急にやってほしいのです。どこに聞いたらいいか分からないというのがあって、つながりやすいかなと思うので、それの検討を早急にお願いしたいと思いますがいかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"前向きに検討します。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと確認だけさせていただければと思うのですが、４回までは報告を伺って、その状況について教えてほしいと求めました。現状判断をされているのかどうかというところで、各部署に流れていくのかなと思うのですが、その辺の流れについて確認をさせてください。","respondent":"立川総務課長","answer":"２月３日に設置しまして、第１２回の対策本部会議というのが昨日５月１８日、実施されたところです。対策本部会議の中では、報告事項と、また付議事項といった式次第に従いまして、今後の方向性等を議論し、決定をしているといった流れです。","id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。もう１２回やられていて、いろいろなところから情報を取りながら、ありがとうありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-02","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"田中委員","kind":"質問","question":"変更後は令和９年の中頃で、差が６年間もあってとても大きいなと思ったのですけれど、イメージとしてどういう感じなのですか。私も工事が全然分からないので、イメージが湧かないのですけれど、こんなに変わることというのはあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"これ、予算はどうなっていくのか。いろいろなものがあると思うのですけれど、もう関係ないですよ、という認識でよろしいか尋ねました。","respondent":"島袋人権啓発課長","answer":"確かに都の工事ですので、予算に関しましては東京都のほうが責任を持って進めるということを伺っております。かなり長引く仮移転、工事あるいは不備な点に関しましては予算要求をいたしまして、設備を整えていっていただくという流れになっているところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"そうすると、予算書や決算書などにこれも入ってきますよ、という認識でよろしいのか尋ねました。","respondent":"島袋人権啓発課長","answer":"こちら、全て東京都の持ちですので、区の予算書の中にはこの項目は入ってこないと考えております。","id":"exchange-025"}]},{"id":"topic-03","title":"スカイウォーク３号復旧工事請負契約","agenda":"スカイウォーク３号復旧工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"どういうふうにして壊れたのか、何かぶつかってどうかしたのか分からないのですが、その辺について分かる範囲で説明を求めました。","respondent":"東野経理課長","answer":"支持力、支えている力が弱まったので、パネルが落下したというふうに聞いてあります。特に施工上の問題ではないというふうに聞いております。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"私の見解では、どうしても我々が見る限りでは、施工が悪いように感じたのです。は中身までちょっと分からないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"契約の相手側なのですけれど、今回江東区の企業になっているのです。品川区の事業者が多かったかなと思っていて、今回広げての入札だったのか、その辺の経緯はいかがか尋ねました。","respondent":"東野経理課長","answer":"こちらにつきましては、公告している入札参加資格、それから入札参加条件に一致しているという業者になります。ですから、品川区以外の業者もこれについて入ることができる、そういう案件です。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"品川区外の事業者がここに加わることができる条件というのは、例えばどういう条件だと入れるのか尋ねました。","respondent":"東野経理課長","answer":"品川区の業者に限るというふうに記載しているものでなければ、品川区外の業者でも入ることができます。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"それは分かるのですけれど、今までは結構品川区の業者が多かったのかなと思っているのですが、品川区内のということを外すことのできるケースと、外せないケースというのはあるのか尋ねました。","respondent":"東野経理課長","answer":"それぞれの案件によりまして、判断しています。品川区の施工業者だけですと、この入札に呼ぶ対象が絞られるとか、そういうものになりますと、品川区外の業者も入れるということも想定しています。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ただ、私はどうしても品川区にという固執をしているわけではなくて、事業者のいろいろな特徴があると思うのです。私の印象だと、品川区の事業者、というのが強かったかなという思いがあるので、その辺はいかがか尋ねました。","respondent":"東野経理課長","answer":"品川区内の業者がどの業者でもできるようなものであるという前提であれば、そういった形での入札公告をするということがあります。やはり一般的なところというよりも、少し特殊な工事という部分もありますので、そこは対象を広げて公告をしたというような状況です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"そうすると、解釈の一つとしては、品川区内の事業者の特徴を区のほうはよく知っていますよと。なので、ある程度は把握をしていて、その案件ごとに品川区内に限定するのかしないのかと決めているということなのか尋ねました。","respondent":"東野経理課長","answer":"その中でも対象となる業種が絞られてきますので、それに合致した業種での申込みをしなければいけないということになります。ですので、その工事に対してほかのところでの実績があるかといった部分で結果のほうで判断していくです。","id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"最後に、品川区内、区外を問わず、いい施工をしてほしいというのがあります。私の考え方は、広くいい施工をするところを、こういう入札などについてはある程度広げられるだけ広げてほしいなという思いがあるのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"新型コロナウイルス感染症に関わって１点伺いたいのですけれども、いろいろな判断の上で現場が止まっているという話をよく伺うのですけれども、伺いたいと思います。","respondent":"東野経理課長","answer":"新型コロナウイルス感染症対策に係りまして、施工中の工事が一時中止しているというものが、４月、５月の段階で実は品川区内でもありました。５月６日の再開という形になっておりますので、一時中止をしていたものにつきましては、皆再開をしているという状況です。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"何とか現場が感染症対策に照らしても安全に、そして工期どおりに進むようにというのでしょうか、そういうふうに進めていただきたいと。それが地域経済にも関わってきますので、その点について一言伺いたいと思います。","respondent":"東野経理課長","answer":"工期の見直しですとか、それから現場の体制の見直しといったものに係る契約変更等を行っていくような形になろうかと思います。国のほうでは、雇用調整助成金が現在検討されているところですので、業者のほうと十分な調整を図るように所管のほうへは指導していきたいと思います。","id":"exchange-035"}]},{"id":"topic-04","title":"品川区東五反田五丁目付近再構築工事請負契約","agenda":"品川区東五反田五丁目付近再構築工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問","question":"入札のときに技術者の配置だったりというのが計算できるかは、なかなか難しいものなのですか。４つの事業者の中で３つの辞退が出るというのが、どうしてなのだろうというのを思ってしまって、お答えいただけますか。","respondent":"東野経理課長","answer":"積算金額が予定価格を超過したという部分ですが、一般競争入札につきましては予定価格を公告の際に事前公表しております。この案件については、４社応札のうちの３社辞退というようなことになりましたけれども、そういった現象が起こる場合もあります。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"要望として訴えているのですけれど、この予定価格の算出方法について、ざっくりとしたものでもいいので説明資料として出してほしいなというのが１点。この場で伺うのではなくて、ぜひそういうことを、もう少し詳しい説明を求めたいと思いますがいかがか尋ねました。","respondent":"東野経理課長","answer":"これらの算出にあたりましては、委員会資料の中で予定価格までのものにつきましては出していないのですけれども、今後検討してまいりたいと思います。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"そうなったときに、品川区内の事業者の中である程度こういう事業ができるよというのは、品川区内では大体この４社なのでしょうか。いかがなのか、そういう状況は専門ではないので分からないところはあるかと思うのですけれど、いかがか尋ねました。","respondent":"東野経理課長","answer":"この４社の中での下請にかかる技術者についてというところでは、この契約の段階で何か分かるようなものというのは特に持ち合わせていないものです。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"市場に合わなければ高くしなければならないのではないですかというふうに言いたいところではありますけれども、その辺はいかがなのか。今回も品川区に限定されているのか尋ねました。","respondent":"東野経理課長","answer":"それから品川区の中での下水道事業という部分で、品川区の区内業者での対応を、ということが求められているものです。もっと業者を、ということであれば、発注課ごとの調整は進めたいと思います。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜここに辞退がこんなにあるのかなというところは、何でこんなに辞退があるのですかと、見た感じだと非常に不自然です。そういうことも含めて、辞退者があまり出ないような形で今後も検討してほしいと求めましたが、その辺のご意見をお聞きして終わりたいと思います。","respondent":"東野経理課長","answer":"区内業者育成という部分で、区内の業者を使ってということを念頭に置きまして、これまで契約のほうを進めてきたというところがあります。その点につきましては、区外の業者を入れるかどうかの判断をどの時点でするかということも含めて、今後検討してまいりたいと思います。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そこまで区のほうは知っているのでしょうか。１５０ミリ、２００ミリと仮に大雨の場合に、そういう情報というのは区のほうにも来るのか尋ねました。","respondent":"東野経理課長","answer":"経理課のほうで聞いている範囲でお答えしたいと思います。５０ミリ以上の雨が降ってというような、そういったところについて東京都と十分な調整をしながら、改修事業を進めているというふうに伺ってあります。","id":"exchange-041"}]},{"id":"topic-05","title":"(6)債権の放棄","agenda":"(6)債権の放棄","exchanges":[{"speaker":"西本委員","kind":"質問","question":"その違いは何ですかというようなときに、金額にもよると思うのですけれど、間違ったものはしようがないねと。その辺はどういう状況だったのかなというのは非常に気になるところなのですけれど、知っている範囲で。","respondent":"中山会計管理者","answer":"実際に支給された金額と違う金額が算定されたときには、やはりお戻しいただくべき金額は戻していただくというのが基本になると考えています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"今の時期だから４年か５年くらい催促を行っているわけではないですか。こういう形になってしまうわけですから、その人のためになるのかなというふうに思いますので、今後いろいろ配慮していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-06","title":"令和２年７月５日執行東京都知事選挙執行要領","agenda":"令和２年７月５日執行東京都知事選挙執行要領","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、鉛筆とシャープペンシルの持参と書いてあるのですけれども、単純にボールペンは駄目なのですか。ちょっとそこを不思議に思ったので、ご説明ほしいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"筆記用具の指定というのは特にございませんけれども、ボールペンの場合は、投票用紙が今、プラスチックなので、乾きが遅いのです。広報にはその旨、かすれて読み取れない可能性があるので、鉛筆をご使用くださいというような趣旨の注意書きを書く予定です。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"そうだったのですか。でも油性のものもあるので、もうちょっと説明していただけますか。","respondent":"秋山選挙管理委員会事務局長","answer":"水性のボールペンはなかなか乾きが遅いので、こすれる可能性が高いというふうに言われています。インクの乾きが遅い物についてはそういう可能性があるということで、ご説明をさせていただいています。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"それから、選挙人同士の間隔を概ね１ｍ確保ということになると、結構幅を取ると思うのです。結構ぎちぎちなところがあるのではないかと思うのですけれど、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"その辺は、期日前投票所も有効に利用して、密にならないようにというアナウンスはしようということになっております。１ｍの間隔なのですけれども、投票所に入るために並ぶときに１ｍ間隔で並んでいただいて、その辺の運用で対応させていただきたいと思います。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"今回の新型コロナウイルス感染症は治療に結構長くかかります。病院でという方々がいらっしゃると思うのですけれど、その人たちの投票というのは何か工夫をする予定はありますか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"病院にいますので、ほぼ指定機関になりますので、病院での投票ができるのではないかというふうに考えております。どのような方法があるのか、それを見ながら、適正に対応したいというふうに考えております。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"新型コロナウイルス感染症の話もそうですけれど、自分はどこで投票できるのだろうかなどというのが心配になると思うのです。照会しているということなので、告知の方法も含めてしっかり対応を取っていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"小芝委員","kind":"確認","question":"選挙公報のところでちょっと確認したいのですけれども、投票日の２日前、どうしても行き届かないケースがあるかもしれないのです。これまでに、直近の選挙でもいいので、そういった事例があったのかどうか教えてもらえますか。","respondent":"秋山選挙管理委員会事務局長","answer":"選挙公報ですけれども、一応今のところの予定では２４日か２５日には配布を終了するというような想定で動いております。実際に届いていないということであれば再度届けるということで、ご連絡を頂ければ、３日前と書いてありますけれどもその期間で対応しています。","id":"exchange-049"},{"speaker":"小芝委員","kind":"質問","question":"それこそ投票日の前日の、例えば土曜日でも、もし届いていないというのであれば業者のほうにお願いして、すぐにお届けできるような、そういった仕組みというふうに考えておけばよろしいか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"土曜日の対応まではちょっと確認はしていないのですけれども、平日であれば確実に対応します。","id":"exchange-050"},{"speaker":"つる副委員長","kind":"確認","question":"エレベーターの中の密を避けるとかそういう対応、対策も当然必要になってくるであろうなと考えられるので、そういう部分の配慮の確認。もう少し、区役所の中に入ってすぐ出られるという動線の確保というのですか、何かほかに適所というのがあったのではないかなとはちょっと思うのです。","respondent":"秋山選挙管理委員会事務局長","answer":"前回の都知事選挙が３時５５分だったかと思います。ですので、それぐらいで終了するだろうというような想定はしております。","id":"exchange-051"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明いただきたいのですけれども、内容が説明では分からなかったので、もう少しご説明いただきたい。２回送ってしまった相手が何か手続きをしなくても、ちょっとそこの組戻の仕組みがよく分からなかったので、ご説明ほしいと求めました。","respondent":"中山会計管理者","answer":"２度目の振込、これは間違っていますので組戻をしたいということで、ご連絡が行きます。その上で、お客様のほうで書類にちょっと書いていただく必要がある、そういうような手続きになります。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、間違ってしまったことは間違いですけれども、その回収はどこまでできるのか。その辺はどういう見通しなのか、非常に気になるところなのですが、最後にもう一度ご説明ほしいと求めました。","respondent":"中山会計管理者","answer":"既に返ってきた８億５,０００万円だけではなく、あるいは口座振替をしたいので、というご連絡も頂いております。債権者登録の方が多いという中では、おわびとともに手続きのご協力ということで、全額回収していくということで頑張っていきたいと考えています。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望ですけれども、やはり事故の規模としては約１４億円と大きいものでありますので、組戻の一定のめどが立った時点で、改めて総務委員会に終了の報告となることが一番うれしいわけですけれども、報告をしていただけるよう要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"ただではないと思うのですけれど、それはどのレベルになりますか。それは全部こちら持ちという、一般財源から出ていくのだろうと思うのですけれど、どのぐらいのレベルか尋ねました。","respondent":"中山会計管理者","answer":"組戻の金額というのは区と指定金融機関とが結んでいる契約によります。今、１件４５円ということになっております。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"は振込料は別途、そうしたらまた振込料がかかるなと思って、そこはどういう仕組みになっているのか尋ねました。","respondent":"中山会計管理者","answer":"口座振込につきましては、ネットバンキング等で手数料のかからないお客様、そうしたお客様用に返金の方法として残しているようなところです。先ほどの、仮に５０７件全部が４５円の手数料がかかったとすると、２万２,８１５円の手数料が区の負担になるです。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"本当にこの事故の経緯、どうしてこのようなことが起きたのかといった、その原因をきちんと明らかにしてほしいと要望いたします。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"つる副委員長","kind":"確認","question":"いろいろ見て確認すると、でも１件４５円かかるということは理解したので、今現在の３６２件のうちの債権者登録と随時というものの内訳の件数というのは分かりますか。","respondent":"中山会計管理者","answer":"随時が全部で２９件あるのですが、随時のうちお戻しいただいた分が２６件ということになっております。２６件が随時で１回限りのお客様で、こちらのほうにご返金いただいたということになります。","id":"exchange-058"},{"speaker":"つる副委員長","kind":"確認","question":"当然対象金額というのでしょうか、見込みというのですか、なかなかそれはないと思うのですが。先ほど、分析という、何か非常に高尚な表現があったわけですけれど、日常のそういうチェック、確認のところは行うと。","respondent":"中山会計管理者","answer":"今回のヒューマンミスだと考えていますので、やはり事実としてすごく重たい、データを送信ということはすごく緊張もしますし重たい作業になります。","id":"exchange-059"},{"speaker":"田中委員","kind":"確認","question":"さっき確認し忘れてしまったのですけれど、ご説明の中にもしあったらごめんなさい。この事故が分かったのはいつ、何日だったのかというのを説明を求めました。","respondent":"中山会計管理者","answer":"事故の発覚というのは、実際のところ４月３０日に振込が２件されていますという事業者からのお知らせによるものです。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"私１年間総務委員会にいて、その他の最後のところでご意見をお聞きしたく、発言をさせていただきました。委員長、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":41260,"voices":155}},{"id":"r02-20200520-14","meetingId":"r02-cm05","date":"2020年5月20日","dateIso":"2020-05-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと議事の運営について意見と、あと質問を１点だけさせてください。今回、なぜ陳情審査を見送るという判断をされたのか、理由だけお伺いさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":2663,"voices":13}},{"id":"r02-20200522-18","meetingId":"r02-cm05","date":"2020年5月22日","dateIso":"2020-05-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時４５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"東京２０２０大会に向けた機運醸成ＰＲ動画","agenda":"東京２０２０大会に向けた機運醸成ＰＲ動画","exchanges":[{"speaker":"つる委員","kind":"質問","question":"何とか元気になるのかなという第１段階の希望が少し見えてきたところかと思いますし、いろいろな機会も含めて、地域も知恵を絞ってやっている。例えば３キャラクターにマスクをさせて登場させるとか、その辺りの企画とかは現状、お考えの中にあるかどうか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"コロナが広がる状況の中で、なかなか大きく大会に向けてというＰＲは、今は難しい時期だと認識しております。ここぞというときになったら、また再開できるようなことを願って、今の活動をしています。","id":"exchange-001"},{"speaker":"つる委員","kind":"質問","question":"世界の感染状況がどうなるかというのは分からない中で、２３区のどこかでも、ある区ではカウントダウンを再開するところがあります。いろいろな規制があるのかどうか分かりませんけれども、その辺の考え方を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"カウントダウンタイマーの件なのですが、私どももいろいろ検討して、どうしようかということで、今のところ閉じています。ずっと閉じたままとは思っておりませんので、一つの方向性、ターニングポイントのところで徐々にまた再開していくというふうにしたいと思っています。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"本来行うべきであった７月、８月に向けて、やってほしいと求めました。ちょうどパラリンピック２００日前というイベントがさっき動画に出たので、同じような取組みをしてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今年度も当初の予定では、夏に向けて幾つかの機運を上げるようなイベントは企画しておりました。いろいろな形はこれからも考えられますし、様々な形を、ご意見を頂きながらつくっていきたいと考えています。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問","question":"区応援３競技のアスリートの皆さんが、みんなで１分計って一緒に挑戦してみる、お互いリモートで収録などができるとどうかしらと思いました。いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば１分間で腕立て伏せ何回とか、いろいろな形が考えられると思いますので、ご意見のようなものも含めて企画はしていきたいと思います。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"しな助の方の英語のワークショップは、私どもも見られる状態になるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今配信しているのはワークショップではなく、一方的に流しているものなのですけれども、これはしな助の方だけなのです。ただ、なかなかすてきな内容なので、終わった後には一般公開も、しながわネットＴＶで流そうかという話はしています。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、もし大会が中止となった場合は、今まで取り組んできたことが無駄になってしまう。ぜひともそうした２つのパターンを冷静に考えていただきたいと思っているのですけれども、その点、もう一回ご意見を聞かせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"次のオリンピック、オリンピックばかりではないですが、そこを見据えながら機運醸成イベントなども企画していきたいと考えています。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"オリンピックが本当に中止になってしまうのかどうか、日本の大会組織委員会と東京都からの連絡体制というのが、今どうなっているのかなと。品川区も困ってしまうと思いますので、今の状況というのをこれからどう考えていくのかということを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私ども品川区も、その中でも大会組織委員会や東京都がいろいろな説明に来ておりますので、その連携体制はできているかと思います。ただ、そこは自分たちから情報を取りに行くようにして、知らなかったということがないようにしていきたいと考えています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"つる委員からも確認をさせていただきましたカウントダウンの件についてですが、また出していくというところのお考えが今後どうなのかというのを、１点確認させてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区のホームページの、今までは左上のほうに、トップ画面に出ておりましたが、今はコロナ対策が出てあります。こちらは広報広聴課とのやり取りになると思いますが、今後一定程度、コロナが収まった時点で、またお願いしたいと思います。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"オリンピックを迎える１年後も、ぜひアピールの意味も込めて、また復活をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"４０万人いるから、新しい生活様式にチャレンジしたのだなとか、お互いがお互いにエールを送り合うような仕組みづくりというのも面白いのではないか。ぜひいろいろ知恵を課でも考えていただいて、やってほしいと求めましたが、何か感想を頂ければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、委員からいろいろな新しいアイデアを頂きました。なかなか課の職員だけで考えても、ぜひいろいろな意見をまた頂いて、近くにいなくてもつながれるような取組みというのをしていきたいと思っています。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":11064,"voices":32}},{"id":"r02-20200526-10","meetingId":"r02-cm05","date":"2020年5月26日","dateIso":"2020-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"監査委員の２件、選任同意ということですが、まず、本多議員についてですけれども、監査委員は第１会派および第３会派から選出されるべきだとの考えから賛成したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"共産党が第３会派になったときに、第４会派から出すと変更され、今回は第１会派、第２会派というものです。やはりフェアな進め方ではないと思いますので、改めて監査委員は第１会派および第３会派から選任されることを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"正副委員長の互選","agenda":"正副委員長の互選","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ほかの自治体で選任、委員長とかいろいろ決められるときに、問題が起きている事例が見受けられます。ですから、最初に臨時委員長の席には大会派の人を入れたほうが、問題が生じないかと思うのですが、いかがか尋ねました。","respondent":"米田区議会事務局長","answer":"これまで臨時委員長等を決めるに当たりましては、年長議員の方に臨時委員長になっていただいていますので、そのように先ほど説明させていただいたものです。","id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"質疑というわけではないですけれども、令和２年度行政視察について議長から説明があったとおりでよいと考えています。第２波、第３波も含めて区議会としてどう対応すべきなのか、引き続き協議しながら進めていただければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9094,"voices":55}},{"id":"r02-20200608-6","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"区民委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"大きい流れだけ教えていただきたいのですが、そういう地域、面に近づけていこうとしているのか教えていただきたいのが１点。戸籍住民課に伺いますけれど、大きな意味でいいので、その辺についてはどういうふうに考えていこうとしているのか教えて頂きたいと思います。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"１２分の１の実費負担で防犯カメラを設置することができましたが、従来と同じ負担率で新規に防犯カメラをつけていただくような制度を準備しています。積極的に地域の皆様方にご説明申し上げまして… 国のほうでも、いわゆるデジタル手続にどんどん移行していこうというような大きな動きがこれから出てくると思います。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"１６ページの「地域課題の自主的解決の支援」というので、使いづらい状況とか、そういうことではないのですかという確認なのですが。どこかでつまずいてしまうというか、突っかかってしまうという部分があるのか、そこを伺いたいと思います。","respondent":"川島地域活動課長、黛生活安全担当課長、遠藤商業・ものづくり課長","answer":"０件ということで、お祭りでの事故の対応などの相談対応をしていたということですが、引き続き私どもも考えていかなければいけないと認識しています。これに対しまして、当担当といたしまして、ツイッター、それからホームページ、しなメール、さらには青パトによる広報活動などを展開しています。… 国や都のやっている事業ですので、私どもといたしましては、なかなか把握するのが難しい状況です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"支援策も、やり続けていけるかどうか分からないけれど申請しているという状況もお伺いしていますので、区としては大事なのではないかと。実態の把握というのをぜひ、都や国の支援策がどこまで行き届いているのかというのを把握していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"私ども、雇用調整助成金などの窓口、あるいは国の持続化給付金などがスムーズにできるような相談窓口という形で設置させていただいているところです。","id":"exchange-003"},{"speaker":"つる副委員長","kind":"提案","question":"１点、提案と検討いただきたい点でして、子どもたちの安全安心のためにいろいろ対策を取っていただいているということは分かっています。夕方のチャイムのときの案件ですとか、この辺で何か１つ対応できないかというところで、その辺のお考えがあれば説明を求めました。","respondent":"黛生活安全担当課長","answer":"そのあたりのことを踏まえて、できるかどうかということを、引き続き検討してまいりたいと思います。こういうもの等を引き続き行いながら、今、何かいいものができないかということで研究してまいりたいと思います。","id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"熱中症対策なども含めて、子どもたちの安心安全に努めてほしいと求めましたので、ぜひ積極的に検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"１点、こういう機会でないとなかなかお伺いできないと思うのでお伺いしたいのですけれど、スポーツというところで出てきて。これは、問題意識の共有という意味で質問させてほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"今まで従来の考え方、方針というのは、あくまで地域の区民の方にスポーツや健康づくりの機会を広げていくというのがまず第一なのです。それぞれの組織の目的に果たしてかなうのかというところで、今後、全体の中で検討していくべきものかと考えているところです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"今後、長引くと言われている中では、どのようにお考えになるか伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"やはりマスクをしてというのは危険な状態もあるので、強制する考えもまずないです。できるところから、またソーシャルディスタンスも意識しながら、そういうところを進めていければいいかと考えているところです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"専門家というのですか、議論というのですか、考えるのはどうかというのをお伺いできたらと思います。","respondent":"中元スポーツ推進課長","answer":"一方で、現在、品川区のスポーツ推進計画というものをつくっているところです。今のところはまだ区で独自ということは考えていないのですけれども、情報収集はきちんとして、心がけていきたいと思っているところです。","id":"exchange-008"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"それらの課題について、今後、区がさらなる支援を行っていくに当たって、どのような支援が可能か。他自治体の取組も参考にしながら、その２点の調査を希望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"どういうふうに過密な状況をつくらないのかというところの施策を、区内ではないですけれども、そのあたりを検討できればいいと思うのが１点。品川区が、自治体としてｅスポーツをどういうふうに推進していけるのかというところも、所管事務調査ということでやらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"小芝委員","kind":"質問・要望","question":"品川区で、この新しい時代に対応できるような対策をぜひ取ってほしいと求めましたので、まずはそういったところの要望をしたいと思います。地域で住む人を牽引する町会を、ぜひとも品川区で支援してほしいと求めましたので、町会・自治会の支援について要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011","title":"町会・自治会支援"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も大体、皆さんと同じなのですが、やはり商店街と商店、そして中小企業です。生活の大きなところですから、そこへの支援の在り方、そして実態をつかんでいけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"ですから、これは委員長・副委員長に、皆さんのご意見をまとめていただいて、私は全部、所管事務でやりたいです。でも、物理的な回数等も条件としてあるので、正副にお任せいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"提案","question":"正副で当然、私も皆さんから出していただいた提案と全く同じような部分も多々ありまして、新しい生活様式に基づく地域の絆の在り方という部分では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":36298,"voices":88}},{"id":"r02-20200608-7","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"厚生委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"公明党のあくつ広王です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"９ページのことなのですけれども、どの法人からどこに何人派遣されているのか、ご説明願えますかとの意見を述べました。","respondent":"寺嶋福祉計画課長","answer":"法人からの派遣につきましては、高齢者福祉課の高齢者支援第一・第二係に、区内の法人から４名の職員が派遣されております。職種としては、主任ケアマネジャーです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"前の年にニーズ調査を行うということが厚生労働省から求められていたと思うのですが、品川区は行っていないのではないかと思うのですけれども、その理由を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"ページですか。さっきの説明にあったと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"その第八期計画の策定スケジュールやメンバー、あるいは委員会の回数や、おおよその日程を教えていただければと思うのですけれども。","respondent":"宮尾高齢者福祉課長","answer":"こちらは現在の第七期あるいは第六期のときと同様に、基本的には、介護保険制度推進委員会と一緒に策定の準備を進めてまいりたいと考えています。時期を見て、別途ご報告をする予定でおります。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"そして要望を聴いて、どうお考えでしょうか、伺えたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"今回につきましても、パブリックコメントは実施をする予定でおります。こういった結果も反映をさせていただきたいと考えていますので、現時点では住民の説明会等を実施する予定はございません。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"説明会という形での要望を聴く場、そしてそれを骨子案に反映させるようなことを考えていただきたいという要望を申し述べておきます。続けていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"委員会の回数は４回ほど予定されているということを、それから素案策定、それからパブリックコメントの日程や……。〔「中に入り過ぎではないか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"計画策定のスケジュールなどございましたら、お聞きできたらと思いますけれども、お願いいたします。","respondent":"築山障害者施策推進担当課長","answer":"今年度実施します障害福祉計画の策定に関してですけれども、策定委員会は先ほど説明させていただきましたとおり、４回程度を予定しています。障害者団体へのヒアリング、パブリックコメント等の実施は、秋口頃を予定しています。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"特に４月の申請のことを、その新聞では報道していたのですけれども、東京２３区に限ると、申請件数の増加率は４割に達しているという報道でした。５月の申請件数、できればその増加率を品川区についてお伺いしたいのですけれども、お聞きできるか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"非常に生活困窮者は、共産党でもアンケートを取っていますし、新聞報道やテレビの報道でも……。〔「そういうことではない、質問をするのだ」 「共産党の宣伝はいいから、概要をみんなで聞いているのだ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ目につくように、区民の方が、このようにしたら生活保護の申請ができるのだということを分かるようにしていただきたい。そういうことが品川区のホームページや、それをやっていただきたいということを、今日お願いしたかったということなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"そして、品川区はこのような制度を持って、自分も助けてもらえるのだと思えるようなものを作ってほしいと求めました。それを本当に要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"これまでも、ケースワーカーの受け持ち人数が多く、ケースワーカーを増員すべきことを求めてきました。そして、最も多いケースワーカーの方は何人を受け持っているのか、教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"ケースワーカーの担当世帯数についてのご質問かと思います。４月時点で保護世帯数４,５５２、ケースワーカー４３名で、ケースワーカー１人あたりの世帯数は１０５世帯となっております。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問","question":"組織図で、ここには生活福祉課６７人の職員と書かれていますけれども、非常勤の方は常勤換算で何人いるのか、伺っておきたいと思います。","respondent":"櫻木生活福祉課長","answer":"会計年度任用職員は現在３０名いまして、常勤換算いたしますと、２２人相当となります。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"去年は２０１人と書かれていたので、実際の福祉部全体は２１５人ではなくて何人なのか、その人数も教えてほしいと求めました。先ほど法人からの派遣職員というのが、法人への派遣職員というのは、どこに何人派遣されているのかについてもお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長、松山障害者福祉課長","answer":"それから、先に法人への派遣ということで私からお話ししますと、福祉計画課のところに派遣というのが４つ書いてあります。社会福祉協議会に３名… 申し訳ありません、昨年度の職員数としては、３２人です。今年度は３６人になりましたので、４人増えたということになります。『品川の福祉』という形で製本することになりますので、その際に改めまして、正しい人数で記載をさせていただきたいと考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の時点で福祉部全体の職員の人数というのはどうなっているのかというのだけ把握しておきたいのですけれども、会計年度任用職員がどうなっているのか、教えていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"今ご答弁申し上げたとおり、昨年度の数字にも非常勤が入っているということで、実際には増えているということもあります。全数を申し上げることができませんので、『品川の福祉』のところで新しい数字を改めてご紹介するということで、今日のご答弁とします。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"職員のところはそういうことで、ぜひ増やしていただきたいという要望だけ、お伝えしておきたいと思います。その辺のところも、ここのところもぜひ知らせていただきたいと思っているのですけれども、その点についてもご答弁いただけたらと思います。","respondent":"櫻木生活福祉課長","answer":"１つは生活保護、暮らし・しごと応援センターの周知、もう１点が住居確保給付金の件数ということでございまして、概要についてご説明します。住居確保給付金ですが、暮らし・しごと応援センターの延相談件数を申し上げますと、令和２年４月から５月までで３,２３４件となります。","id":"exchange-018"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に大変な中、お疲れさまです。申請からおおよそ２カ月ぐらいかかってしまうものなのか、その辺のところの見通しが分かったら、教えていただけたらと思います。","respondent":"寺嶋特別定額給付金担当課長","answer":"見込みとしましては１日３,０００件、夜間をやらないと２,０００件程度ということなので、３,０００件ペースで進めようとしております。","id":"exchange-019"}]},{"id":"topic-04","title":"事務事業概要を再度、議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","agenda":"事務事業概要を再度、議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２３区の平均だと７,０００人弱なのです。その辺はどのようにお考えなのかということを伺っておきたいと思います。","respondent":"鷹箸保健予防課長","answer":"新型コロナウイルス感染症対応に関する保健師の部分について、私からお話しいたします。新型コロナウイルス感染症対応に関しまして、その対応については、かなりスキルを持った事務職でないと対応できないという部分がありまして。","id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"さっき人口と保健師の数ということで挙げたのですけれども、一般論としても、品川区の保健師はそれほど少ないものではないというご認識なのでしょうか、伺います。","respondent":"榎本荏原保健センター所長","answer":"先ほど保健師の活動のところでご説明いたしましたけれども、かなり特徴的な、そういったところで連携を取っているということ。こちらも各所に１名ずつ配置しておりまして、連携体制で協力をして、充実している一面というところでも見られるかと思います。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問・要望","question":"大変な増大ということになると思うのですけれども、区としてはどのように体制を強化していくつもりなのか、その辺をお伺いしたいと思います。いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"６月２日付の国の方針で、濃厚接触者を基本的には全例という方針は、その対応を始めているところです。今後、今設置されている帰国者・接触者外来あるいはＰＣＲ検査センターの対応数では賄えなくなる可能性がありまして、第２波に備えて。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"受ける人が増えるように持っていく対応も必要ではないかと私は思うのですけれども、この点、いかがでしょうか。特に高齢者の無料化をお願いしたいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国民健康保険のことを伺いたいのですけれども、前回の厚生委員会の中でもお話させていただきましたけれども、これがいつから対象になっていくのか。６月１５日に国民健康保険料の発送がされていくということでしたけれども、私はこの厚生委員会の中でお知らせいただきたいと思っているのです。","respondent":"池田国保医療年金課長","answer":"今予定しているところでは、６月１１日号で新型コロナウイルス感染症に対する保険料ということで、やりますと。６月１５日に保険料の発付ということで先ほど説明させていただきましたけれども、また、ご報告するということで考えているところです。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3568#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":56961,"voices":140}},{"id":"r02-20200608-8","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"建設委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"様々なまちづくりの動きの推進を強化していくということでご説明がありましたけれども、そうすると、担当部長は、事務が増加したことによって、それを処理するためということでしたので、どのように事務作業をやっていくかという、担当部長としての仕事内容をお聞きしたいです。","respondent":"中村都市環境部長","answer":"そうしますと、さらに東京都あるいは国、こういったところと連携して進めていかなければいけないというところがあります。部長を配置して、そういう所管の関係の自治体と調整をしていくというところがありますので、その必要性をもって配置をしたです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"いかがかということと、あと、今までこれだけの体制をとったことというのはあるのでしょうか。それぞれの課、部に配置されている職員の人数も伺いたいと思います。","respondent":"中村都市環境部長、多並都市開発課長","answer":"にぎわいの維持と向上、こういった観点からもまちづくりの取り組みは必要であるというところで、継続していくと考えています。〔「現在の」と呼ぶ者あり〕 失礼いたしました。現在の人数とほぼ同等だったと記憶して……。体制としては維持と、または部長のこれからの調整なども含めて、そういうものをこれから進めていかなければいけない。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"担当部長も配置したということで、福祉よりも開発に優先性が表れているのではないかと思うのですけれども、区の認識を伺いたいと思います。〔「いろいろな意見があると答弁しているじゃないか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"これだと１年前の数値ということになってしまいますので、ぜひ最新の数値を事務事業概要に載せるべきだと思うのですけれども、いかがでしょうか。公園の整備で、これをどういう方針で、あるいは方法で進めていくのかという区の考え方を伺いたいと思います。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"不急という部分でいっても、長い目の中で検討されていることについて、区がしっかり支援していくことが必要であろうということです。よりよいまちづくりを進めていこうということで、総合的なバランスの中で… 補助２９号線の用地買収あるいは整備について、不要不急といいますか、早急に取り組んでいかなければいけないというところの区の認識です。それ以外の地域に造っていく公園については、所管は公園課です。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"要望してほしいと求めました。実際検討というのは行われたのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"まちづくりは区が進めるものというよりは、地域の方がご自分で考えていくことでありますので、それを区として支援していくというのが重要なことです。そういう形でしっかり支援していきたいという意味ですので、中止か、延期かという検討というのではなくて。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"最後の質問にしたいと思いますけれども、区のほうで検討するということではないと。やはり区の財源を投入されるわけですから、区のほうで判断していくことも必要なのかと思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"地域の方が皆さんがご自分で考えて、どうしていこうかと考えられる協議会だったり、そういう段階からご自分たちで組織されて検討していくと。そのように区としては進めていきたいというのが考えであります。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"空港環境担当についてお伺いしたいのですけれども、４月２０日の総務委員会で新設されるという報告があり、そういう窓口にもなるのかと思うのです。空港環境担当についてもう少し詳しくご説明ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"ご質問の空港環境担当、予算化されて今年度実施していく一番大きなものとしては、区内２か所に測定局を設けて騒音を測定していくというものです。その窓口になって、いろいろ調整ですとか、地域の人の声を国に届けていくというところも大事な仕事になってくるです。","id":"exchange-007"},{"speaker":"田中委員","kind":"意見","question":"しかもとても区民の方たちが注目している羽田の問題の担当なので、記載があったほうが、ご説明がもう少しあったほうがよかったというのを思いました。区民から寄せられた声や、それに対する答えだったりとかも、この担当の中でやられていくのかといったところもお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"もうじき調整次第、まとめてになりますが、公表し、その後は定期的にスケジュールどおり公表していきたいという予定です。それに対する回答については一つひとついただいている状況ではございませんが、こうしたいただいた声を紹介しているという状況です。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"要望等を届けているということだったのですけれども、苦情何件、そういった情報を区のホームページのほうでも載せてほしいと求めました。多く寄せられる要望、ぜひそういったことも要望したいと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"せっかく新設されて、きっといろいろと相談ができるのだろうと期待されている方たちもおられると思うので、ぜひホームページだったり、情報発信をきちんとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"まちづくりですから、そこの補正というのをどうかけながら、この１年間議論すればいいのかということです。これから建設委員会で議論する中で、大きな影響が出てきてしまわないかというのがすごく心配されるのですが、その辺はいかがか尋ねました。","respondent":"森住宅課長、中村都市環境部長、鈴木都市計画課長、多並都市開発課長","answer":"そういったものが７項目ありますけれども、窓口は区になりますので、区のほうに出していただく。それに対して区のほうからマンション管理士等の専門… 部の一番上に２つ並んで配置されるわけですが、今回は他の自治体と特に調整が必要であり、担当部長に担当していただくという形です。その中には… おおむね１０年をめどに、時代に合わせた中身で更新を、見直しを図っていくと記載させていただいてあります。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やはりその部分で工事が伴うもの、今後盛り返して、きちんと区内事業者に工事の発注ができるように頑張っていきますという部分があるではないですか。１０のうち２割ぐらいは減ると思っていますとか、いつ頃までにそれを分かるようにしようと思っているか、そこら辺を教えていただきたい。","respondent":"中村都市環境部長","answer":"粛々と進めていく、区民の対応につきましては、区民の要望が極力通るようにというところで対応していくです。今、やはりパーセンテージでいけば２桁台のパーセンテージで、新型コロナウイルスの影響によって不用額が出てくるといったところが見込まれるです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"来年度予算だって、もうすぐこれは始まってくる頃だろうと思うけれども、そういう要求をしていくわけではないですか。今後少なくとも３年ぐらいは大変な時期が続くのだろうと思っていますので、各所管にかかってくると思うので、お願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"では、報告事項、羽田空港の機能強化に関する要望","agenda":"では、報告事項、羽田空港の機能強化に関する要望","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、要望に行った目的、どういう目的で行ったのか。一層の騒音軽減策の推進を求めるということで書かれているのですが、具体的に何を求めているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"３月２９日から本格運用が開始されてございまして、運休が続いている中で、本格運用が開始されて実施されてきてあります。新型コロナウイルスへの対応や当面の就航需要の減少を踏まえた一層の騒音軽減策の推進の中身ですが、この議事要旨、要望にあるとおりです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"一層の騒音軽減策の推進というところが、少し矛盾するというのか、よく分からないのです。そこが何を求めていらっしゃるのか、区のビジョンというか、考えがおありでしたら、ご説明ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"様々取り組みを行っていただいておりまして、新型コロナウイルスの影響により減便しておるというところを入れさせていただいてあります。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、区が求めるこの取り組みというのは、品川の上を飛ばないルートを求めたということで理解していいのでしょうか。今、品川区はこの説明をどのように受け止めたのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１点目の、要望書にもあります新飛行ルートを固定化しない取り組みの実施、上空を飛ばないということも含めて求めているというものです。〔「航空局長の回答をどのように受け止めたか」と呼ぶ者あり〕 様々、オープンハウス型あるいは教室型説明会の中で国が説明してきている内容、日本の国益を上げていくというところが非常に大きかった。","id":"exchange-016"},{"speaker":"のだて委員","kind":"確認","question":"千葉県との確認書が国土交通省と交わされたということで、区としては、この確認書をどのように認識されているのでしょうか。午後３時から７時の間、千葉県の上は飛ばないということで確認をされておりますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"私、こちらを所管してから３年、その中では、オープンハウス型説明会、区内１３地域全域で教室型説明会も実施していただいております。","id":"exchange-017"},{"speaker":"のだて委員","kind":"確認","question":"今までこの確認書が報道されるまではご存じなかったということですよね。私が伺ったのは、確認書はご覧になっていらっしゃるかと思うのですが、区としての認識を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国のほうからは、騒音環境軽減の意味も含めて、この件については継続し検討していくという回答がございました。国はしっかり受け止めて回答いただいて、検討していくとしていただいておりますので、それを今後も強く求めていきたいです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"国土交通省にもその説明を求めていくべきではないかと思いますので、ぜひそういった要望もしてほしいと求めました。従前のルートへ戻すべきということで、はっきりと新飛行ルートの中止を求めるべきではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"どこか国の委員会の場で、新ルートを固定化しないご要望についてはしっかりと考えていきたいという旨の発言を直接区長のほうにもいただいてあります。そうした中で考えますと、これは国のほうでしっかり検討をしていただけるものだというところでの区の受け止めです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"この羽田新飛行ルートの中止を国土交通省に品川区として、ぜひ区長を含めて求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"幾つかお伺いしたいのですけれども、まず、要望書の作成プロセス、過程をお知らせください。","respondent":"鈴木都市計画課長","answer":"あるいは３月２９日の本格運用開始以降、当日、国土交通省に要望書として出したというものです。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"この要望書の中にある区民の声、このような声も確かにあります。そのような声が反映されていないということはなぜなのかというのを伺いたいです。","respondent":"鈴木都市計画課長","answer":"ただ、区民の不安である騒音や落下物、これについて不安の払拭に努めていただきたいということがこれまでも区として強く求めてきたことです。先ほど区のスタンスをご説明したとおり、あるいは本格運用開始以降も、区としての立場を国に伝えるというものではないという理解です。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"要望書の中にある「従前ルートへ戻すべきなどの声もあり」、従前に戻す、３時間をもっと短くという趣旨で示している。そのところに関してお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"新型コロナウイルスへの対応、時間を３時間から２時間とかに短くするとか、そうした意味合いを含めて書かせていただいているところです。固定化しない取り組み、方法がどういったものがあるかというところは、国のほうでしっかり検討いただくべき内容だと感じているところです。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"だから、きちんとここの要望書の中で、容認できない、飛ばせられない、品川区としては認められないといったことをきちんと示すべきだと思います。千葉県の確認書についてなのですけれども、確認書を区として知ったのは、要望書が出される５月２０日以前だったのか。","respondent":"鈴木都市計画課長","answer":"あるいは国際線を増便していくものを、そこは違う方法もしっかり検討していただきたいという意味で、固定化というものを入れているところです。ご質問からすれば、５月２０日以前に知ったです。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"区として、千葉県と国の確認書のことに関してももっと言うべきことは言わなければいけなかったのではないかというのはとても思うのです。意見を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その不安を解消、これまでも実施してきたことで、今後もしっかり行っていかなければいけないと考えています。区民への丁寧な説明・周知、落下物・騒音環境の取り組み、固定化しない取り組みというところを今後もしっかり求めていくべきだと思います。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"５月２０日以前に確認書のことを知って、次にまた要望書を書くときには、３時間よりもっと短くしてほしいといった区としての考えを。突然“このような要望を上げました”ではなくて、きちんと区民の声も聞きとって、次からは要望書を出してほしいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"固定化についても、固定化することがない取り組みをしていただきたいと。固定化しない取り組みというのはどういったものがあるかについても、これもその中身を国のほうでしっかり考えていただくというものと考えています。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、その文言を、区としての趣旨をきちんと次からは要望書に書いていただきたい。そういったものもきちんと残してほしいですし、公開もしてほしいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当日短い時間の中で、儀礼的挨拶以外については、この発言要旨のとおりのやりとりが行われたです。区としても要望していくことになりますので、そうしたやりとりについては、しっかり記録として残していくと考えています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"この要望書は、就航需要の減少を踏まえ、一層の騒音軽減策というのは何ですか。〔「同じ質問じゃないか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"ということは、どこまで国土交通省の考え方と一致しているのかどうかというのは、確認しておかないといけないことなのではないかと思うのです。国土交通省がこのように書いてありますけれども、本当にそれが一致しているのかという確認はしていかなければいけないことなのではないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"考えられる技術的選択肢について多角的な検討を行っていただき、さらに一歩踏み込んで、大臣が国会の場で発言されたという認識です。先ほどご説明した、決定後もこれは継続して東京都には情報共有、そうした場でしっかり確認をしていきたいと考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"この建設委員会が担当になるわけですから、建設委員会の中には、しっかりとこれは新しい文言だということの認識を強めてほしいと求めました。なので、ぜひ今後の取り組みをしっかりとしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"ごめんなさい、１点だけ確認し忘れていました。発言要旨の中にある、その中でこのような要望を出して、どのような回答があったのかというところを伺いたいのですけれども。","respondent":"鈴木都市計画課長","answer":"そうした実施について、今打ち出されている取り組みで、落下物対策はすべてオーケーだとは思ってございません。ほかの自治体についても、これに対する回答は国としてもしっかりその辺は検討して取り組んでいきたいという回答はいただいているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"では、検討ということは、やはりいまだに国としては前進していないということでいいですか。確認をさせてください。","respondent":"鈴木都市計画課長","answer":"国の受け止めは、区のあるいはほかの自治体の求めに対して、今後も検討、取り組んでいきますという回答をいただいておりますので、国の受け止めも、“今の打ち出しているもので終わりです”という認識ではいないと理解しています。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"この要望も、目に見える形で前に進めてほしいという要望ということは、そういったことだと思うのです。ですので、区として求めている落下物対策に対しての要望は叶っていないということでいいか尋ねました。","respondent":"鈴木都市計画課長","answer":"この取り組みは、区民にも、その実効性についてお示しいただきたいというところがまず１つです。その上で、しっかりその取り組みの実施とともに、ほかに何かできることはないかというところを今後もやっていただきたいという区のスタンスです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"都心の上を飛ばないルートを求めているということは、品川の上を飛ばないルートを求めているけれども、よく分からないのですけれども。今回求めたことで、ぜひ中止の立場に立ってほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"固定化をしないように求めた実効性がなくなってしまうと思うので、改めてそこのところを伺いたいと思います。ですから、少なくとも今、減便になっているこの段階で中止を求めるべきだと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"実施につきましては、国策でございまして、区として中止を求めるというところは考えてございません。その中身については、落下物、騒音環境の取り組み、それから、固定化しない取り組みというところをしっかり求めていくというものです。","id":"exchange-035"}]},{"id":"topic-03","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"段ボールベッドですとか、間仕切りをすることが感染拡大防止にも有効だということで言われておりますけれども、検討状況を伺いたいと思います。町会のない公園で、先ほど旗の台の説明がありましたけれども、今後、進めていく方針というのはどのようになっているのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"適切に、ぜひ被害のないように、できるだけ抑えるようにして進めていってほしいと求めました。冊子を配布するなどして、避難所での対応を示していくということが迅速に対応できるようになるのではないかと思うのですが、いかがか尋ねました。","respondent":"中島防災課長","answer":"防災区民組織に通知した内容につきましては、今、委員ご指摘のありましたＮＰＯのマニュアル等も参考にしまして、作成しています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"都市環境部よりは都の補助金等との関係はあまり大きくはないのか、影響は起きないのかと思うのですけれども、その関係はどうなのでしょうか。それも含めて今後事業は展開していかなければならないと思っているのか、その辺のお考えをお聞きしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"今後の水族館のあり方を検討していくということなので、どういう考え方でということを問うのはやはり難しいですか。そういう分け方をしているのだから」と呼ぶ者あり〕。","respondent":"塚本委員長","answer":"それはやはり水族館ということで、これは行財政改革特別委員会ということで決まっているので、こちらで、要するに、「しながわ水族館」という言葉が出るということがふさわしくないということだと認識しております。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり６月になっていますので、水害も出てくるでしょうし、ぜひとも早急に報告としてまとめていただきたいと要望します。ただ、品川区にとってはどうかといった場合には、やはり“ここは何とかしてほしい”という要望が多々出てくるかとは思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"１点だけ。防災課の７２ページの２、もしご説明できるようでしたら、お願いします。","respondent":"中島防災課長","answer":"事業等を進めていく、国の動き等で必要なことについては防災会議のほうに諮って、地域防災計画に反映してまいりたいと考えています。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど新任の災害対策担当部長のご答弁の中で１つだけ確認をさせてほしいと求めました。もう一回、ご決意というか、私の受け取り方ではないのだということを示してほしいと求めました。","respondent":"滝澤災害対策担当部長","answer":"防災関係もある中で、自分で選択をするというのが今回の職業選択ということで。１５歳から自衛隊に入隊しておりまして、強い気持ちをもって今回、品川区に就職をさせていただきました。","id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"任務であられるわけでありまして、職に就くというよりも職に奉ずるという心構えでされたほうが私はいいと思いますけれども、どのようにお考えですか。イメージのチェンジ、あるいはステージが変わったわけですから、そこのあたりの考え方を、もう一回、私の話を受けて、感想を聞かせていただければと。","respondent":"滝澤災害対策担当部長","answer":"まさに職に奉ずるという意味で、同義だと考えています。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２点伺います。１点目は、先ほど都市環境部でも伺ったのですけれども、これを必ずしっかりまずピックアップをしろということがある。","respondent":"溝口道路課長","answer":"今年度、予算がついているところもありますし、私どもも計画的に事業を進めていかなくてはいけないところではあると考えております。そのように考えているところです。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから、もう一点伺いたいのは、先ほど来、災害対策担当部長の話が出ているのだけれども、私はぜひご活躍いただけることを期待しています。ここから発信して、“私たちに仕切らせろ”ぐらいの話があってよかったような気がするのだけれども、どうかというところを聞きたい。","respondent":"藤田防災まちづくり部長","answer":"防災まちづくり部としてできること、こういったこともみんなで力を合わせながら、これまでも進めてきているところです。組織のあり方についても、これがゴールということではなく、一歩ずつ前に進めていければと考えています。","id":"exchange-045"}]},{"id":"topic-04","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"例えば、こういうときに合わせて避難所が密にならないようにどういう対応を取っているかなどというのは、様々いろいろな動きが出てきている。どうして防災というのは、それが必ずあるので、そこら辺を含めてもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"大沢委員","kind":"提案","question":"戸越公園しかり、北品川のほうもしかりということで、どうしてもこれ、国の財源、あるいは企業の財源に頼るところが多いと。立体交差事業について調査・研究をすべきではなかろうかと思って、今、提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう視点でお願いしたいというのが１点と、もう一つが、羽田の件です。新しい項目が知らないうちに入ってきているというのがあって、羽田空港の機能強化に関してというのを項目として入れていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4292#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":60511,"voices":192}},{"id":"r02-20200608-9","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"文教委員会","time":"午後 １時００分～午後 ３時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"の１の幹部職員紹介","agenda":"の１の幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけと申します。１年間どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の２の事務事業概要","agenda":"の２の事務事業概要","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"先ほど、コロナの話も出ましたので、私から１点お伺いしたいと思います。コロナの関係で、学校の関係が非常に不安定になっている部分が多いと思うのですが、それはまたおいおい伺うことにして、高校入試です。","respondent":"矢部教育総合支援センター長","answer":"私どももまだ待っているところですので、周知の必要がありましたら、早急に学校に通知していきたいと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"区教委としては、これをどのように定めているのか、また定めていこうとしているのかを１点目にお伺いしたいと思います。そこら辺について改善の必要があると思うのですけれども、そこら辺についてもお伺いしたいと思います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"ただ、子どもと教員も負担過重にならないということは国からも通知されているところですので、特にこの６月は、まだお休みから明けたばかりです。大きく２点目の３密の状況ですが… 基本的に様々ご心配される点は、あくまで４０人学級につきましては、国の法律あるいは東京都の基準等によって現在進められているものです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点お伺いしたいのですが、１点目は、何を目的とした会議になっているのか伺いたいというのが１点です。２点目は、また、どういう状況になっているのか伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１点目の職員会議のことです。内容は、２か月単位のところもあると思いますけれども、月別の行事についての確認というところが中心になるかと思います。 私どもは東京都教育委員会からもご指導いただく中で評価者訓練等も行いながら、研修なども校長、副校長に実施しながら適正に進めているです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それが子どもたちに直接接する教員なわけですから、そこら辺がどうなっているか、もう１回聞かせてください。そこら辺について、そういった懸念はないのか、もう１回だけお願いします。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"分科会がありますので、一堂に会すというのは、多くても月１回というふうに認識しております。学年ですとか教科で部会もありますので、そこで自分たちのアイデア等を協議できる場があると認識しています。 それを個々の教員が自分の職務分担等を鑑みながら、自分の１年間の目標を決める。その中では、その中で最終申告まで、そういったものを行いながら適正にその業務内容を業績評価していくというふうに取り組んでいるところです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、いわゆる校外施設、修学旅行的なものは、移動教室とか夏季施設の利用のこの２点しかないということでよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"教育委員会のほうで関わりを持っているのは、こちらに書かれているとおり、移動教室と夏季林間学園になります。修学旅行に関しましては、各学校が独自に企画をして実施をしているというものです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"各学校のご判断ということなのですが、現状、修学旅行の中止とかは検討されているのでしょうか。今の状況を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"お話に挙がりました修学旅行につきましては、極力実施したいという気持ちがあるのは伺っておりますけれども、校長会と検討しまして、６月末には一定の判断を出したいという予定です。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"６月末のコロナの感染状況とかを踏まえて、やはり生命に関わることかもしれないので、ぜひ慎重なご判断を行ってほしいと求めました。どのように、これは効果的だったというふうにいうのか、そうしたお考えは今のところ教育委員会としてはどう考えられているのかを説明を求めました。","respondent":"工藤指導課長","answer":"各学校のほうでは、今、落ち着いた後にはしっかりとオリンピック・パラリンピック学習としては取り組んでいきたいというふうに考えてあります。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"今まで培ってきたものはしっかりとぜひ活かしていっていただきたいと考えておりますので、よろしくお願いします。学校の改築、施設整備工事においては、コロナウイルスの影響はあるのか尋ねました。","respondent":"小林学校施設担当課長","answer":"現在のところは、予定どおり目標に向かって進めているところです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう１点教えていただきたいのですけれども、学校の出席ですが、今の段階では、既にもう出欠はとっているのでしたか。これ、自治体によってちょっと違いがあったと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"出席につきましては、登校が始まってございまして出席日になりますけれども、お休みしても欠席にはなりません。今回はそういう扱いでおります。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"これは、６月中は分散登校でずっとそういう考え方ということでよろしいのでしょうか。今後の方針は、どのようにお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"６月、７月も同じ考えです。授業日数は、学年に応じて同じ数を本区の子どもたちに通ってくるようにです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"いわゆる１学期中といいますか、夏休みに入るまでは少なくともそういう考え方ということでよろしいのでしょうか。登校選択制という考え方も今ちょっと出てきているみたいなのですけれども、それについて何かお考えがあれば併せて説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"東京都や国の事務連絡によって今の出席の扱いはとっておりますので、少なくとも１学期はそのとおりで、これまでどおりです。様々な形があるかと考えておりますが、先ほどお話がありましたが、学力の保障という両方を協議しながら慎重に進めてまいりたいと思います。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"２点お聞きしたいのですが、先ほどもお話がありました１人１台タブレットということも進めてくださっているのですが、そういったお子さんなどに対してのＩＣＴの活用の検討も今はされているのかということをまず１点お聞きしたいです。","respondent":"篠田学務課長","answer":"現在、とにかく品川区の児童・生徒全てのお子さんに配布できるようにという形で、まず機械のほうの整備を考えてあります。具体的に個別のお子さん方にどのような形でフォローができるかというのは、これから先、丁寧に検討してまいりたいというふうに考えているところです。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったことの周知も、制度が整ってからですが、そういったところもやっていただきたいと要望します。２点目に教職員の働き方改革ですけれども、これからやるという対策とか方針とか、そういったところを検討されていましたらお教えください。","respondent":"工藤指導課長","answer":"特に今回、結局、夕方にやむを得ず残っている場合に電話応対に時間をとられてという教員の方たちの負担を軽減するということも考えてはあります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて待機児童数とはどういう数字なのか教えていただきたいのですが、例年、そこら辺を確認させていただきたいというのが１点です。それと１０９ページのご説明で、１１月に１か所、４月の認可保育園の開設予定はどのように考えていらっしゃるのかもお伺いします。","respondent":"立木保育課長、若生保育支援課長","answer":"これは４月１日入園時の数値ということになりますので、年末に４月入園のお申し込みをした方たちの審査等を一次、４月１日に実際に入園された方たち等の数値をこちらのほうに記載しているものです。来年度の認可保育園の開設の予定のご質問ですが、令和３年度の開設につきましては、８園の開設を予定しています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"実態を反映していないということになるのかお伺いしたいと思いますし、この数字はどういう数字なのですかということを伺ったので、もう少し聞かせてほしいと求めました。","respondent":"若生保育支援課長、立木保育課長","answer":"待機児童の１３人に対して来年度開設が８園というのがそぐわないのではないかというようなご質問でしたけれども、現在計画している８園につきましても、８園の開設とさせていただいたものです。 先ほどこちらの表でご説明をさせていただきましたが、この１３名に至るまでには、そういった数字を差し引いて最終的に待機児としてカウントした方の数が１３人ということでこちらに計上しているものです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと２点ですが、この３つの相談拠点の関係性といいますか、連携はどういうふうになっているのかということをお伺いします。４１ページですが、事業のすみ分け、連携などはどうなっていくのかお伺いします。","respondent":"廣田子ども育成課長、加島児童相談所移管担当課長","answer":"学習会とか家族懇談会も予定しておりまして、本人自らというよりも、本人を一人ひとり支援していくというような形で考えてあります。仲介するような形で、区であまり知られたくないような方であるとか… 課題検討を行っていく上で、支援を担っております子ども家庭支援センターの意見を聞きながら、検討を練り上げていきたいと考えているところです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"できれば、同じ課題に取り組んでいるわけですから、そういったところが見えてくるといいのかという感想を持ちました。最後は雇用の問題ですか、最後に区のお考えといいますか、お聞かせほしいと求めました。","respondent":"加島児童相談所移管担当課長","answer":"令和元年６月の児童福祉法改正において、児童相談所職員の配置基準が引き上がりましたので、そちらのほうにも的確に対応していく必要があります。継続的な人材の確保につきましては、人事部門と協議の上、こちらのほうも努めてまいりたいと考えております。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認させていただきたいのですけれども、冒頭で報告していただいた保育園の６月２日現在での登園率を教えていただきたい。ちょっとこの数字を確認させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで７割程度ということですね。この保育園の再登園開始に当たって、現場でかなり戸惑いがあるみたいなので教えてほしいと求めました。","respondent":"立木保育課長","answer":"どうしてもくっつかざるを得ない場面も出てきますので、それ以外のところで、できるだけ離す。例えば、不可能なところはやむを得ずというところもあるのですけれども、極力できることをやっていこうということで指示は出しています。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"ちょっと現場のほうで戸惑いが聞かれたものですから確認させていただきました。なかなか登園自粛に対する、それに対して何らか指導なり何なりということをすることができるのか、あるいはしてきたかということを説明を求めました。","respondent":"若生保育支援課長","answer":"私学の考え方、品川区内の１８園に関しましては、私立幼稚園のほうでの各園の対応というところを尊重しているところではあります。そういったところでなるべく負担は軽減するという考え方をとっているところです。","id":"exchange-021"},{"speaker":"横山委員","kind":"確認","question":"すみません、１つ確認をお願いいたします。説明会の部分のほかに、どういった部分で、全体については令和６年ということで特に変更はないということで確認させてほしいと求めました。","respondent":"加島児童相談所移管担当課長","answer":"計画説明会のスケジュールについてですが、児童相談所の開設予定年度、令和６年度中については変更はございません。ただ、１月２０日の文教委員会でご報告しましたとおり、当初は６月に説明会の開催を予定しておりました。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、恐らく一番新しい情報で４月２０日の保育課からのお知らせで、登園自粛に伴う育児休業期間の延長など、あと登園自粛における在園資格ですけれども、やはり６月末までということで変わりはないか尋ねました。","respondent":"立木保育課長","answer":"６月末が間もなく近付いております。６月の半ば、６月中旬ぐらいには今後の取り扱いについて何らかの一定の方向性を出すようにしないといけないというふうに考えているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"すみません、今のお話ですけれども、６月、この先、７月まで育休延長できるかもしれないというお話なのでしょうか。２歳児で自粛されている方については、多分７月は保育料の返還はもう対象にならない、その返還も対象になるということか尋ねました。","respondent":"立木保育課長","answer":"現時点では６月末までは今お願いしている最中ですので、そこの部分に関しては免除といいますか、還付という形になります。財源の担保もなくなりますので、これもまた今後、感染の拡大状況を見ながらという形になると思います。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"むしろ７月あるいは秋ぐらいまでというところが、２３区で言えば、品川区は延長する可能性もかなり高いということなのでしょうか。お答えできれば。","respondent":"立木保育課長","answer":"そこのところも含めまして検討している最中ですので、決まり次第、またホームページ等で……。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"児童虐待についてですけれども、コロナウイルス感染拡大の中、今現在で児童虐待相談は今回のコロナウイルスの影響で増えているのでしょうか。状況をお知らせください。","respondent":"崎村子ども家庭支援センター長","answer":"その対応件数が昨年の１０月から今年の３月まで半年ですけれども、約９０件ございました。ただ、虐待対応の件数としては、昨年と比べると増えているといった状況はあります。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"そういった送致の制度とか、ほかの家庭内暴力とかいろいろあるから、なかなか児童虐待とかというふうに特定して認定するということはできない。内訳ははっきりしないということですが、その分析というか、そうしたことはおやりになる予定とかはあるのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"分析できるかどうかというところも今後検討しますけれども、虐待の通告自体は年々増えているような状況があります。そういったところをどのように判断、捉えるかというところは、もう少し検討させていただければというふうに思います。","id":"exchange-027"}]},{"id":"topic-03","title":"の１に戻りまして、幹部職員紹介","agenda":"の１に戻りまして、幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。１年間どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]},{"id":"topic-04","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"いち早くそういった１人１台ということもありましたので、手元に来てから実際にどういう取組みができるのかということも含めて、タイミング的には所管事務でしっかり追いかけていったらいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5004#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":48443,"voices":124}},{"id":"r02-20200608-5","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"総務委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ概要説明ありがとうございました。いつごろ示されるのか、未確定な部分も含めて、もう少しご説明をほしいと求めました。","respondent":"佐藤企画調整課長","answer":"総合実施計画の策定の見込みですが、実施計画に関しては成果目標をきちんと出して、それを行政評価につなげていくという大事な役割もあります。考え方をまとめた計画を別途つくるように、今、作業をしています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"最終補正を待つのではなく、年度途中であっても予算全体の調整を行うなどの対応についてはどのようにお考えなのか、伺いたいと思います。東京都が５月に依命通達を出しておりますが、何か考えを持っているのであれば、その点も伺いたいと思います。","respondent":"品川財政課長","answer":"それから４月、５月と補正をしまして、今回の第２回定例会でもかなりの額の補正をするという予定になってありますが。こういう経過等の報告時期等については、やはり新型コロナウイルス感染症の動きを見ながら、適切な時期に出していきたいと考えております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"第２回定例会に補正予算が組まれるということで、１点、その点を伺いたいと思います。区が独自に出した１人３万円、中学生未満は５万円という、その辺についても最後に伺いたいと思います。","respondent":"品川財政課長","answer":"しながわ活力応援給付金のほうで財政調整基金を使いまして、おおむね基金の残高としましては、２２億円程度になるかと考えております。この辺の部分で金額がどういうふうに動くかということになるかと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"では、その交付金で今後新型コロナウイルス感染症の部分はどこまで対象になるか、国の交付金も活用できるのかというのは、現状では分からないというか、見通しも含めて不明な部分があるということなのか、そこだけ最後にお願いしますとの意見を述べました。","respondent":"品川財政課長","answer":"財政調整交付金のほうが、基本的には令和２年度の財調交渉の中で、基本的には進められていくのではないかと考えております。どこまでの部分が新型コロナウイルス感染症の関係で財政調整交付金の対象になるかというところは、また今後の展開になるかと考えております。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"もう都知事選挙が迫ってきている中で、新型コロナウイルス感染症への対応というのは、既にいろいろお考えかと思います。今日のご報告からはその辺のことは分からないのですが、今、伺える範囲で検討されていることなどあれば、伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"５月１９日の総務委員会において、都知事選の執行要領のご説明をした際に、新型コロナウイルス感染症対策についてもご報告をしています。消毒液を置いたりということで、新型コロナウイルス感染症対策をとった上で、都知事選挙を執行するということをご報告したものであります。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"実際、知的障害の方とかで投票にいらした方が、品川区の選挙ではとても丁寧に対応していただいているということを伺っています。その中でもぜひ投票していただきたいというところで、何か工夫されていることがあれば、伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"それから障害者への対応ですけれども、障害者団体からご相談も受けておりまして、実際の模擬投票的なこともやりたいというふうには思ってあります。ご相談があった際は、そういう形で合理的配慮の上、障害者の方も投票ができるような対応をとっていきたいと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ある意味期間限定ですから、音声による案内ということもぜひ、視覚障害者の方たちに向けて行ってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問","question":"広報広聴課のところで、お伺いします。電話相談もなく、この専門相談が中止になってしまったという、その考え方をお聞かせほしいと求めました。","respondent":"大澤広報広聴課長","answer":"専門相談につきましては、各団体との話し合いによって電話を受ける場所がなかなか確保できないのですとか、状況を聞いて、電話で相談を受けられないという団体の結論を受けて、その期間は中止にしていたものです。","id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今後、またこれからもこのような状況になったとき、今回のことを受けて、何かできるような体制もぜひ、ご検討ほしいと求めました。そういうこともぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"相手の団体があってということですので、区のほうで一概にこのようにすると決めるのは難しい部分もあると思いますが、相談のニーズがあったということは認識していますので、今後検討してまいりたいと思います。","id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何とか感染防止をしながら開設できないかと思っていましたけれども、こうした状況のもとで、残念だということをお伝えしておきます。区民への周知だけは、ぜひ徹底してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"新型コロナウイルス感染症については、この後の報告事項のところで別に質問したいと思います。どのような意見や提案、方向性が示されているのか、概要を伺いたいと思いますとの意見を述べました。","respondent":"島袋人権啓発課長","answer":"７月に一度お会いできるような会議体を設定する予定でおりまして、各分科会から報告をいただきます。予定ですと３月にはというところですが、新型コロナウイルス感染症の関係で、若干延びますかどうかも確認しながら、様子を見ながら開催する予定です。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは、いわゆるＤ案は決定事項ということなのか、誰がどのようにＤ案を決めたのか、伺いたいと思います。庁舎について重要と考える課題はどういうものが抽出されているのか、現状についてご報告ほしいと求めました。","respondent":"島袋人権啓発課長、濱中庁舎計画担当課長","answer":"行動計画推進会議におけるパブリックコメントの実施ですが、今までパブリックコメント等は実施しておりませんので、今後も予定はしておりません。 次に、庁内ＰＴの重要事項ですが、今、１０ＰＴで検討しています。庁内の検討ＰＴで検討いたしまして、それを基に庁舎機能検討委員会で、様々な機能につきまして検討を進めていっていただく予定です。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、誰がどのようにＤ案を決定したのかということを質問しましたので、改めて伺いたいと思います。その中でも経過が分かるような資料をぜひ示してほしいと求めましたけれども、その点だけ改めて伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"その中で様々な諸条件から、Ｄ案が最も適切であろう、有力な候補地であろうと。ほかになかなか候補地が見つかっていない段階で、Ｄ案が最有力であろうということで、区として考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点だけいいですか。会計管理室に伺いたいのですが、再発防止等の対応をしてほしいと求めましたが、その後どういう経過になったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"経理課と会計管理室のほうで伺いたいのですけれど、最初に経理課の契約のところです。２７ページに契約係の表がありますね、それは件数からも金額からも、全部除かれているということなのか尋ねました。","respondent":"東野経理課長","answer":"これが予定数量を年間でどのぐらいかけてとか、この表から除いてあると、そういうふうに理解いただければと思います。そういったものにつきましては全部が契約確定できない、そういうものになってきます。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"は個別に伺うしかないかなと思いますけれど、この表の中に占める割合はどうなるのかと思いましたので、その辺をちょっと。今お答えできないようでしたら個別に伺いたいと思いますけれど、ぜひ説明を求めました。","respondent":"東野経理課長","answer":"それから、各所管との連携です。所管との関わりにつきましては、今後研修等を通しまして、きちんと記載していきたいと思ってあります。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"個別に伺うことがあるかと思いますが、そのときはよろしくお願いします。この１ページの表を見た段階では、それは違って、出納係がその役割になるのか尋ねました。","respondent":"中山会計管理者","answer":"新公会計制度担当というところでは、それぞれ歳出、歳入の仕訳のことであるとか、あと日々仕訳で一括して入れられないものがあるのですね。そこをどういうふうにすると一番きちっとした形でできるのかというのを、まだ模索しながらやっているところです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。ご説明を伺うと大変なお仕事かなと思うのですが、ほかの別のお仕事もやりながらということで、よろしいのか尋ねました。","respondent":"中山会計管理者","answer":"兼務２人というのは係長を充てているわけですけれども、その係長だけでやっているわけではなく、他の職員も含めて仕訳の相談ですとか、どういうふうにやっていくかということは、会計管理室全体として対応しています。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"さらに残業代が、今はローンの返済だの様々な生活費の一部にもなっていたと思うのですが、その辺に対して何か影響というのはでているのでしょうか。説明を求めました。","respondent":"黒田人事課長","answer":"一番多いときでも全体を平均しますと３割ぐらいでございまして、お電話をいただいたりということで、非常に難しいというのが現状としています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"派遣の方に協力してもらって、様々な事業を支えていただいていると思うのですが、その人たちに対する影響というのはないのですか。その辺の大まかな人数とか予算が、これぐらいの規模でやはり減りましたとか、そういうものは大体把握されているのか尋ねました。","respondent":"黒田人事課長","answer":"看護師は増員して、電話対応に当たっておりますので、仕事として増えている部分もあります。そういった影響がどのぐらいになるかは、人件費では把握していないところです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そういう方が多々いるというお話をお聞きしているもので、できるだけ多くの方の雇用の確保というのも考えていただければありがたいと。あるときは必要だから来てくれ、こういうときは要らないというのだと、その人たちの生活にも関わってくると思うので、それでお聞きしたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それと、庁有車のマイクロバスなのですけれど、こういう状況下で出庫する回数というのは当然減っていると思うのです。視察などでマイクロバスを使用していないと思うのですが、管理はどういうふうにされているのか、お聞きします。","respondent":"東野経理課長","answer":"今後、経済活動といったところで、新型コロナウイルス感染症が終息に向かいましたら活用も増えてくるだろうと思われます。今のところはあまり活用がないような状況です。","id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"意見","question":"分かりました。いざ出庫のときに、バッテリーが上がっていたら困ってしまうので、その辺どういうふうに整備されているかと思ったのですとの意見を述べました。","respondent":"東野経理課長","answer":"庁有車ですので、出庫する場合、外に出かける場合などに支障のないようにというところで管理を行っているところです。具体的にどういう管理を、というところまでは今、申し上げることができませんけれども、支障のないような管理を行っていきたいと思ってあります。","id":"exchange-023"}]},{"id":"topic-04","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"新型コロナウイルス感染症対策本部の対応について、幾つか伺いたいと思います。区としては、この感染抑止と社会経済活動の開始を一体的に進めていくためには、何がどう重要だと思っているのか、基本的な認識を伺いたいと思います。","respondent":"立川総務課長","answer":"委員ご案内のとおり、こういった「新しい日常」であるとか、「新しい生活様式」といったことが打ち出されているところです。基盤として今後とも最重要事項であるとともに、こういったことを、区としましては周知に努めてまいりたいと考えているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"保育園に子どもたちの声が戻り始めて、また学校では分散登校も始まり、介護施設では利用者も戻りつつあると伺っています。区民そして職員の安全安心をつくることも、新型コロナウイルス感染症対策本部で検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"立川総務課長","answer":"現在のところ、健康な職員等に対してＰＣＲ検査を実施する考えはございませんが、今後の国や都の動向といったものを踏まえまして、この辺については考えていく必要があるのかなと思っているところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり現に新たな感染も都内で２０人、３０人と報告されておりますし、いち早く実施できるよう強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回の委員会でしたでしょうか、ヒューマンエラーという話もありました。それを防ぐための対策も必ずすべきだと思いますので、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"新妻副委員長","kind":"意見","question":"ご説明をいただき、ありがとうあります。残金２５万円余ということですけれども、その金額がどれぐらいなのか、あらあらの金額がもしわかればお知らせほしいと求めました。","respondent":"中山会計管理者","answer":"他行から振り込まれる場合は一番最大で８８０円、同じ銀行内であればたしか２２０円とか、そういった額だったと思います。それから納付書による納入につきましては、１件につき手数料が２円ということで、これらが区のほうの負担になると考えているところです。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"質問","question":"そうすると、そういう様々な手数料のトータルは、まだ出ていないということか尋ねました。","respondent":"中山会計管理者","answer":"それぞれの方とどういった形で返金をしていただくかという話は、合意が得られているところです。今、きちっとした総合計は出していないのですけれども、３万円以内で収まる見込みです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"先ほど総務課が、中心になって調査を行うということだったのですけれど、どれぐらいの期間を見込んでいるかとか、もしあれば伺いたいと思います。それからどういう体制で行っているのか、一定見込みを伺えるとありがたいのですが。","respondent":"立川総務課長","answer":"７月に２回ほどやりまして、７月下旬までにまとめまして、報告につきましてはそれ以降にさせていただこうと考えております。香川公認会計士、こういった方をお迎えいたしまして、委員会を構成しています。","id":"exchange-030"},{"speaker":"鈴木（真）委員長","kind":"質問・要望","question":"前回の委員会のお話で確認なのですけれど、みずほ銀行がしたのか、その辺はどうなのか気になっています。その辺、もし今の段階でお答えいただけるのでしたら、教えていただきたいのですけれど。","respondent":"中山会計管理者","answer":"やはり会計管理者と指定金融機関との間で、きちっとした確認ができない中で起こった事故というふうに考えています。区が最終的に振り込んだものになりますので、区のほうで指定金融機関に依頼をし、組み戻しの手続きをしたところです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"スケジュール的に延びるかもしれませんけれど、答申を出すという段階ですので、性的マイノリティの理解促進が２つ目です。いずれにしても日常的な委員会の中でも大事なテーマだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"湯澤委員","kind":"意見","question":"ＩＴ力を活用するなど、そういった観点からも、自治体がこのシビックテックをどのように活用するかは重要であると考えています。品川区におけるこのシビックテック活用について、調査項目にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"これだけ社会がどん底といったらいいのでしょうか、日々子どもたちの一日は、１年に相当するぐらいの大きな影響を私はこうむっていると思うのです。その二つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問","question":"生活様式が変わっていくわけですから、昨年、シティプロモーションも含めた連携をしていく中で生活様式が変わっていく。そういった中での自治体との取り組み方、要するにシティプロモーションについて、私は調査を希望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"私は先ほどの事務事業概要で質問させていただきまして、どなたかほかの委員のご質問に対して、一体どういうことかなと思った覚えがあります。契約というところももう少し、いろいろな所管との連携のあり方とか、もう少しきちんとあってほしいというところがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"新妻副委員長","kind":"提案","question":"少しピンポイントになりますが、昨年、ピンポイントで品川区のホームページというテーマを提案させてほしいと求めました。区民が求めている情報が一目で分かるという、一点、提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言よろしいでしょうか。その点だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"ご存じのとおりワクチンができるのが１年半から２年先、きちんと終息するには数年かかるというお話まで聞いております。信念として、行く、行かないは決断させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"第２波、第３波の議論もある中、しないを含めて検討していただきたいと。ストレートに言えば、やらなくていいのではないかと私も思いますので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40820,"voices":166}},{"id":"r02-20200609-14","meetingId":"r02-cm06","date":"2020年6月9日","dateIso":"2020-06-09","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時３６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"荏原複合施設には設置施設として４つありまして、荏原在宅サービスセンター、荏原在宅介護支援センターの４つ。荏原健康センター、荏原保健センターの３つがあると書いてあるのですが、今７つあるうちのどの部分が移転するという形になるのか尋ねました。","respondent":"佐藤企画調整課長","answer":"旧第一日野小学校に移転する対象の施設ということで、説明が不十分で申しわけございません。詳細については、今後、基本設計を進めていきますので、また折を見て報告したいと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"その２つに関してはその場に残る、ほかの部分が第一日野小学校に移転するだろうという理解でいいわけですか。それで、説明会を開くとなっているのですけれども、その説明の日程などは決まっているのか尋ねました。","respondent":"佐藤企画調整課長","answer":"説明会の日程ですが、まだコロナの関係もあって、なかなか着手できなかったということもあります。今回、こちらの委員会で報告できましたので、今後、所管と詰めて、できるだけいいタイミングでやっていきたいと考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それから、荏原複合施設の改修そのものは大規模改修であって、今７つ申し上げましたけれども、それ以上に新たな施設を入れるということではないと理解してよろしいか尋ねました。","respondent":"佐藤企画調整課長","answer":"新しい荏原複合施設に関しましては、新しい機能を入れることは現時点では考えていません。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"これは一体何なのでしょうか。教えてほしいと求めました。","respondent":"立川総務課長","answer":"平成２４年に総務課で作成したガイドラインでございまして、各課において危機管理マニュアルを作成する際等の指針ということでつくったものです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"大抵こういうところに示された文章は、ホームページで検索すれば、かなり細部なものでも出てくるのですけれども、見ることはできないのか尋ねました。","respondent":"立川総務課長","answer":"こちらは、先ほど申し上げたとおり、いわゆる内部向けに作成したものでございまして、作成からもう既に７年経っているところです。このガイドラインの公表につきましては、今後、検討していきたいと考えております。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"危機管理対策ガイドラインということで基本的な文書であろうと思います。ぜひ公表していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"立川総務課長","answer":"内容が公表にふさわしいかどうか、検討していきたいと思います。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"国でも新しい生活の仕方を銘打ってきているところもありますので、今後の取り組みの検討について、「Ｗｉｔｈコロナ」と言うのでしょうか。これは私の意見ですので、理事者の方のご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"実際、これから２０２５年問題もあって、水族館ももうそろそろ年数が来ていると思うのです。直近で相当の予算を必要とされるのならば、どうなるかなという推移を見たいので、資料を出していただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"区の働き方改革が今回出されておりますけれども、区の職員の方もかなりの残業をされているのではないか。いつも遅くまで明かりがついておりますので、区の職員の働き方を考えるにあたり、そういう現状がわかるような数字も出していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。事業をどういう形で取り組んでいけば、それは時間短縮にもなるし、そのような議論ができるような資料もお願いできればなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10744,"voices":62}},{"id":"r02-20200610-18","meetingId":"r02-cm06","date":"2020年6月10日","dateIso":"2020-06-10","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけと申します。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２０２１年にも開催されなかった場合は中止となる見通しを示したと報じられましたけれども、されないかで大きく方向性も変わってくると思うのです。開催の可否が判断される時期、タイムリミットというのはいつ頃になると区は把握していらっしゃるのか、伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１０日に理事会が開かれまして、そこで示されるというふうにニュース等では出ていました。直接的に組織委員会や東京都からの連絡は入っていないところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点なのですけれども、レガシーのところで、１点だけ確認させていただきたいのです。実施予定などもあったと思うのですけれども、大会の延期に伴って延期されたものなど、その全体の大まかな開催状況について伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから、文化プログラムについてなのですが、今、７５事業ありますというようなご説明を差し上げました。それからあともう一つ、インクルーシブ能、国立能楽堂や喜多能楽堂で開かれる予定でした能・狂言、手話狂言のほうが中止になっております。","id":"exchange-003"},{"speaker":"つる委員","kind":"確認","question":"前期のオリンピック・パラリンピック推進特別委員会の最後のときにも確認させていただいたときに、今はまだ表示はしていないですね。まさに新ロードマップを受けてやるのか、その１点をまず説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"事業者が明日参りましてセッティングをします。よろしくお願いします。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問","question":"５、６月とイベント的なものは当然中止になっていると思うのですけれども、今年度の中にあるのか。それをまず、概略でいいので説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"次にどう残していくかですが、先ほどの説明の中でもお話し差し上げたのですけれども、まず３競技を中心にずっと機運醸成をしてきたわけです。そういったものを区民の皆様と作っていけるようなことを推し進めていきたいという思いです。","id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"どんぶりなどがなくて困ったという人には出しますよといった形なのかなというところをちょっと確認したいのと。そういったもののほうがいいのではないのかと思ったりしていて、そんなところを伺いたいのですが、いかがか尋ねました。","respondent":"提坂環境課長","answer":"容器を持参していない方については、ご説明したモールド容器ですとか紙製容器類をお配りして、お持ち帰りいただく。「買い過ぎず」・「使い切る」・「食べ切る」ということをうたっておりまして、そういうところでまずごみ削減の一環につながるのかなと考えています。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"ホームページのほうのカウントダウン表示はいつぐらいから可能なのかというところを１点確認させてほしいと求めました。区が作成したものをぜひご紹介いただきたいと考えていますが、いかがか尋ねました。","respondent":"提坂環境課長、辻オリンピック・パラリンピック準備課長","answer":"今のテイクアウトの関係で、区だけではなくて周辺の自治体とか東京都と連携して、その辺はこれから周知を図ってまいりたいと考えています。オリンピック・パラリンピックで配ることが可能かどうかということはちょっとまだ不明なのです… 申し訳ございませんが、今のところはまず新型コロナウイルスのことがホームページの作成ではやっていくということで、ご理解いただきたいと思います。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"私からは１点、私も含め、やはりどうしてもイメージとしては奉仕活動。そういった部分でこの独自ボランティアの在り方といいますか、改めてどういった位置づけでどのようにしていくのかを教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"地域をつくっていく上でも大事なことだと考えています。ちょっと機運も下がり気味ですので、そうならないように、これからいろいろ手を打っていきたいと思っているところです。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"２０１２年のロンドン大会、７万人の大会ボランティアが活動されて、大会後にやはりこのボランティアレガシーをロンドンは考えていたのですね。そういった位置づけに何とか残していくというか、そういった形で残していくことが大切ではないかと思うのですけれども、どうか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"プロボノと言って、こういうスポーツボランティアみたいなのを自分たちで立ち上げてみようという方もひょっとしたらいらっしゃるかもしれない。その支援はしますし、あくまでもそのしな助の意向を確かめながら、次につなげられるようなことができたらいいかなと思っています。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、ぜひ進めていっていただきたいのですけれども、オリンピック・パラリンピックを具体的にどうやって結び付けていくのか。そのご予定の事業をお知らせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西村委員","kind":"質問","question":"本当に前例のないことに区としてもこれから向かっていくのだなという気持ちでお話を伺っていたのですが、改めて環境を考えたときに。こういったテイクアウトマップとの連携ですとか、ウェブの展開をご検討されていらっしゃるでしょうかというのを伺わせてください。","respondent":"提坂環境課長","answer":"さらに、今２３の商店街のほうで登録していただいているのですけれども、いろいろな推進事業にご協力いただきたいと考えております。エコバッグについては、これは一応エシカル、倫理的な消費ということにはつながるのかなと考えています。","id":"exchange-011"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"提案","question":"提案なのですけれども、オリンピックに向けておもてなし清掃をして、来客・観客を迎えていくという動きがあると思います。課題とか、この中で取り上げていただけたらという提案なのですけれども、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"２つ目は、この広町現庁舎敷地にこのアリーナを整備するかどうかというのは決定事項ではないですし、区民的議論や合意もない状況だと思います。これも要望というか提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"趣旨的にはここでお答えがあるのかどうかは分からないですけれども、しっかり考えなくてはいけないと考えております。委員会としてはまだそこまで具体的な内容、今後どうするのかというのは詰めていないという理解でよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"渡部副委員長","kind":"確認","question":"例えば東京２０２０大会で言うのだったら、過去の大会を確認しても、そのような中で環境レガシーというようなこともあります。その関係あるかないかというのはちょっと誰も答えられる話では全くなくて、関係あるからやるわけですので、そこは承知してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"両にらみで進めていかなくてはいけないのかなと考えておりますので、そうした２つのシナリオを考えた運営をしていっていただきたいと考えております。これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23472,"voices":71}},{"id":"r02-20200612-10","meetingId":"r02-cm06","date":"2020年6月12日","dateIso":"2020-06-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"それに応じた、見合った配分というのを積極的に求めていただきたいという趣旨で、１点目の要望とさせていただきました。この水辺事業者に対しての水域占有料、いわゆる停泊料の減免の要望というのを出して、品川区議会自民党の要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"次、鉄道連続立体交差事業の一層の推進を求める要望ということで、３の技術的な支援など自治体の支援を充実していただきたいという要望です。最後に、４位の不妊治療助成に対しても、先ほどと同じ要望をさせていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"以下３つについては、国と都両方への要望ですので、あわせて説明します。毎年出させていただいています高齢者施設に関する要望ということで、２０２５年問題というところで、(1)と(2)で２つ出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"続いて、例えば市街地再開発や街路整備など、こうしたものの中止または当面延期を求めてコロナ対策の財源に振り分けていただきたいということです。保育の質の確保についての要望ということで、保育園の職員配置基準の改善、用地取得に関する負担の軽減などですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"３番目に、全国市議会議長会を通じた要望ですが、また医療従事者等の宿泊所として利用できる臨時大型施設をつくり上げることを求めます。以上をトータルしますと、臨時大型施設を何とかつくるように要望したい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"中段より下にある自衛隊中央病院との連携に関する要望など、この２番目の枠の中に一緒にまとめられないかなと。やはり２３区共通の課題ということを考えれば、保健所機能の強化というのは単独で残して要望をと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"着陸も離陸も、やはり東京全体の共通の問題として、ここはしっかりと国に求めていくことは大事ではないかと強調しておきたいと思います。国民健康保険制度ですね、やはりここは国民皆保険制度ですから、ぜひご検討をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"これだけたくさんさまざまな要望が出ていますので、ではどうするのかという話で、皆さん各会派からの要望の多かったところを主として考えて。これだけ要望があったらどれがどれだと、それぞれ皆さん削れない要望ばかりだと思うので、副委員長。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"こんの委員","kind":"意見","question":"これは一緒にしましたが単独でということも考えられるかというところですので、そこはお計らいほしいと求めました。課題というのが見えてきていますので、やはり二、三項目一緒に出ているところをまとめていくというのがよろしいのかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"意見","question":"第一希望で避難所における感染症対策、これもコロナ対策になると思うので、これを含めてほかの会派の皆さんもコロナに関することを一緒にうまく取りまとめていただけるとありがたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体まとめてもらったので、大分ここは今の国と同じようにまとまってくるので、ある程度委員長のほうでまとめてもらってもいいのではないですか。この中でいくともう大体同じ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"認可保育園がとても大事だと思いますので検討いただきたいのと、また自治体への支援にいよいよ踏み込んでいただきたいと考えています。どうしたって学級規模を縮小することが必要だし、子どもの学びにとっても少人数学級は全国で実施されておりますので、ぜひ一致できたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほど自民党の芹澤委員からも説明させていただきました財調の問題、これはぜひ入れておいてほしいと求めましたので、追加でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど国の部分についてはいわゆるコロナウイルス対策というところで１つにまとめていこうということになっていて、その中に入れ込むのではなくて、単独でこれは特出しでやるということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然コロナ対策もありますけれども、それだけではなくて財調自体のあり方が今までもいろいろな議論をされています。新たな課題も出てきているということで、東京都に対して直接別の立場で要望するということで考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"コロナウイルスということで財政のこととかいろいろなことを１つの要望の中に幾つかの項目という形で入れたのですけれども、そこの取り扱いは、議長。コロナウイルスということであれば財調も入れてもいいのかと思ったのですが、理解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"今財調のお話がありましたが、そのとおりだと私も思います。既に準備をしているわけですから、あわせてそこは東京都の算定項目にしっかり入れるべきだと思いますので、一言述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう意味で、私たち自民党として児相は児相で要望を出していますし、財政面でのフォローをしてくれということで両方入れている部分があります。ですから、財調の中では含めた上での財源、個別事業は個別事業ということで要望しているということの流れでつくっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"本多委員","kind":"質問・要望","question":"この課題に対しましては、国に対する要望のところでうちは考えておりますので、うちの考えはコロナ対策に対する、あと避難所とか自衛隊中央病院との連携とか、その辺の施策で出していますので、必要ないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望内容は、防災対策の充実としては大事な指摘もあるかと思うのですけれども、全国市議会議長会に宛てるべきなのかというところはよく判断していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"今先にご発言いただいた２人の委員と同じ意見です。それをちょっと全国市議会議長会に出すということの、そこまでの特出しをする必要があるのかというところでは慎重な判断が必要かと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"提案","question":"ですけれども、皆さん方のご意見も今お伺いしましたので、それはそれで議運の場でだめならだめで構いません。ただ、趣旨だけは、そういう趣旨で提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"そこで速記をやっている方がいらっしゃるではないですか、今どうなのかわからないですけれども。それでちょっと提案させていただきましたとの意見を述べました。","respondent":"渡辺議長、米田区議会事務局長","answer":"今ご提案いただいた議場でのマスクの着用、またはそれに関連する感染予防対策、既に事務局のほうで業者とのやりとりをしたり検討に入っております。補足は事務局長から。 ただ、それ以外の席ではマスクをされて発言をされているというのが東京都議会の状況だと見ております。その辺も踏まえまして、今議長の話にありましたようなところでの検討を、物理的な条件等も含めて検討を進めているところです。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":17633,"voices":55}},{"id":"r02-20200624-10","meetingId":"r02-cm06","date":"2020年6月24日","dateIso":"2020-06-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"コロナ禍の下、感染抑止と議会活動をどう両立させるかという点においては、やはり今は第２波への備えが必要なのだと思います。ただ、委員会ごとにばらばらというのはどうかと思いますので、これはお願いをさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"向こうも東京から来られては困るということがあるわけですから、そういうことを考えて、私は今年度は自重するべきではないかと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"何よりも今回、羽田新飛行ルート計画について、要望事項からなくなったというのは問題だと考えています。国に要望を届けていただきたかった、提案していただきたかったと思いますと、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"3)の駐車場内工事ということですけれども、全体としてはどうなっているのか、分かれば教えてほしいと求めました。","respondent":"米田区議会事務局長","answer":"工事の内容ということで、免震ダンパーということで申し上げましたけれども、こちらにつきましては、今定例会中の委員会で所管より報告がされる予定と聞いてありますので、そちらで詳細はお尋ねになっていただければと思います。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10396,"voices":33}},{"id":"r02-20200629-6","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"区民委員会","time":"午前１０時００分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"松本委員","kind":"質問","question":"今回は国と違って、給付の対象が新生児も含まれているという状況で、なぜこれは２,０００人も減っているのか。場合によっては増えてもいいのかなと思っているのですけれども、その辺りのご見解をお願いいたします。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"対象者数なのですけれども、５月１日時点での人口が４０万６,１８８人いらっしゃるという状況でした。基準日の４月２７日から日数が空いておりますので、この間、約４０万６,０００人とさせていただいたものです。","id":"exchange-001"},{"speaker":"松本委員","kind":"意見","question":"例えばお子さんでもいいのですけれども、お子さんとかが申請することができるのか、どうなのか。先ほど申し上げた２人以上の世帯の場合は、今どのようにお考えか、お願いいたしますとの意見を述べました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"これは、国の特別定額給付金の考え方に準じてやらせていただくというところになっております。ですので、もし世帯の構成員が世帯主様お一人で、亡くなられたとすれば、申請ができないということになっているところです。","id":"exchange-002"},{"speaker":"松本委員","kind":"意見","question":"何が起こるかというと、ご本人が例えば債務があって、差押えをされますと。場合によっては差押えの対象になっていくのではないかと思いますが、そこの部分というのは何か対策を講じていらっしゃるのか、お願いいたしますとの意見を述べました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"世帯主の方に行っていただくところなのですが、給付する給付金に関しましては、給付対象者の方に帰属するものと考えています。その先の給付対象者一人一人に帰属すると考えております。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"対策としては、これは質問という形で再度お伺いしなければいけないのですけれども、やはり個人を対象にするべきではないかというのが１点。全庁的に共通見解を出したほうがいいのではないかというところと、その辺りは対策を取るべきではないかと思いますが、いかがか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"それと、２点目の質問なのですけれども、今回給付するものにつきましては、個人に帰属するという考えを持ってあります。差押え等につきましては、関係部署等と連絡を取り合いながらという形になろうかと思います。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問・要望","question":"私としては要望しておきたいと思いますし、ぜひとも全庁的な共通見解というか方針は、きちんと徹底してほしいと求めました。委託の部分とか、もっと減ったりするのではないかと思うのですが、その辺りは予算の精査の状況というのはどうなっているのか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"３億７,０００万円計上させていただいておりまして、またデータ入力業務等の委託という形で、２億６,３００万円を計上しております。例えばＡＩ－ＯＣＲといった、申請書を自動で読み取ってデータ入力までするという機械の導入等も検討していての金額となっております。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"どうしてもオンラインで申請したもので、口座の情報がちょっと違ったりとかというので、ものすごく時間がかかっていると。ここまで大きく、同じ額を予算として計上しているところの理由について、もう一回お願いいたしますとの意見を述べました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"国の特別定額給付金と、今回のしながわ活力応援給付金では、事業実施の期間というのが完全に一致するものではないという認識は持っています。対象とする世帯数等々も近い数字になっておりますので、このような形での計上という形にしているところです。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"業者の契約は７月の上旬ということですけれども、かかり過ぎないようにしていただきながら、適切にというところは要望しておきたいと思います。これは質問ではなく、要望というところで終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"８月上旬に申請書が発送されるということで、６月３０日に議決されるという予定で、結構かかるのだなという印象がしたのです。今、１０万円の給付金を今やっている最中で、全く業者もシステムも変えた上で進めていくというものでいいのかというのを伺いたいと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"金額が違うという委員からのご指摘もございましたが、申請者の負担軽減で、国の特別定額給付金に添付していた書類の活用等を考えております。いずれにいたしましても、議決いただきましたら速やかに事務を進めていく予定です。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"その辺が分からないのですけれども、伺えたらと思います。そうなのであれば、住民票ではなく戸籍の付票活用というのをやるべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"ホームレスの方の扱いにつきましては、先ほど説明しましたとおり、基準日である４月２７日時点に住民登録のある方を給付の対象とするところです。住民登録のある方でございましたら、給付対象となります。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国によっても、国の給付金は駄目だったので、区の給付金なら、区で何とかしていただきたいと思うので、もう一回求めておきたいと思うのですけれども。どこと調整していて、ぜひそこを強力に求めてほしいと求めましたが、関係行政機関というのはどこなのかというのを伺いたいと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"１つ目の、ホームレスの方のお取扱いにつきましてですが、基準日において品川区に住民登録のある方を対象とするという形を考えております。２つ目の、生活保護世帯の収入認定の関係で、調整している関係行政機関につきましては、東京都になります。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、次に行っていいですか。次というか、補正の中の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"７１５万円というのは、すごく安いのだなと感じてしまったのですけれども、あそこの土地も建物も取得するということでいいのでしょうか。それで、自治体が取得するということになると、安く購入できる仕組みで購入しているということなのか、説明を求めました。","respondent":"古巻文化観光課長","answer":"敷地が１９.７３m2ということで、延べ床面積が１０.３４m2ですので、ここの建物と土地を併せて取得するという内容です。特別な制度があるわけではないと思いますけれども、東京都の言い値といいましょうか、東京都から提示した金額で購入をするです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"もともとの店内を、つい立てとかアクリル幕とかではないもので工夫しているお店というのは、どのように証明されるのか伺いたい。遡っても助成してもらえるということなので、そういう場合はどのようにしたらいいのか、お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"購入したものとか、それをやることで、どのような影響があるかというのを書いていただくような形で考えております。これは販路拡大とか、そういう部分だなということで判断できるようであれば、助成の対象となるかと思います。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"３密を避けた形に改装して、４月１日に遡って請求もできるわけですから、どのようにされるのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業に全て配付していますので、おそらく皆様のお手元に、この情報が行くのかなと考えております。","id":"exchange-014"},{"speaker":"小芝委員","kind":"確認","question":"私からは、先ほど石田ちひろ委員もおっしゃっていますが、販路拡大支援助成についてお聞きします。確認なのですけれども、中小事業者、これは個人事業主も含まれるという認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"基本的には対象と考えております。","id":"exchange-015"},{"speaker":"小芝委員","kind":"質問・要望","question":"よくて５割という話も伺っております。支給された額も結局、ぜひともこの販路拡大支援助成をさらに広めていただきたいというのを要望といいますか、見解をお聞かせいただけますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"この間、４月から私はこちらに就任させていただきまして、特に融資の関係とかで多くの苦労があるという話を聞いております。ちょっとした、今回この販路拡大支援事業というのを実施させていただきましたので、ぜひ多くの方にご活用いただければと考えております。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは郵便局の問題なのかもしれないですけれども、そういった課題とかというのが新たに見えてくるデータになるような気がするのです。そうするときに、定額給付金を配り終わった後のいろいろなデータについての活用とか考え方について、何かあれば教えてほしいと求めました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"今回、対象となる世帯に書面を送らせていただいて、ご申請いただいて、それを速やかに給付される事務を進めていくところです。申請いただきました情報等に関しましては、この給付金を目的にしておりますので、そこで活用するというところを考えております。","id":"exchange-017"},{"speaker":"大倉委員","kind":"意見","question":"その辺の活用について、貴重なデータだと思っていますので、今後の活用とかを考えていただければいいかなと。それは特別定額給付金もそうですし、品川区政にいいデータとして活用していただければというところで聞かせていただいたので、もう一度お願いしますとの意見を述べました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"郵送で送りますので、返戻される郵送物は、一定数見込まれると思います。理由の分からないものに関しましては、戸籍住民課と連携しながら対応していこうかと考えているところです。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"１個、そういったところにも届けてほしいという思いがあるのですが、なかなか大変だと思うのです。一つ一つ、申請されませんでしたけれども大丈夫ですかという確認を取るというのも、考えがあれば教えてほしいと求めました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"申請期限前に申請が出されていない世帯につきましては、勧奨の通知を送る予定です。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"勧奨の通知を送るというのは、大丈夫ですか、申請されないのですか、というものが来るのかどうかだけ教えてください。勧奨通知を送ったけれども反応がないから、どうしたのだろうという対応になるのか、そこだけ教えていただきたい。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"勧奨の通知につきましては、送りまして、その後、申請が期限までになければ、申請がなかったものという形で考えるところです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"本当に情報的に手の届きづらい人たちに行っているかどうかというのは、今お伺いして思ったのですが、いかがか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"勧奨通知と併せまして、広報しながわ、また区ホームページ等で周知を図ってまいるところです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"プレミアム付商品券についてお伺いしますが、プレミアム率が３０％と今回決まったのだけれども、その根拠を教えていただけますか。予算もあるし、いろいろあると言われてしまうかと思うのですけれども、改めてその根拠を説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"５月ぐらいにできそうだと、３０％でインパクトがあるだろうということで、話合いの中でやらせていただいたです。５０％のことで、私どもは３０％でも十分、させていただいたところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"次に、しながわ活力応援給付金についてお伺いしますけれども、いつこの担当課はできたのですか。なぜ担当課が替わってしまったのかということも含めて、教えていただきたいと思うので、まずそこから入ります。","respondent":"久保田地域振興部長","answer":"担当課ができたことですけれども、まず、これは６月５日付で担当課をつくらせていただきました。福祉計画課は国の定額給付金のほうの事務を重要事項として進めているというところで、全庁から各係長の兼務を頂きながら、全庁体制で進めているです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"今、部長からそういう答弁を頂いて、力強い。次の質問なのですけれども、給付対象者は４月２８日から１２月３１日までとなっているのですけれども、令和２年という意味でいいのですよね。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"令和２年の４月２８日から１２月３１日までです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"４月２７日現在にお母様が例えば住んでいて、生まれる時期とかがあるではないですか。すると、５月、６月、７月、８月、９月、１０月、１１月、１２月と、１２月３１日までだと８か月間ということではないか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"対象期間を１２月３１日までに生まれた子どもにした理由という部分になってくるのですけれども、その上で出産されたという世帯への支援としています。妊娠期の期間などを総合的に勘案しまして、対象期間については本年中を一つの区切りとさせていただきました。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"でも、４月２７日現在にはおなかに宿していたかもしれないではないですか。妊娠期の不安だと言うならば、赤ちゃんが１か月目です、２か月目ですとか、あるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"２回目の郵送というのを、今のホームページを見ると、支給された全ての世帯は２０％ぐらいですか。取りあえず、そこまで伺わせてください。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"申請期限を設けますので、申請期限内までの申請を給付に結びつけるという形を考えておりますので、なかなか取扱いは難しいのかなと考えるところです。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"追加で告知等をしていただいて、何とか区民の全ての方に、何が何でも知っていただくという形を取っていただきたいという要望です。どうやったら８月から、例えば２か月以内に全て給付する予定ですとなっているのであれば、その２点をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問・要望","question":"これは一つの要望という部分もあるのですけれども、事業者の方々に２０万円の枠を活用していただけると思うので、何か方策を考えているかどうか。この対象経費で５項目書いてあって、この３００件という見込みの内容が、どういった内容で３００件と見込んでいるのかという部分をお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"４つほど記載させていただきまして、チラシを作る予定ですので、ホームページなどは常に更新してやっていきたいと考えています。実際その７割部分は３００件はなかったのですけれども、ただ今回、少し上乗せして３００件という形の数字を出させていただいたところです。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、プレミアム付商品券について伺います。はその２点、全体でどれぐらいの販売の見込みがあるのか、あとは売れ残りの周知方法をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"８億円プラス２億４,０００万円ということで、一応見込みとしては、全部売れるだろうと考えています。数字は先ほど、２０％ではこれぐらい売れるだろうという見込みでやらせていただいておりますので、全部売れるだろうという形です。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"こちらがなぜ完売を見込んでいるのかを伺ったのは、２回に分けていると思うのですが、そうなると５万円かかるわけです。これは前例を伺いたいのが、同じような形で、まとめて上限５万円という形でやったことがあるのか。","respondent":"遠藤商業・ものづくり課長","answer":"場合によっては１０口の方が８口しか買えなかったという形のスキームになっております。今回は３割、３０％のプレミアムなので、その辺をうまく使ってご利用いただければです。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"商品券について１個だけ伺いたいのが、例えば私は５％のプレミアムだったら買わないという形で、おっしゃるとおり大きいと思うのです。転売対策をどう考えていらっしゃるのか、どういったプラスアルファでの強化を考えていらっしゃるのか、転売対策を伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"これも税金が投入されているものですので、転売については基本的にしないような形で、関係機関と連携していければと思っています。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問・要望","question":"本人確認はもちろん無理なので、いろいろと方策は考えていただきたいというのが、一つ要望で終わります。７１５万円が財産購入費ということで、何か補助金が出るのかどうか、こちらの改修費用について伺いたいです。","respondent":"古巻文化観光課長","answer":"改修費用につきましては、都市計画課の今年度予算でついているものです。特に補助金がということは聞いていませんけれども、都市計画課で本年度の事業として対処していくということで進めております。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらはロケ地等でも使われている大分古い建物ですが、史跡名勝として今後も活用できると思うので、ぜひともこちらを取得した後、活用をいかにするかというのが大事だと思うので、そちらに関して、何かいいアイデア等が出れば、補助金等もつけて活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"つる副委員長","kind":"質問・要望","question":"どのぐらいのスピード感で１日対応できるのかというところの確認です。もう１２月３１日で切らざるを得ないかもしれないけれども、今後のそうした部分においての対応の猶予があるかどうかというところの確認です。","respondent":"宮澤しながわ活力応援給付金担当課長、遠藤商業・ものづくり課長","answer":"返信用の色と違う色を採用しようと考えておりまして、送付する封筒につきましては、青色を基調とした封筒を検討しております。国の特別定額給付金の添付書類等を活用して迅速にやっていく予定ですが、現状では… こういう理由だということで書いていただければ、その辺につきましては、個別の実際の申請書を見てからという形になろうかと思います。","id":"exchange-035"},{"speaker":"つる副委員長","kind":"質問・要望","question":"委員会外で確認するのですが、私たちも質問されたときに、ご説明申し上げるのです。お子さんについての見解、そういうご質問を頂いたときに、そこを。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"４月２８日以降に生まれた子どもの基準日の特例ということで、給付対象とするところにつきましてです。財源の側面から見ると、そういったところを勘案して、引き続き申請日まで住民登録がある方とさせていただいたところです。","id":"exchange-036"},{"speaker":"松本委員","kind":"意見","question":"今調べたのですけれども、どちらも、点字については横浜市が封筒でやっていらっしゃいます。福岡市が４か国語で封筒をやっていたりするので、最後に補足させていただいて、賛成としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]},{"id":"topic-02","title":"第４２号議案 品川区手数料条例の一部を改正する条例","agenda":"第４２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今回、事務事業概要のときに、交付率といいますか、２０％と言われていたと思うのですけれども、以前はそんなになかったと思うのです。今後の申請の見込みといいますか、その辺はどのように考えているのかを伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"２０％にもう少しというところなのですけれども、これからまた先、これを使って何かをということがあるのではないか。今までのときより約３倍程度という形で対応しておりまして、ぜひ作っておこうという方が増えていらっしゃると考えております。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"ということは、面積に上限はないということで考えていいのですか。できないは、都の条例だと思うのですが、面積の上限というのはないということで考えていいのか尋ねました。","respondent":"稲田土木管理課長","answer":"担当者ですけれども、大体１,０００m2ぐらい、今までやってきたプロジェクションマッピングはそういう状況だったということは言っておりました。建物の壁とかに映すのが一般的なのでしょうから、大体そういう事例を参考にしているということでした。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"大体１,０００m2ぐらい、ないものということでいいのでしょうかということと、区は許可をするという立場になるのですか。すみません、手数料についても区が条例に基づいて徴収すると書いてありますけれども、区が許可を出すということでいいのか尋ねました。","respondent":"稲田土木管理課長","answer":"ただ、それが下りてきて、最終的には区が許可をするということになっておりますので、いずれにしましても、区が許可をしていくというものです。手数料の徴収も品川区で行います。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"届出制であって、届け出ればそれでオーケーということで、許可というものにならないと。東京都では自治体への届出を条件としているだけで、許可は得なくていいという議論がされているのですけれども、そうか尋ねました。","respondent":"稲田土木管理課長","answer":"公益性を有する場合は、許可申請が不要、届出だけでいいという内容になっております。それ以外のものについては許可が必要ですが、かなり細かな条件がいろいろありまして、それに適合してやっていくという状況です。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"その辺が考えられていなくて、運転者の幻惑などを想定したものではないという議論も、都の担当部署からも言われていたのです。本当に安全なのでしょうかという感覚が私はするのですけれども、その辺、区の考えを伺いたいと思います。","respondent":"稲田土木管理課長","answer":"これは条例の中に、景観とか周辺環境および安全性に配慮し、支障を及ぼさないものであるという大前提のようなものがありますので、交通事故を起こしたり、事故があったりしては本末転倒ですので、その辺は個々の状況等を事前にチェックしながらやるものになると思います。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"述べさせていただきたいのですが、どちらもですか。マイナンバーもプロジェクションも一緒の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"意見","question":"無理に推進するのではなく、立ち止まって見直すべきだと思いますので、マイナンバーについては反対です。そして安全性の確保されたものにしていくべきだと思いますので、それにつながる手数料条例ですので、反対しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"松本委員","kind":"意見","question":"特別定額給付金との関係で言ったら、あれはなぜホームレスが申請しづらいかというと、一つには重複の話も出てくると思います。これは解決できたのではないかと考えておりますので、そこを付言させていただいた上で、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40952,"voices":127}}]);
